(5254, 'CassiaCombat11', '[]', 'Disgusting!', 'Audio/Dialogue/NPC/Cassia/Cas_27_4C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5255, 'CassiaTowersRandom', '[]', 'Let''s see what this tower can really do.', 'Audio/Dialogue/NPC/Cassia/Cas_28_2A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5256, 'CassiaTowers1', '[]', 'Let''s see what this tower can really do.', 'Audio/Dialogue/NPC/Cassia/Cas_28_2B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5257, 'CassiaTowers2', '[]', 'Let''s see what this tower can really do.', 'Audio/Dialogue/NPC/Cassia/Cas_28_2C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5258, 'CassiaTowers3', '[]', 'Divine power!', 'Audio/Dialogue/NPC/Cassia/Cas_28_3A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5259, 'CassiaTowers4', '[]', 'Divine power!', 'Audio/Dialogue/NPC/Cassia/Cas_28_3B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5260, 'CassiaTowers5', '[]', 'Divine power!', 'Audio/Dialogue/NPC/Cassia/Cas_28_3C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5261, 'CassiaNewLane1', '[]', 'It''s put out new mycelium! ... New roots!', 'Audio/Dialogue/NPC/Cassia/Cas_29_1A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5262, 'CassiaNewLane2', '[]', 'It''s put out new mycelium! ... New roots!', 'Audio/Dialogue/NPC/Cassia/Cas_29_1B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5263, 'CassiaNewLane3', '[]', 'It''s put out new mycelium! ... New roots!', 'Audio/Dialogue/NPC/Cassia/Cas_29_1C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5264, 'CassiaNewLane4', '[]', 'The Blight is trying to spread!', 'Audio/Dialogue/NPC/Cassia/Cas_29_2A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5265, 'CassiaNewLane5', '[]', 'The Blight is trying to spread!', 'Audio/Dialogue/NPC/Cassia/Cas_29_2B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5266, 'CassiaNewLane6', '[]', 'The Blight is trying to spread!', 'Audio/Dialogue/NPC/Cassia/Cas_29_2C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5267, 'CassiaNewLane7', '[]', 'It''s branching, exile!', 'Audio/Dialogue/NPC/Cassia/Cas_29_3A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5268, 'CassiaNewLane8', '[]', 'It''s branching, exile!', 'Audio/Dialogue/NPC/Cassia/Cas_29_3B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5269, 'CassiaMonsterNearPump1', '[]', 'Those fiends are getting too close to my pump.', 'Audio/Dialogue/NPC/Cassia/Cas_30_1A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5270, 'CassiaMonsterNearPump2', '[]', 'You''re making me nervous.', 'Audio/Dialogue/NPC/Cassia/Cas_30_2A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5271, 'CassiaMonsterNearPump3', '[]', 'Do not let them reach the purification pump!', 'Audio/Dialogue/NPC/Cassia/Cas_30_3A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5272, 'CassiaMonsterNearPump4', '[]', 'Do not let them reach the purification pump!', 'Audio/Dialogue/NPC/Cassia/Cas_30_3B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5273, 'CassiaMonsterNearPump5', '[]', 'Do not let them reach the purification pump!', 'Audio/Dialogue/NPC/Cassia/Cas_30_3C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5274, 'CassiaSingCloseRandom', '[]', '<i>{Burning away our sins...}', 'Audio/Dialogue/NPC/CassiaSing/Cas_01_1A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5275, 'CassiaSingClose1', '[]', '<i>{Burning away our sins...}', 'Audio/Dialogue/NPC/CassiaSing/Cas_01_1B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5276, 'CassiaSingClose2', '[]', '<i>{Burning away our sins...}', 'Audio/Dialogue/NPC/CassiaSing/Cas_01_1C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
