(5283, 'CassiaSingFarRandom', '[]', '<i>{And the unrighteous were turned to ash... And the unrighteous were turned to ash...}', 'Audio/Dialogue/NPC/CassiaSing/Cas_31A.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5284, 'CassiaSingFar1', '[]', '', 'Audio/Dialogue/NPC/CassiaSing/Cas_31B.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5285, 'CassiaSingFar2', '[]', '', 'Audio/Dialogue/NPC/CassiaSing/Cas_31C.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5286, 'CassiaSingFar3', '[]', '<i>{Burning away our sins... Burning away our sins... Burning away our sins... Burning away our... }', 'Audio/Dialogue/NPC/CassiaSing/Cas_31D.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5287, 'CassiaSingFar4', '[]', '<i>{Cast your burning gaze to thine soul... Cast your burning gaze to thine soul...}', 'Audio/Dialogue/NPC/CassiaSing/Cas_31E.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
(5288, 'CassiaSingFar5', '[]', '<i>{And the unrighteous were turned to ash! And the unrighteous were turned to ash -- to ash!}', 'Audio/Dialogue/NPC/CassiaSing/Cas_31F.ogg', '', 0, 0, '', 1, 0, 1, '[396]', NULL, 0, 0, '[]', 100),
