(6000, 'OshabiGreetingHarvestReady4', '[]', 'The harvest is ready at last.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_D_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6001, 'OshabiGreetingHarvestReady5', '[]', 'To the Grove, Exile. A harvest awaits.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_E_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6002, 'OshabiGreetingHarvestReady6', '[]', 'Gather them quickly. A harvest is ready.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_A_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6003, 'OshabiGreetingHarvestReady7', '[]', 'Our garden swells with Lifeforce. Come.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_B_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6004, 'OshabiGreetingHarvestReady8', '[]', 'Our crop is ready. Return to the garden.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_C_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6005, 'OshabiGreetingHarvestReady9', '[]', 'The harvest is ready at last.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_D_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6006, 'OshabiGreetingHarvestReady10', '[]', 'To the Grove, Exile. A harvest awaits.', 'Audio/Dialogue/NPC/Oshabi/OSH_26_E_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6007, 'OshabiHighLevelFirstWildGreeting', '[]', 'You''ve found some seeds, Exile.', 'Audio/Dialogue/NPC/Oshabi/OSH_42_B.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6008, 'OshabiGardenWildGreeting', '[]', 'This way, Exile.', 'Audio/Dialogue/NPC/Oshabi/OSH_04.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6009, 'OshabiWhenPlantingRandom', '[]', 'Perhaps not as thrilling as killing someone in cold blood, but you must admit there is a satisfaction to be had.', 'Audio/Dialogue/NPC/Oshabi/OSH_29_A_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6010, 'OshabiWhenPlanting2', '[]', 'Giving something life can be nearly as enjoyable as taking it, yes?', 'Audio/Dialogue/NPC/Oshabi/OSH_29_B_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6011, 'OshabiWhenPlanting3', '[]', 'Have you ever considered trading the sword for the plow, Exile?', 'Audio/Dialogue/NPC/Oshabi/OSH_29_C_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6012, 'OshabiWhenPlanting4', '[]', 'Not too different from burying the dead, is it?', 'Audio/Dialogue/NPC/Oshabi/OSH_29_D_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6013, 'OshabiWhenPlanting5', '[]', 'You cannot pave a road with just one stone.', 'Audio/Dialogue/NPC/Oshabi/OSH_29_E_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6014, 'OshabiWhenPlanting6', '[]', 'Perhaps not as thrilling as killing someone in cold blood, but you must admit there is a satisfaction to be had.', 'Audio/Dialogue/NPC/Oshabi/OSH_29_A_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6015, 'OshabiWhenPlanting7', '[]', 'Giving something life can be nearly as enjoyable as taking it, yes?', 'Audio/Dialogue/NPC/Oshabi/OSH_29_B_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
