(6018, 'OshabiWhenPlanting10', '[]', 'You cannot pave a road with just one stone.', 'Audio/Dialogue/NPC/Oshabi/OSH_29_E_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6019, 'OshabiWhenHarvesting1', '[]', 'Put down the spawn.', 'Audio/Dialogue/NPC/Oshabi/OSH_30_A_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6020, 'OshabiWhenHarvesting2', '[]', 'We need not the fruit, just the juice.', 'Audio/Dialogue/NPC/Oshabi/OSH_30_B_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6021, 'OshabiWhenHarvesting3', '[]', 'Kill it Exile. Quickly.', 'Audio/Dialogue/NPC/Oshabi/OSH_30_C_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6022, 'OshabiWhenHarvesting4', '[]', 'Don''t let it make a mess.', 'Audio/Dialogue/NPC/Oshabi/OSH_30_D_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6023, 'OshabiWhenHarvesting5', '[]', 'Put down the spawn.', 'Audio/Dialogue/NPC/Oshabi/OSH_30_A_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
