(6027, 'OshabiWhenFightEnds1', '[]', 'Hmph.', 'Audio/Dialogue/NPC/Oshabi/OSH_31_A_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6028, 'OshabiWhenFightEnds2', '[]', 'I''ll get this cleaned up.', 'Audio/Dialogue/NPC/Oshabi/OSH_31_B_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6029, 'OshabiWhenFightEnds3', '[]', 'Plenty of fertiliser.', 'Audio/Dialogue/NPC/Oshabi/OSH_31_C_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6030, 'OshabiWhenFightEnds4', '[]', 'What a mess.', 'Audio/Dialogue/NPC/Oshabi/OSH_31_D_01.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
(6031, 'OshabiWhenFightEnds5', '[]', 'Hmph.', 'Audio/Dialogue/NPC/Oshabi/OSH_31_A_02.ogg', '', 0, 0, '', 0, 0, 1, '[402]', NULL, 0, 0, '[]', 100),
