(10998, 'EnvoyFinalConversationA', '[]', 'You force an intervention, Nomad. You have proved your might. You have proved your ignorance.', 'Audio/Dialogue/NPC/Envoy/Envoy_58_1_A.ogg', '', 0, 0, '', 1000, 0, 1, '[486]', NULL, 0, 0, '[]', 100),
(10999, 'EnvoyFinalConversationB', '[]', 'The Maven is a toddler, a nymph, a hatchling that has wandered too far from the nest. Were I to allow you to continue, it would surely call for its progenitor. Were I to allow you to continue, you would drag all into its gaping maw.', 'Audio/Dialogue/NPC/Envoy/Envoy_58_1_B.ogg', '', 0, 0, '', 1000, 0, 1, '[486]', NULL, 0, 0, '[]', 100);
