(11014, 'TrialmasterTutorialGreeting', '[]', 'Approach, Challenger.', 'Audio/Dialogue/NPC/TrialmasterWild/Tri_80_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11015, 'TrialmasterTutorialIntro', '[]', 'Many exiles have tested their skills here as of late. Face the trials of Chaos and pursue your fate. You might die here, now, or you might someday rival the gods themselves.', 'Audio/Dialogue/NPC/Trialmaster/Tri_81_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11016, 'TrialmasterTutorialAltarUnlocked', '[]', 'Make your choice.', 'Audio/Dialogue/NPC/Trialmaster/Tri_82_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11017, 'TrialmasterTutorialAltarClicked', '[]', 'Slay the waves of enemies. Simple enough.', 'Audio/Dialogue/NPC/Trialmaster/Tri_83_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11018, 'TrialmasterTutorialPlayerWalksAway', '[]', 'Not participating is itself a choice.', 'Audio/Dialogue/NPC/Trialmaster/Tri_84_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11019, 'TrialmasterTutorialPlayerLoses', '[]', 'Your potential remains unrealised.', 'Audio/Dialogue/NPC/Trialmaster/Tri_85_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11020, 'TrialmasterTutorialContinueOrStopOne', '[]', 'A favourable result. Now you face another choice: further commit to a more difficult challenge, or balk?', 'Audio/Dialogue/NPC/Trialmaster/Tri_86_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11021, 'TrialmasterTutorialStopChosen', '[]', 'The safe choice.', 'Audio/Dialogue/NPC/Trialmaster/Tri_87_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11022, 'TrialmasterTutorialContinueOrStopTwo', '[]', 'A choice of futures, as before. The next challenge will be even more difficult.', 'Audio/Dialogue/NPC/Trialmaster/Tri_88_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11023, 'TrialmasterTutorialStopChosenTwo', '[]', 'The expected choice.', 'Audio/Dialogue/NPC/Trialmaster/Tri_89_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11024, 'TrialmasterTutorialContinueOrStopThree', '[]', 'Do you wish to keep your fortunes, or continue in pursuit of greater riches?', 'Audio/Dialogue/NPC/Trialmaster/Tri_90_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11025, 'TrialmasterTutorialStopChosenThree', '[]', 'So be it, as disappointing as it is.', 'Audio/Dialogue/NPC/Trialmaster/Tri_91_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11026, 'TrialmasterTutorialFullWin', '[]', 'You play the game well, Challenger. Enjoy the fruits of your luck, and your skill. We shall meet again.', 'Audio/Dialogue/NPC/Trialmaster/Tri_92_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11027, 'TrialmasterSeeEachOtherAgainShout', '[]', 'The future holds further challenges. Count on it.', 'Audio/Dialogue/NPC/Trialmaster/Tri_93_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
