(11454, 'TrialmasterMoodBeginFiveOrMoreLosses6', '[]', 'Persistence is your only virtue.', 'Audio/Dialogue/NPC/Trialmaster/Tri_62C_02.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11455, 'TrialmasterMoodBeginFiveOrMoreLosses7', '[]', 'You know the goal is to succeed, yes?', 'Audio/Dialogue/NPC/Trialmaster/Tri_62D_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
