(11461, 'TrialmasterMoodBeginTwoToFourLosses3', '[]', 'Yes, come lose a trial. Productive.', 'Audio/Dialogue/NPC/Trialmaster/Tri_63B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11462, 'TrialmasterMoodBeginTwoToFourLosses4', '[]', 'Yes, come lose a trial. Productive.', 'Audio/Dialogue/NPC/Trialmaster/Tri_63B_02.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11463, 'TrialmasterMoodBeginTwoToFourLosses5', '[]', 'Yes, come lose a trial. Productive.', 'Audio/Dialogue/NPC/Trialmaster/Tri_63B_03.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11464, 'TrialmasterMoodBeginTwoToFourLosses6', '[]', 'Multiple losses. A touch shameful.', 'Audio/Dialogue/NPC/Trialmaster/Tri_63C_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(11465, 'TrialmasterMoodBeginTwoToFourLosses7', '[]', 'Multiple losses. A touch shameful.', 'Audio/Dialogue/NPC/Trialmaster/Tri_63C_02.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
