(11757, 'EnvoyRandomFinalSayingRandom', '[]', 'They... are coming.', 'Audio/Dialogue/NPC/Envoy/Envoy_Farewell_10.ogg', '', 0, 0, '', 1, 0, 1, '[485]', NULL, 0, 0, '[]', 100),
(11758, 'EnvoyRandomFinalSaying2', '[]', 'They... are coming.', 'Audio/Dialogue/NPC/Envoy/Envoy_Farewell_11.ogg', '', 0, 0, '', 1, 0, 1, '[485]', NULL, 0, 0, '[]', 100),
(11759, 'EnvoyRandomFinalSaying3', '[]', 'They... are coming.', 'Audio/Dialogue/NPC/Envoy/Envoy_Farewell_12.ogg', '', 0, 0, '', 1, 0, 1, '[485]', NULL, 0, 0, '[]', 100),
(11760, 'DannigOnExpeditionMap', '[]', 'Our expeditions are a private matter of honour. Let''s discuss this in your hideout instead.', 'Audio/Dialogue/NPC/Dannig/Dannig_38.ogg', '', 0, 0, '', 1, 0, 1, '[511,515]', NULL, 0, 0, '[]', 100),
(11761, 'TujenRandomMap', '[]', '[DNT] Random map exile!', '', '', 0, 0, '', 1, 0, 1, '[513,521]', NULL, 0, 0, '[]', 100),
(11762, 'TujenRareIntBoots', '[]', '[DNT] Rare int boots exile?', '', '', 0, 0, '', 1, 0, 1, '[513,521]', NULL, 0, 0, '[]', 100),
(11763, 'TujenRegretStack20', '[]', '[DNT] Stack of 20 regrets i think, exile.', '', '', 0, 0, '', 1, 0, 1, '[513,521]', NULL, 0, 0, '[]', 100),
(11764, 'TujenRegalStack5', '[]', '[DNT] Stack of 5 regals you''ll never use, exile?', '', '', 0, 0, '', 1, 0, 1, '[513,521]', NULL, 0, 0, '[]', 100),
(11765, 'TujenDivineStack4', '[]', '[DNT] Stack of 4 divines, exile!', '', '', 0, 0, '', 1, 0, 1, '[513,521]', NULL, 0, 0, '[]', 100),
(11766, 'TujenMirrorStack2', '[]', '[DNT] Oh my god it''s a stack of 2 mirrors exile', '', '', 0, 0, '', 1, 0, 1, '[513,521]', NULL, 0, 0, '[]', 100),
(11767, 'GamblerCurrencyVeryLowMagicRarityEquipment', '[]', 'No risk, no reward.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_40_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11768, 'GamblerCurrencyVeryLowRareRarityEquipment', '[]', 'That might be useful?', 'Audio/Dialogue/NPC/Gwennen/Gwennen_41_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11769, 'GamblerCurrencyUniqueCommentOne', '[]', 'It''s not nothing, at least!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_42_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11770, 'GamblerCurrencyUniqueCommentTwo', '[]', 'That''s something!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_43_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11771, 'GamblerCurrencyUniqueCommentThree', '[]', 'That looks intriguing!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_44_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11772, 'GamblerCurrencyUniqueCommentFour', '[]', 'You believed, and your belief paid off!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_45_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11773, 'GamblerCurrencyVeryLowDivineUniqueCommentOne', '[]', 'Wow! I don''t know what to make of that at all! But at least you got it cheap!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_46_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11774, 'GamblerCurrencyVeryLowHeadhunter', '[]', 'Congratulations! You hit the jackpot! I always knew you''d get lucky!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_47_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11775, 'GamblerCurrencyVeryLowEquipmentSpecialLow', '[]', 'Curious... at least you didn''t pay much for it.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_48_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11776, 'GamblerCurrencyVeryLowEquipmentSpecialMid', '[]', 'A decent payoff, I''d say.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_49_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11777, 'GamblerCurrencyVeryLowEquipmentSpecialHigh', '[]', 'Quite the interesting piece of equipment, that! And it came cheap!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_50_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11778, 'GamblerCurrencyLowMagicRarityEquipment', '[]', 'You get what you pay for, I suppose!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_51_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11779, 'GamblerCurrencyLowRareRarityEquipment', '[]', 'At least it''s pretty.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_52_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11780, 'GamblerCurrencyUniqueCommentFive', '[]', 'Hmm. Might be useful in certain situations.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_53_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11781, 'GamblerCurrencyUniqueCommentSix', '[]', 'A decent prize!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_55_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11782, 'GamblerCurrencyLowDivineUniqueCommentTwo', '[]', 'Glad you''ve taken that off my hands. I don''t like it.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_57_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11783, 'GamblerCurrencyLowHeadhunter', '[]', 'Amazing! I really should have charged more for that one!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_58_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11784, 'GamblerCurrencyLowEquipmentSpecialLow', '[]', 'Low risk, strange equipment. Just another day of gambling.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_59_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11785, 'GamblerCurrencyLowEquipmentSpecialMid', '[]', 'How intriguing! And it didn''t cost you much, either.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_60_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11786, 'GamblerCurrencyLowEquipmentSpecialHigh', '[]', 'Now that''s a decent payoff!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_61_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11787, 'GamblerCurrencyMediumMagicRarityEquipment', '[]', 'Better luck next time.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_62_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11788, 'GamblerCurrencyMediumRareRarityEquipment', '[]', 'You never know with that kind of equipment. Maybe somebody will trade you for it.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_63_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11789, 'GamblerCurrencyUniqueCommentSeven', '[]', 'I''m not sensing excitement from you on this one.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_64_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11790, 'GamblerCurrencyUniqueCommentEight', '[]', 'That looks very nice.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_67_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11791, 'GamblerCurrencyMediumDivineUniqueCommentThree', '[]', 'Artifacts related to these ''gods'' of yours make me wary...', 'Audio/Dialogue/NPC/Gwennen/Gwennen_68_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11792, 'GamblerCurrencyMediumHeadhunter', '[]', 'Yes! You did it! Luck favours you this day!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_69_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11793, 'GamblerCurrencyMediumEquipmentSpecialLow', '[]', 'Wraeclast has such strange equipment...', 'Audio/Dialogue/NPC/Gwennen/Gwennen_70_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11794, 'GamblerCurrencyMediumEquipmentSpecialMid', '[]', 'Looks like your belief in luck paid off.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_71_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11795, 'GamblerCurrencyMediumEquipmentSpecialHigh', '[]', 'You''re getting good at gambling!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_72_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11796, 'GamblerCurrencyHighMagicRarityEquipment', '[]', 'Ouch.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_73_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11797, 'GamblerCurrencyHighRareRarityEquipment', '[]', 'You really must believe harder.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_74_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11798, 'GamblerCurrencyUniqueCommentNine', '[]', '...neat.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_75_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11799, 'GamblerCurrencyUniqueCommentTen', '[]', 'Hmm. Expensive risk you took, but this might be... something?', 'Audio/Dialogue/NPC/Gwennen/Gwennen_76_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11800, 'GamblerCurrencyHighDivineUniqueCommentFour', '[]', 'Are you sure this ''divine'' gear is worth what you paid for it?', 'Audio/Dialogue/NPC/Gwennen/Gwennen_79_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11801, 'GamblerCurrencyHighHeadhunter', '[]', 'That seems rather useful, to put it mildly!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_80_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11802, 'GamblerCurrencyHighEquipmentSpecialLow', '[]', 'Strange equipment at high prices. That''s the beauty of gambling.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_81_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11803, 'GamblerCurrencyHighEquipmentSpecialMid', '[]', 'Not bad for the risk you took.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_82_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11804, 'GamblerCurrencyHighEquipmentSpecialHigh', '[]', 'High risk, high reward!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_83_01.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11805, 'GamblerCurrencyVeryHighHeadhunter', '[]', 'Did you just squeal with joy?', 'Audio/Dialogue/NPC/Gwennen/Gwennen_84_02.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11806, 'GamblerCurrencyVeryHighRareLeatherBeltWithLife', '[]', 'You didn''t believe hard enough. Better luck next time.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_85_02.ogg', '', 0, 0, '', 1, 0, 1, '[512,520,516]', NULL, 0, 0, '[]', 100),
(11807, 'GwennenTutorialShout', '[]', 'You there! Local! Come here!', 'Audio/Dialogue/NPC/Gwennen/Gwennen_01.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11808, 'GwennenTutorialIntro', '[]', 'I bet a yokel like yourself would be eager to see some explosions. Nevermind why we''re blowing things up just yet. We''ll get to that.' || char(13) || '
' || char(13) || '
I''ve gone ahead and marked the locations of likely treasures and dangers. Consider me magnanimous. You can choose what we uncover, since I''m eager to see what kind of luck you possess. I''ll wait back here. As far back as possible.' || char(13) || '
' || char(13) || '
Lay out a chain of devices. We''ll make a mighty fine display.', 'Audio/Dialogue/NPC/Gwennen/Gwennen_02.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11809, 'GwennenTutorialPlayerPlacesFirstExplosive', '[]', 'Try to go as far as you can with the detonation cord.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_03.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11810, 'GwennenTutorialPlayerWalksTooFarAway', '[]', 'Not that far!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_04.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11811, 'GwennenTutorialPlayerPlacesSecondExplosive', '[]', 'Further! Keep going. Away from me.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_05.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11812, 'GwennenTutorialPlayerPlacesThirdExplosive', '[]', 'All placed. Shall we light it up?', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_06.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11813, 'GwennenTutorialDetonating', '[]', 'I should also mention... this might unearth monsters!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_07.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11814, 'GwennenTutorialMonstersAppearing', '[]', 'You can take ''em!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_08.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11815, 'GwennenTutorialMoreMonstersAppearing', '[]', 'Go get ''em, local!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_09.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11816, 'GwennenTutorialAllMonstersDead', '[]', 'You did it?... you did it! Most of the locals I grab for this job don''t last long.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_10.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11817, 'GwennenTutorialTalkAfter', '[]', 'Hah, yes, I could have been more up front about the danger... but you see, people don''t take the job when I mention that the upturned ground is full of deadly creatures. It''s a mighty awful land you''ve got here, local. A wonder anyone survives at all. Though that does speak to why I''m here in the first place... but you''ll have to ask Dannig about that, if you find him.' || char(13) || '
' || char(13) || '
By the way, if you enjoy a bit of risk, I''ve got a few things I''ve unearthed that might be of interest to you...', 'Audio/Dialogue/NPC/Gwennen/Gwennen_11.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11818, 'GwennenTutorialPartingShoutForTutorialTwo', '[]', 'If you see Tujen, tell him I sent you!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen_12.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11819, 'GwennenTutorialPartingShout', '[]', 'I''ll finish up here. See you again soon!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_01.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11820, 'GwennenTutorialTwoShout', '[]', 'Found something special for you here, local!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_02.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11821, 'GwennenTutorialTwoIntro', '[]', 'Remnants of ancient civilisations abound on this continent. Apparently, some of the remnants still hold mysterious influences. It''s a bit of a risk to destroy one and release its energies, but the reward could be worth it.' || char(13) || '
' || char(13) || '
Everything unearthed after a remnant is destroyed comes up a little different. Why don''t you place an explosive device near that one over there? Let''s see what happens.', 'Audio/Dialogue/NPC/Gwennen/Gwennen2_03.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11822, 'GwennenTutorialPlayerPlacesExplosiveNotNearRemnant', '[]', 'Place an explosive near the remnant!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_04.ogg', '', 0, 0, '', 1, 4000, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11823, 'GwennenTutorialTwoFailure', '[]', 'This placement of explosives won''t scratch that remnant at all! Oh well, we''ll try again later.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_05.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11824, 'GwennenTutorialPlayerPlacesExplosiveNearRemnant', '[]', 'Good, that''ll do it.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_06.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11825, 'GwennenTutorialEnragedMonstersAppearing', '[]', 'I should also mention... this might enrage the monsters!', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_07.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11826, 'GwennenTutorialTwoAllMonstersDead', '[]', 'There you go, exile! Destroying remnants is a risky endeavour but you can clearly handle it.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_08.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11827, 'GwennenTutorialTwoTalkAfter', '[]', 'So it seems destroying ancient remnants alters everything we subsequently unearth, treasures and monsters both. It''s a gamble, and you know I''m always up for that. So long as you''re ready to handle the consequences... with violence.', 'Audio/Dialogue/NPC/GwennenWild/Gwennen2_09.ogg', '', 0, 0, '', 1, 0, 1, '[516,512,520]', NULL, 0, 0, '[]', 100),
(11828, 'DannigTrailerLookingAtExpedition', '[]', 'The translation''s tough on this one. This expedition''s Remembrancer was clearly a novice. Prosaic lists of landmarks passed on the trek... notable hills, rivers, a mountain range... he goes on at great length about the battles, though. Pages and pages of arbalest bolts ''finding purchase in the necks and hearts of exotically dressed shamblers.'' Young men were still the same bloodthirsty whelps thousands of years ago, it seems.' || char(13) || '
' || char(13) || '
Might be a Vaal site from that description, though he doesn''t go into detail about their clothing. The use of arbalests hints at Black Scythe work. There are a few locations that might fit the details from this logbook. What do you think?', 'Audio/Dialogue/NPC/Dannig/Dannig_52.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11829, 'DannigIntroGeneralWitch', '[1]', 'You''re naught but skin and bones, Exile, but you''ve made it this far. Clearly, you must have some talent. Care to lend your skills to a matter of honour?', 'Audio/Dialogue/NPC/Dannig/Dannig_01.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11830, 'DannigIntroGeneralScion', '[2]', 'You''re naught but skin and bones, Exile, but you''ve made it this far. Clearly, you must have some talent. Care to lend your skills to a matter of honour?', 'Audio/Dialogue/NPC/Dannig/Dannig_01.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
