(11834, 'DannigIntroGeneralTemplar', '[6]', 'You''re naught but skin and bones, Exile, but you''ve made it this far. Clearly, you must have some talent. Care to lend your skills to a matter of honour?', 'Audio/Dialogue/NPC/Dannig/Dannig_01.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11835, 'DannigIntroMarauder', '[0]', 'Ah, a fellow warrior! You and I must share tales of ancestral bravery around a campfire! But first, I have a request. A matter of honour. I believe it is something you are well-suited for.', 'Audio/Dialogue/NPC/Dannig/Dannig_02.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11836, 'DannigNotHelping', '[]', 'Time to earn your keep. You handle the fighting.', 'Audio/Dialogue/NPC/Dannig/Dannig_03.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11837, 'DannigApproachShoutRandom', '[]', 'Hail!', 'Audio/Dialogue/NPC/Dannig/Dannig_23_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
