(11884, 'DannigExplainsExchanging', '[]', 'Some relics are more important than others. If you''ve found anything from the Knights of the Sun, I''ll take those in exchange for what the others trade for.', 'Audio/Dialogue/NPC/Dannig/Dannig_25.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11885, 'DannigExplainsExchangingAlternate', '[]', 'My quest is to investigate the Knights of the Sun and acquire their relics. I''m willing to trade other less important relics for theirs.', 'Audio/Dialogue/NPC/Dannig/Dannig_26.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11886, 'DanningRerollInventoryRandom', '[]', 'Let''s see what else I''ve got...', 'Audio/Dialogue/NPC/Dannig/Dannig_27_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
(11887, 'DanningRerollInventory2', '[]', 'Let''s see what else I''ve got...', 'Audio/Dialogue/NPC/Dannig/Dannig_27_01_02.ogg', '', 0, 0, '', 1, 10000, 1, '[511,515,519]', NULL, 0, 0, '[]', 100),
