(13786, 'KalandraGenericEndingLine7', '[]', 'Ambition begets arrogance.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6C_01.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13787, 'KalandraGenericEndingLine8', '[]', 'Ambition begets arrogance.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6C_02.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13788, 'KalandraGenericEndingLine9', '[]', 'Ambition begets arrogance.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6C_03.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13789, 'KalandraGenericEndingLine10', '[]', 'We succeed, but remain lonely.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6D_01.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13790, 'KalandraGenericEndingLine11', '[]', 'We succeed, but remain lonely.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6D_02.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13791, 'KalandraGenericEndingLine12', '[]', 'We succeed, but remain lonely.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6D_03.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13792, 'KalandraGenericEndingLine13', '[]', 'Wisdom is the offspring of Suffering and Time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6E_01.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13793, 'KalandraGenericEndingLine14', '[]', 'Wisdom is the offspring of Suffering and Time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6E_02.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13794, 'KalandraGenericEndingLine15', '[]', 'Wisdom is the offspring of Suffering and Time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6E_03.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13795, 'KalandraWarbandsIntro', '[]', 'They have struggled for generations, but have forgotten why.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_7A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13796, 'KalandraWarbandsOutro', '[]', 'Vengeance is a closed loop.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_7B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13797, 'KalandraRogueExilesOutro', '[]', 'Some were exiled for good reason.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_8A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13798, 'KalandraRogueExilesIntro', '[]', 'They believe they are the heroes of their own journey.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_8B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13799, 'KalandraStrongboxesIntro', '[]', 'Treasure begets danger.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_9A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13800, 'KalandraStrongboxesOutro', '[]', 'Greed shall be the undoing of order.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_9B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13801, 'KalandraBreachOutro', '[]', 'They unite only in dreams... for now.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_10A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13802, 'KalandraBreachIntro', '[]', 'The Lords have unknowing followers among your kind.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_10B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13803, 'KalandraDeliriumOutro', '[]', 'He awaits a proper fool at journey''s end.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_11A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13804, 'KalandraDeliriumIntro', '[]', 'The Trickster believes himself a master of mirrors. Fah!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_11B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13805, 'KalandraAbyssIntro', '[]', 'The Clayshaper once took refuge here... for a time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_12A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13806, 'KalandraAbyssOutro', '[]', 'Often, it is our own creations that destroy us in the end.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_12B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13807, 'KalandraLegionIntro', '[]', 'Their ancestors await their souls. They will wait forever.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_13A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13808, 'KalandraLegionOutro', '[]', 'You are feeding it exactly what it desires...', 'Audio/Dialogue/NPC/Kalandra/Kalandra_13B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13809, 'KalandraShrinesIntro', '[]', 'I was here before gods, before religion. Trapped. Watching. Curious.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_14A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13810, 'KalandraShrinesOutro', '[]', 'The devout offer nothing at the altar. They only take, and destroy.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_14B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13811, 'KalandraShrines3', '[]', 'Not even occultists truly know the corruption inherent in these lands.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_14C.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13812, 'KalandraMetamorphIntro', '[]', 'Intrinsic Darkness is merely a shadow cast by the light of the soul.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_15A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13813, 'KalandraMetamorphOutro', '[]', 'The torturer should pray his search for truth never bears fruit...', 'Audio/Dialogue/NPC/Kalandra/Kalandra_15B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13814, 'KalandraHarbingerOutro', '[]', 'There can never be peace without understanding.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_16A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13815, 'KalandraHarbingerIntro', '[]', 'They have journeyed farther than you know.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_16B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13816, 'KalandraEssencesIntro', '[]', 'In death, they get to leave their prison.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_17A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13817, 'KalandraEssencesOutro', '[]', 'You would never touch another essence if you knew...', 'Audio/Dialogue/NPC/Kalandra/Kalandra_17B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13818, 'KalandraBestiaryOutro', '[]', 'The Beastmaster once found his way here on a hunt. He is... very strange.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_18A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13819, 'KalandraBestiaryIntro', '[]', 'I used to love hunting...', 'Audio/Dialogue/NPC/Kalandra/Kalandra_18B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13820, 'KalandraExpeditionOutro', '[]', 'Their kind and yours have much in common.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_19A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13821, 'KalandraExpeditionIntro', '[]', 'They come from beyond the sight of the Lake. They are a mystery even to me.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_19B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13822, 'KalandraBeyondOutro', '[]', 'You would lose all hope if you truly understood.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_20A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13823, 'KalandraBeyondIntro', '[]', 'She wanders still, forever fleeing, forever burdened by guilt.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_20B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13824, 'KalandraTormentIntro', '[]', 'Have you ever met a lost soul, consumed by its own sorrow?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_21A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13825, 'KalandraTormentOutro', '[]', 'Their spirits are imprisoned, forever harrowed by their own misdeeds.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_21B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13826, 'KalandraDelveOutro', '[]', 'An incendiary light at the end of the tunnel, leading only to madness.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_22A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13827, 'KalandraDelveIntro', '[]', 'Prospero oversees all treasures unearthed from the depths.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_22B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13828, 'KalandraHeistMonstersIntro', '[]', 'Fools seek to make the power of this Lake their own. They will crack the world.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_23A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13829, 'KalandraHeistMonstersOutro', '[]', 'Qotra meddles with forces she does not understand, and can never master.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_23B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13830, 'KalandraUntaintedParadiseOutro', '[]', 'There was a time when all of Wraeclast was pure and untainted.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_24A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13831, 'KalandraUntaintedParadiseIntro', '[]', 'A vision of long ago...', 'Audio/Dialogue/NPC/Kalandra/Kalandra_24B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13832, 'KalandraFishingOutro', '[]', 'In time, all questions shall find their answer.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_25A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13833, 'KalandraFishingIntro', '[]', 'The Master Fisherman once fished at this Lake. He... should not have done that.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_25B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13834, 'KalandraCraftingRoomIntro', '[]', 'The lake is a forge beyond all others.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_26A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13835, 'KalandraCraftingRoomOutro', '[]', 'Greed is the path to power... and ruin.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_26B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13836, 'KalandraAtACertainDepthA', '[]', 'You trace symbols in the sands of time, but do not comprehend their significance.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_27A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13837, 'KalandraAtACertainDepthB', '[]', 'The path ahead lies untouched, and unclear.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_27B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13838, 'KalandraAtACertainDepthC', '[]', 'The future is uncertain, refracted into a haze of spectra without clarity.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_27C.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13839, 'KalandraEnteringMaximumDepthRandom', '[]', 'The path ahead fades into obscurity... as may you.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_28A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13840, 'KalandraEnteringMaximumDepth2', '[]', 'Darkness descends. I doubt even a soul such as yours can illuminate it.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_28B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13841, 'EvilandraMetaProgressionInvasionStartRandom', '[]', 'Gloom overshadows the horizon, Wanderer.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_29A.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13842, 'EvilandraMetaProgressionInvasionStart2', '[]', 'Show me what you are truly made of.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_29B.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13843, 'EvilandraMetaProgressionInvasionStart3', '[]', 'Another human in pursuit of power. You''re not special.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_29C.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13844, 'EvilandraMetaProgressionInvasionStart4', '[]', 'You are meddling in forces beyond your understanding!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_29D.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13845, 'EvilandraSkillsRandom', '[]', 'I doubt you have the fortitude to face their reflections.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_30A.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13846, 'EvilandraSkills2', '[]', 'An imperfect simulacrum shows no mercy.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_30B.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13847, 'EvilandraSkills3', '[]', 'Dark reflection!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_30C.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13848, 'EvilandraSkills4', '[]', 'Raw creation!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_30D.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13849, 'EvilandraSkills5', '[]', 'Forged likeness!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_30E.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13850, 'EvilandraSkills6', '[]', 'Duplicate!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_30F.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13851, 'EvilandraMetaProgressionInvasionEndRandom', '[]', 'Fah!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31B.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13852, 'EvilandraMetaProgressionInvasionEnd2', '[]', 'I have forever. Can you say the same?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31C.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13853, 'EvilandraMetaProgressionInvasionEnd3', '[]', 'Eventually, you will fall.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31D.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13854, 'EvilandraMetaProgressionInvasionEnd4', '[]', 'It is only a matter of time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31E.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13855, 'KalandraOnPlayerDeathRandom', '[]', 'Death is not the worst fate this lake can inflict.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_32A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13856, 'KalandraOnPlayerDeath2', '[]', 'Have no fear. Another will continue in your place...', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_32B.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13857, 'EvilandraOnPlayerDeathRandom', '[]', 'One step closer...', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_33A.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13858, 'EvilandraOnPlayerDeath2', '[]', 'Foolish creature!', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_33B.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13859, 'EvilandraEndgameRandom', '[]', 'Who do you think you are?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34A.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13860, 'EvilandraEndgame2', '[]', 'Who do you think I am?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34B.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13861, 'EvilandraEndgame3', '[]', 'You have no idea what forces you toy with.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34C.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13862, 'EvilandraEndgame4', '[]', 'I cannot let you leave here!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34D.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13863, 'EvilandraEndgame5', '[]', 'End of all hope!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34E.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13864, 'EvilandraEndgame6', '[]', 'You must be destroyed!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34F.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13865, 'EvilandraEndgame7', '[]', 'You are a flawed creation!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34G.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13866, 'EvilandraEndgame8', '[]', 'Neither of us will ever leave this place.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34H.ogg', '', 0, 0, '', 1, 0, 1, '[544]', NULL, 0, 0, '[]', 100),
(13867, 'EvilandraEndgameQuestRandom', '[]', 'You seek to shape this world to further your own goals. We are not unalike.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31A.ogg', '', 0, 0, '', 1, 0, 1, '[543]', NULL, 0, 0, '[]', 100),
(13868, 'KalandraHideoutCommentRandom', '[]', 'Wisdom and patience walk as one.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_5A_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13869, 'KalandraHideoutComment2', '[]', 'The wind spoke of your approach.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_3A_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13870, 'KalandraHideoutComment3', '[]', 'Secrets do not reveal themselves easily.', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_4B_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13871, 'KalandraHideoutComment4', '[]', 'Wisdom is the offspring of Suffering and Time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_6E_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13872, 'KalandraHideoutComment5', '[]', 'Have you ever contemplated eternity?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_5C_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13873, 'KalandraHideoutComment6', '[]', 'One day, you will fly.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_5D_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13874, 'KalandraHideoutComment7', '[]', 'Time is my oldest enemy.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_5E_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13875, 'KalandraHideoutComment8', '[]', 'Where you are going depends on where you have been.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_5F_01.ogg', '', 0, 0, '', 1, 0, 1, '[545]', NULL, 0, 0, '[]', 100),
(13876, 'EvilandraHideoutCommentRandom', '[]', 'I have forever. Can you say the same?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31C.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13877, 'EvilandraHideoutComment2', '[]', 'Gloom overshadows the horizon, Wanderer.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_29A.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13878, 'EvilandraHideoutComment3', '[]', 'One step closer...', 'Audio/Dialogue/NPC/KalandraGlyph/Kalandra_33A.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13879, 'EvilandraHideoutComment4', '[]', 'Another human in pursuit of power. You''re not special.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_29C.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13880, 'EvilandraHideoutComment5', '[]', 'Eventually, you will fall.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31D.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13881, 'EvilandraHideoutComment6', '[]', 'It is only a matter of time.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31E.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13882, 'EvilandraHideoutComment7', '[]', 'Who do you think I am?', 'Audio/Dialogue/NPC/Kalandra/Kalandra_34B.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13883, 'EvilandraHideoutComment8', '[]', 'You seek to shape this world to further your own goals. We are not unalike.', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31A.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13884, 'EvilandraHideoutFlyAway', '[]', 'Fah!', 'Audio/Dialogue/NPC/Kalandra/Kalandra_31B.ogg', '', 0, 0, '', 1, 0, 1, '[546]', NULL, 0, 0, '[]', 100),
(13885, 'MelPetIdleRandom', '[]', '', 'Audio/Dialogue/NPC/Mel/Idle1.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13886, 'MelPetIdle2', '[]', '', 'Audio/Dialogue/NPC/Mel/Idle2.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13887, 'MelPetIdle3', '[]', '', 'Audio/Dialogue/NPC/Mel/Idle3.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13888, 'MelPetDismiss', '[]', '', 'Audio/Dialogue/NPC/Mel/Dismissed.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13889, 'MelPetDivineDrop', '[]', '', 'Audio/Dialogue/NPC/Mel/DropDivine.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13890, 'MelPetToHideout', '[]', '', 'Audio/Dialogue/NPC/Mel/EnterHideout.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13891, 'MelPetRareKill', '[]', '', 'Audio/Dialogue/NPC/Mel/KillRare.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13892, 'MelPetMirrorDrop', '[]', '', 'Audio/Dialogue/NPC/Mel/DropMirror.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13893, 'MelPetEmblemDrop', '[]', '', 'Audio/Dialogue/NPC/Mel/DropEmblem.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13894, 'MelPetPlayerDeath', '[]', '', 'Audio/Dialogue/NPC/Mel/PlayerDeath.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13895, 'MelPetSummon', '[]', '', 'Audio/Dialogue/NPC/Mel/Summoned.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13896, 'MelPetUniqueKill', '[]', '', 'Audio/Dialogue/NPC/Mel/KillRare.ogg', '', 0, 0, '', 1, 0, 1, '[559]', NULL, 0, 0, '[]', 100),
(13897, 'CadiroOnChaosOrb1', '[]', 'You know... I thought about making a deal with Chaos, but the price was too high. Prospero is a much better master. ', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13898, 'CadiroOnChaosOrb2', '[]', 'It''s been well over a century since I''ve bargained with the entity known as Chaos.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13899, 'CadiroOnDivineOrb1', '[]', 'I see you''ve got a Divine Orb there. Ah, that would make a fine addition to the Perandus cache...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13900, 'CadiroOnDivineOrb2', '[]', 'I see you''ve got a Divine Orb there. One of the most coveted currencies in the realm, to be sure.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13901, 'CadiroOnExaltedOrb1', '[]', 'An Exalted Orb? These used to be worth a lot more, you know.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13902, 'CadiroOnExaltedOrb2', '[]', 'Exalted Orbs were once revered by the people of Wraeclast, celebrated in pure exaltation. But now that the ceremonies have ceased, their worth is waning.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13903, 'CadiroOnSacredOrb1', '[]', 'A Sacred Orb? A considerably rare piece of currency. ', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13904, 'CadiroOnSacredOrb2', '[]', 'A Sacred Orb? Best left to the highly experienced.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13905, 'CadiroOnVaalOrb1', '[]', 'I don''t deal in currency I don''t understand.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13906, 'CadiroOnVaalOrb2', '[]', 'I don''t know what that piece of currency is... and honestly, it looks unnerving.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13907, 'CadiroOnMirrorOfKalandra1', '[]', 'Rumour has it that Kalandra is an ancient being, eternally trapped in a lake that exists outside Wraeclast, possessing the body of an owl and the head of a human. Sounds a bit ridiculous to me.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13908, 'CadiroOnMirrorOfKalandra2', '[]', 'You have a Mirror of Kalandra? An exceptionally rare find. I''ve only ever seen one before, and I''ve seen almost everything.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13909, 'CadiroOnRoguesMarker1', '[]', 'A Rogue''s Marker? That will take you straight to a den of thieves. Can''t say I''m affiliated with common scoundrels, but I know a discerning eye when I see one. ', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13910, 'CadiroOnRoguesMarker2', '[]', 'Rogue''s Markers? I hear those will buy you all kinds of mischief in the Rogue Harbour.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13911, 'CadiroOnSoulTaker1', '[]', 'Soul Taker... It''s rumoured that axe claims the souls of its victims. ', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13912, 'CadiroOnSoulTaker2', '[]', 'Soul Taker... It''s rumoured that axe chills the souls of its victims.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13913, 'CadiroOnActum', '[]', 'You''re not particularly bright, are you? But I''d rather not get on your bad side while you''re wielding that... thing.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_09.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13914, 'CadiroOnKingmaker', '[]', 'A weapon symbolising pure rebellion. I''d be careful with the sharp end, if I were you. You might end up overthrowing an empire.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_10.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13915, 'CadiroOnDoomfletch', '[]', 'It''s said that arrows loosed from Doomfletch channel the primordial elements themselves.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_11.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13916, 'CadiroOnIronCommander', '[]', 'Ah, I remember when entire legions were commanded by the Eternal holding that bow...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_12.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13917, 'CadiroOnTheGluttonousTide', '[]', 'Oh, to lose oneself in gorging upon the riches of a crumbling empire... It wasn''t until I entered the service of Prospero that I began to relax a little.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_13.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13918, 'CadiroOnReachOfTheCouncil', '[]', 'There is immense power in unity. Never forget this. A lone Undying is as mindless as an automaton, but a legion of Undying is a force to be reckoned with.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_14.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13919, 'CadiroOnWindripper', '[]', 'It is said that Windripper contains the very essence of the tempests themselves.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_15.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13920, 'CadiroOnLawOfTheWilds', '[]', 'The Law of the Wilds... an inevitable strengthening process in which the powerful are rewarded, and the weak are exterminated.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_16.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13921, 'CadiroOnArakaalisFang', '[]', 'Make no mistake, my Azmeri ancestors worshipped Arakaali long before the Vaal did, although I''m not entirely sure why. She was hardly a goddess of love or fertility; no, she was naught but a predator, ensnaring her victims in silk and sedating them with venom.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_17.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13922, 'CadiroOnTheHiddenBlade', '[]', 'The Hidden Blade is aptly named. Your enemies won''t know what hit them.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_18.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13923, 'CadiroOnSongOfTheSirens', '[]', 'The Song of the Sirens... almost as alluring as the clinking of gold coins in a nobleman''s pocket. And just as elusive...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_19.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13924, 'CadiroOnReefbane', '[]', 'Only a fool goes looking for a fortune at the bottom of a lake.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_20.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13925, 'CadiroOnMjolner', '[]', 'An almighty mace. I hope your foes enjoy the calm before the storm.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_21.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13926, 'CadiroOnTrypanon', '[]', 'It''s a little odd to see you wielding the Trypanon, given that it once resided in the Perandus stronghold. Icius was always a little wary of it, given its, ahem, previous applications...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_22.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13927, 'CadiroOnMarohiErqi', '[]', 'Ah yes, Marohi Erqi. It once fell into the hands of the Perandus family while we were on a brief excursion to the Karui Archipelago.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_23.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13928, 'CadiroOnAtzirisRule', '[]', 'Atziri''s Rule! A leftover relic from the Vaal Empire. As formidable a staff as the Vaal Queen herself.' || char(13) || '
', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_24.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13929, 'CadiroOnPledgeOfHands', '[]', 'It''s ironic that Queen Atziri''s advisor placed such high value on forming alliances, given that the Queen''s subjects were being sacrificed to power the Vaal empire...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_25.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13930, 'CadiroOnVarunastra', '[]', 'Varunastra... Another relic that was within the grasp of our family for a time. Yet now you brandish it, as if ignorant of its true value...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_26.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13931, 'CadiroOnTheSaviour', '[]', 'History never clarifies who is the saviour and who is the tyrant.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_27.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13932, 'CadiroOnParadoxica', '[]', 'Ah yes, Paradoxica. One of many relics that the Order of the Djinn fought to protect. They thought they operated in secret, but Perandus coin unveils all secrets in time.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_28.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13933, 'CadiroOnCosprisMalice', '[]', 'Never before have I encountered a weapon that chills the very air around it. If only I were still in the manor, I''d have one of the servants light a fire...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_29.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13934, 'CadiroOnStarforge', '[]', 'You''ve stumbled upon old Starforge, hmm? It''s said that this blade was forged by the Order of the Djinn and given to the Watchers of Decay, who used it to seal away the Elder. Not quite sure how it ended up in your possession, but wield it with caution.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_30.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13935, 'CadiroOnVoidBattery', '[]', 'Void Battery – a hideous instrument used for a variety of unpleasant ends. It was a favourite tool of Inquisitor Maligaro. He was a very nasty man.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_31.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13936, 'CadiroOnGreedsEmbrace', '[]', 'Greed''s Embrace gleams golden even in the evening light, which is fitting, given the wealth of currency it attracts. Needless to say, I am rather fond of this one.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_32.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13937, 'CadiroOnVentorsGamble', '[]', 'Bear in mind that even the most perilous of risks can be worth taking, given the level of calculation done prior.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_33.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13938, 'CadiroOnLioneyesVision', '[]', 'Ah, you''re wearing the platemail of that old sod. Marceus Lioneye had about as much military vision as he did actual sight, which is to say, very little. He lost Lioneye''s Watch to a siege by savages... A colossal failure.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_34.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13939, 'CadiroOnKaomsHeart', '[]', 'Kaom''s Heart? Rotten to the core. I genuinely can''t believe that madman commanded an army... ruled through barbarism and coercion, no doubt.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_35.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13940, 'CadiroOnTabulaRasa', '[]', 'Are you encased in a white sheet? Oh, I see. You''re wearing Tabula Rasa. Suffice it to say, you blend in. You could be anything.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_36.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13941, 'CadiroOnDiallasMalefaction', '[]', 'Ah... Dear Dialla. So intent on serving Malachai to the bitter end. Once upon a time, she was one of Chitus'' mistresses, but her lustre didn''t last. He turned her over to a thaumaturgist many times, and ultimately she fell into Malachai''s hands – which led to all those dreadful gem implants...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_37.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13942, 'CadiroOnShavronnesWrappings', '[]', 'What on Earth are you wearing? That gaudy old robe... Ah, I actually recognise it as Shavronne''s. Her attire became more lurid and twisted as her mind grew more corrupted.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_38.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13943, 'CadiroOnDaressosDefiance', '[]', 'Daresso''s Defiance... A fine piece of craftsmanship, although it didn''t get him very far. His fate is one I wouldn''t wish upon my worst enemy.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_39.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13944, 'CadiroOnVollsProtector', '[]', 'I see you''re wearing Voll''s Protector. Needless to say, I''m not overly fond of Voll, who spearheaded the revolution to overthrow my nephew''s empire. The Purity Rebellion culminated in Chitus'' death, and Voll is predominantly to blame.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_40.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13945, 'CadiroOnGeofrisSanctuary', '[]', 'Ah, I see you''ve got Geofri''s ringmail. That man was one of Voll''s lackeys, forever plotting and scheming alongside him. I do commend him for having a hand in Inquisitor Maligaro''s downfall, though.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_41.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13946, 'CadiroOnShroudOfTheLightless', '[]', 'The Shroud of the Lightless is immeasurably ancient, stemming from a time when none but the Lightless prevailed. Repugnant creatures who infested Prospero''s domain with their wickedness.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_42.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13947, 'CadiroOnFarrulsFur', '[]', 'Furs blessed by an Ezomyte goddess? I''d wash those before you wear them. The Ezomytes are a primitive breed, yet they fancy themselves as romantic poets. Make no mistake: what they lack in eloquence, they make up for with sheer brutality.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_43.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13948, 'CadiroOnTheSquire', '[]', 'I see you''re using a shield as your squire. Do you really hate people that much? You must be quite the misanthrope... After all, you are drenched in the blood of your enemies.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_44.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13949, 'CadiroOnLycosidae', '[]', 'Careful now. An apex predator such as yourself might soon become the prey.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_45.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13950, 'CadiroOnTukohamasFortress', '[]', 'Tukohama''s Fortress... This is said to be a relic taken from the very walls of his abode. What kind of brute would vandalise his own home to make a shield? Well, I suppose it wasn''t a manor...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_46.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13951, 'CadiroOnCrestOfPerandus', '[]', 'Now there''s a shield I recognise, emblazoned with my family crest. "With piety and justice"... it''s a shame that Piety''s misdemeanours tainted that motto for us permanently.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_47.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13952, 'CadiroOnEmperorsVigilance', '[]', 'One of the finest kite shields I''ve ever had the pleasure of laying eyes upon – and an aptly named one. Emperor Chitus was forever vigilant, only taking calculated risks which he knew would fortify his position. I suppose it must run in the family, heh.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_48.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13953, 'CadiroOnMahuxotlsMachination', '[]', 'Mahuxotl''s Machination. An enigmatic shield, to be sure, imbued with the darkest of Vaal magics by the Banished Architect himself.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_49.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13954, 'CadiroOnAegisAurora', '[]', 'The Aegis Aurora? That''s a mighty fine shield you''ve got there. If Chitus had had a shield like that, things might have gone differently.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_50.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13955, 'CadiroOnMagnaEclipsis', '[]', 'Ah, the Magna Eclipsis. I hear it glows more brightly during a solar eclipse.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_51.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13956, 'CadiroOnHeadhunter', '[]', 'Oho, a mighty Headhunter! I''m <i>{so} impressed. Try to duck when the brain fragments splatter everywhere, you wouldn''t want to sully your armour.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_52.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13957, 'CadiroOnMageblood', '[]', 'Who needs Mageblood when you have liquid gold in your veins?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_53.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13958, 'CadiroOnUmbilicusImmortalis', '[]', 'The Umbilicus Immortalis. Icius was fond of this one. He spent hours poring over it, trying to determine the origin of its arcane properties. He couldn''t understand why your wounds seem to heal over when you wear it.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_54.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13959, 'CadiroOnPerandusSignet', '[]', 'Ah, the Perandus Signet! How could I not recognise this fine piece of craftsmanship? I do miss dear old Medici... he was an outstanding advisor, and we devised many clever plots together to bolster the wealth of the Treasury.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_55.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13960, 'CadiroOnKaomsSign', '[]', 'Word has it that Kaom saw this ring as a sign for him to lead his people to Wraeclast, although I wish he hadn''t.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_56.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13961, 'CadiroOnMalachaisArtifice', '[]', 'Malachai was a treacherous old bastard, but he certainly knew how to master the thaumaturgical arts. It''s said that this ring was one of many instruments he used to manipulate virtue gems.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_57.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13962, 'CadiroOnShavronnesRevelation', '[]', 'Shavronne''s Revelation? Ha. Perhaps if Shavronne had truly seen the light, she wouldn''t have been so easily slain.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_58.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13963, 'CadiroOnKaomsSpirit', '[]', 'The Karui Way preaches a number of fallacies, all dutifully upheld by its ignorant followers. Kaom was arguably its strongest proponent... but if he had truly been a traditionalist, he wouldn''t have murdered his own army.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_59.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13964, 'CadiroOnAnglersPlait', '[]', 'Best I not speak on this one...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_60.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13965, 'CadiroOnRomirasBanquet', '[]', 'Romira''s Banquet? Ugh. Romira Phrecian, the absolute savage, fed his wife''s two sons to her during that famed banquet. It was an act of vengeance, since her sons were sired by his brother.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_61.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13966, 'CadiroOnTriumvirateAuthority', '[]', 'It''s said that the Triumvirate Authority is imbued with the sigil of the god Yaomac – the shepherd of Vaal souls, and the arbiter of the balance of the seasons. Three unique blessings are conferred by each of Yaomac''s three serpentine heads.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_62.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13967, 'CadiroOnBadgeOfTheBrotherhood', '[]', 'It''s strange to see you wearing a Badge of the Brotherhood. The Perandus family are no strangers to the Brotherhood of Silence. Indeed, we have hired their services on many occasions...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_63.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13968, 'CadiroOnHyrrisTruth', '[]', 'Hyrri''s Truth? Her arrows may have struck true, but she was fighting for the wrong cause.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_64.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13969, 'CadiroOnStoneOfLazhwar', '[]', 'Ah, the Stone of Lazhwar. Lazhwar was an unmistakably great mind of our time. Indeed, many of his ideas were stolen by Malachai and used to construct the Eternal Laboratory. It''s a shame that Malachai had a hand in his downfall.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_65.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13970, 'CadiroOnAtzirisFoible', '[]', 'I see you''re wearing Atziri''s Foible. Even the Queen''s advisors could recognise her folly. You cannot force your people into sacrificing themselves and expect there to be no consequences.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_66.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13971, 'CadiroOnDaressosSalute', '[]', 'Ah yes, Daresso''s Salute. An amulet with history behind it. Daresso wore this into the arena many times during his glory days.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_67.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13972, 'CadiroOnShapersSeed', '[]', 'The Shaper''s Seed is one of the oldest amulets of all time, emerging from a primal landscape without form.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_68.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13973, 'CadiroOnVictariosAcuity', '[]', 'Victario''s Acuity? He may have had a sharp wit, but he wasn''t perspicacious enough to evade the Cataclysm.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_69.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13974, 'CadiroOnEyeOfChayula', '[]', 'You''re wearing the Eye of Chayula? A truly horrifying entity. He watches the dreams of the unwary, and the willing...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_70.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13975, 'CadiroOnUulNetolsVow', '[]', 'Uul-Netol''s Vow? I''ve no idea what her vow was, but it was no doubt something nightmarish.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_71.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13976, 'CadiroOnMaligarosCruelty', '[]', 'Maligaro was cruel, indeed. To never feel love, or remorse, or think of the consequences... This was Maligaro through and through. I would hesitate to think of what atrocities he would commit if he were still alive.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_72.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13977, 'CadiroOnStarOfWraeclast', '[]', 'Ah, The Star of Wraeclast. Daresso gave that necklace to Merveil as a token of his love, and her voice became melodic and pleasing to the ear. Little did he know that it would turn her mind and body into something truly grotesque, ultimately mutating her into a hideous siren – and so Daresso left her, and she pined for the love she''d lost, and fed sailors to her offspring.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_73.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13978, 'CadiroOnVollsDevotion', '[]', 'Voll''s Devotion? Bah! He was devoted to a cause that was far less pure than Victario''s writings would have anyone believe.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_74.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13979, 'CadiroOnHinekorasSight', '[]', 'Hinekora''s Sight, eh? They say all are welcome in Hinekora''s eternal home, but I honestly have no desire to go there.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_75.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13980, 'CadiroOnAulsUprising', '[]', 'Ah, Aul''s Uprising. My nephew was a fine leader, but he could''ve learned a thing or two from Aul. It''s said that Aul, the Crystal King, was once a slave who quarried stone, and he ascended to power predominantly through his leadership. He earned the respect of the people. Chitus could have worked harder to do the same.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_76.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13981, 'CadiroOnEyeOfInnocence', '[]', 'The Eye of Innocence, huh? Not such a fitting name, given that his gaze incinerated a group of townspeople. Nothing innocent about it.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_77.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13982, 'CadiroOnLeadershipsPrice', '[]', 'Chitus knew the price of leadership better than anyone. He readily made use of his diplomacy, cunning, and all of the resources at his disposal. But alas, it was not enough to save his life.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_78.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13983, 'CadiroOnTheAscetic', '[]', 'How does asceticism lead to more wealth? That makes no sense!', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_79.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13984, 'CadiroOnBiscosCollar', '[]', 'To have a canine at your heel is to have companionship that is almost as valuable as gold. Almost, but not quite.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_80.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13985, 'CadiroOnEmpiresGrasp', '[]', 'Ah, Empire''s Grasp! My nephew, Chitus, wore these into combat. He was a fine swordsman, and a formidable enemy.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_81.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13986, 'CadiroOnAtzirisAcuity', '[]', 'Atziri''s Acuity? She didn''t exactly have an abundance of it. In her narcissism and pursuit of eternal youth, innumerable lives were lost... and she couldn''t escape the Cataclysm that was likely her own doing.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_82.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13987, 'CadiroOnDoryanisFist', '[]', 'Doryani''s Fist, hmm? This weapon seems to weave its way in and out of history...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_83.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13988, 'CadiroOnVerusosBatteringRams', '[]', 'Ah, Veruso''s Battering Rams. I''m rather fond of dear old Tarcus – may he rest in peace. He founded our hometown of Sarn, where the Perandus family first established their mercantile presence.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_84.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13989, 'CadiroOnMaligarosVirtuosity', '[]', 'Maligaro''s Virtuosity? He wasn''t the most virtuous of individuals, though I suppose the gloves are named after his penchant for virtue gems. He was a masterful thaumaturgist, there''s no doubt about it.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_85.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13990, 'CadiroOnKalisasGrace', '[]', 'That''s a rather elegant pair of gloves. Kalisa''s Grace, if I''m not mistaken. Kalisa Maas, the Prima Donna of Sarn, was the finest opera singer in all of Wraeclast, partly due to the corrupted gem that was implanted in her throat. That very same gem was later set into the Star of Wraeclast – the necklace that transformed Merveil into a monster.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_86.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13991, 'CadiroOnGripOfTheCouncil', '[]', 'I don''t believe any ever truly leave the Pale Council, not even in death. They have the means to prolong life far beyond the natural order.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_87.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13992, 'CadiroOnDoedresMalevolence', '[]', 'Doedre''s Malevolence... An aptly named pair of gloves, for her malevolence knew no bounds. Even when her tongue was removed by Maligaro, she still managed to find new methods of spellcasting to continue torturing her subjects.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_88.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13993, 'CadiroOnHandsOfTheHighTemplar', '[]', 'The Templars consider themselves to be men of faith, but even the most pious of men are amenable to a little coin when it suits them. We''ve had some dealings in the past...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_89.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13994, 'CadiroOnOndarsClasp', '[]', 'Ondar! That traitorous, treacherous bastard! How dare you flounce about here wearing the gloves of the man who slew the Emperor!', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_90.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13995, 'CadiroOnMalachaisMark', '[]', 'Malachai certainly left his mark upon Wraeclast. There are still remnants of his evil plaguing the continent. We may never truly know a land untouched by the Cataclysm.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_91.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13996, 'CadiroOnSevenLeagueStep', '[]', 'Ah, I recognise those old boots. Seven-League Step... I used to chase Chitus around the manor when he was small, but when he put those boots on, he started chasing <i>{me}.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_92.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13997, 'CadiroOnDoryanisDelusion', '[]', 'Icius had much to say about Doryani. Doryani was a cold and calculating figure, one motivated only by a desire to save his people... forever. Take that ominous note as you will. A shame we never managed to excavate Utzaal.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_93.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13998, 'CadiroOnKaomsRoots', '[]', 'Oh, you''re wearing those clanky old things? Kaom''s Roots... He fancied himself an almighty warrior, but those rusted greaves could not save him in the end.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_94.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(13999, 'CadiroOnVictariosFlight', '[]', 'Victario''s Flight, eh? He was best known for denigrating my nephew and sowing seeds of dissent among the populace. He couldn''t fly far enough. It''s fortunate that he met a bitter end.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_95.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100);
INSERT INTO "NPCTextAudio" ("_row", "Id", "Characters", "Text", "Mono_AudioFile", "Stereo_AudioFile", "HasStereo", "__col6", "Video", "__col8", "__col9", "__col10", "NPCs", "NPCPortrait", "__col13", "__col14", "Cooldown", "__col16") VALUES
(14000, 'CadiroOnAtzirisStep', '[]', 'Atziri''s Step? Bah! Every move she made brought Wraeclast closer to ruin.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_96.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14001, 'CadiroOnShavronnesGambit', '[]', 'Like all of Malachai''s students, Shavronne was brilliant and adept in the art of deceit.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_97.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14002, 'CadiroOnShavronnesPace', '[]', 'If you can keep up with the pace of Shavronne''s accomplishments, you''ll be well on your way to success.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_98.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14003, 'CadiroOnLioneyesPaws', '[]', 'It''s a shame that Marceus couldn''t claw out the Karui where they stood.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_99.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14004, 'CadiroOnRalakeshsImpatience', '[]', 'The Vaal gods were cruel masters – I wouldn''t want to have tested Ralakesh''s patience.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_100.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14005, 'CadiroOnAurseize', '[]', 'Aurseize are most auspicious gloves indeed. An old favorite of mine.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_101.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14006, 'CadiroOnUsupersPenance', '[]', 'I doubt many usurpers truly show penance. They''re too busy reaping the rewards of having overthrown their masters.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_102.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14007, 'CadiroOnFairgravesTricorne', '[]', 'Looks like a good hat for fishing. Don''t want the sun in your eyes, you know. Perandus Manor was always stocked with all sorts of exotic fish...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_103.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14008, 'CadiroOnWreathOfPhrecia', '[]', 'I thank the Phrecians for establishing that labyrinth, which was most certainly in my nephew''s favour. But they were shoddy rulers at best.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_104.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14009, 'CadiroOnDoedresScorn', '[]', 'Ah, I recognise that circlet. It belonged to Doedre Darktongue... the perverse old hag that she was. Her mind was more twisted even than Malachai''s.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_105.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14010, 'CadiroOnChitusApex', '[]', 'Oh... I see you''re wearing Chitus'' Apex. You could show a little respect, you know... He was my nephew, after all.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_106.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14011, 'CadiroOnKitavasThirst', '[]', 'Kitava''s Thirst, eh? I have little respect for the Karui, and even less for Kitava... Fah! Gluttonous old fool.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_107.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14012, 'CadiroOnGeofrisCrest', '[]', 'Bah, take that blasted crest out of my sight! It belonged to a Phrecian slimeball who worked alongside Voll to overthrow all that I held dear.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_108.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14013, 'CadiroOnCrownOfTheTyrant', '[]', 'The Crown of the Tyrant, hmm? I see you''ve got some grand aspirations. All I''ll say is that you''d do well to ensure that people like you before you grasp the reins of power.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_109.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14014, 'CadiroOnGeofrisLegacy', '[]', 'Geofri''s Legacy? Bah! All he left behind was the tattered ruins of an empire, and a primitive vision for the future. He hated thaumaturgy, but can you imagine a world without virtue gems? Think of all the profits squandered...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_110.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14015, 'CadiroOnMalachaisVision', '[]', 'Malachai''s Vision, eh? You may be wearing his crown, but I doubt you''ll ever see things in quite the same way as he did.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_111.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14016, 'CadiroOnVollsVision', '[]', 'Honestly, I''m surprised you''re wearing Voll''s Vision. It''s a testament to the acts of treason that threw Wraeclast into disarray.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_112.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14017, 'CadiroOnMalachaisSimula', '[]', 'We''re all better off now that Malachai is gone, but you can''t say he wasn''t a clever old bastard.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_113.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14018, 'CadiroOnMalachaisAwakening', '[]', 'Malachai''s Awakening, eh? May he sleep eternally. Although, if I had a mere fraction of the power he had, I''d be even wealthier than I am now.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_114.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14019, 'CadiroOnZerphisLastBreath', '[]', 'Ah, that flask used to be part of my collection. Zerphi''s Last Breath, if I''m not mistaken. He was a serial killer; possibly one who was siphoning life from his victims, since he lived to the ripe old age of 168.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_115.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14020, 'CadiroOnTheWrithingJar', '[]', 'Ha! The Writhing Jar. High Templar Voll loathed this flask, despite being quite the worm himself...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_116.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14021, 'CadiroOnSoulCatcher', '[]', 'Word has it that Soul Catcher entraps the souls of those slain by the imbiber, and grants them heightened power.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_117.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14022, 'CadiroOnSoulRipper', '[]', 'It''s said that Soul Ripper was used by Vaal priests in their dark rituals, to aid their practices of human sacrifice.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_118.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14023, 'CadiroOnOlrothsResolve', '[]', 'Ah yes, Olroth''s Resolve. He had a little too much resolve, if you ask me...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_119.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14024, 'CadiroOnCinderswallowUrn', '[]', 'The Cinderswallow Urn. Takes me back to the days when Janus Perandus, Chitus'' great-grandson, joined the Order of the Djinn. Somehow, most of the Order ended up being dispatched, which allowed Catarina to pilfer the Horns of Kulemak from the Forbidden Vault. Catarina then used the Horns to resurrect the dead – without them becoming Undying – and established the Immortal Syndicate. Janus, of course, has joined the noble ranks of the Immortal Syndicate. I''m a little envious, truth be told.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_120.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14025, 'CadiroOnDyingSun', '[]', 'Ah... Dying Sun. I imagine that would burn the throat more fiercely than a fine whiskey.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_121.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14026, 'CadiroOnGrandSpectrum', '[]', 'Did you loot that jewel from Izaro''s coffers?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_122.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14027, 'CadiroOnMegalomaniac', '[]', 'A fitting jewel for one such as yourself to be wearing, eh?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_123.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14028, 'CadiroOnVoices', '[]', 'It''s said that the gods themselves whisper to the one who harnesses the power of this jewel...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_124.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14029, 'CadiroMultipleUniques1A', '[]', 'Thank you kindly for adding to my collection.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14030, 'CadiroMultipleUniques1B', '[]', 'Thank you kindly for adding to my collection.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14031, 'CadiroMultipleUniques1C', '[]', 'Thank you kindly for adding to my collection.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14032, 'CadiroMultipleUniques1D', '[]', 'Thank you kindly for adding to my collection.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_01_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14033, 'CadiroMultipleUniques2A', '[]', 'These will make excellent additions to the Perandus caches.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14034, 'CadiroMultipleUniques2B', '[]', 'These will make excellent additions to the Perandus caches.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14035, 'CadiroMultipleUniques2C', '[]', 'These will make excellent additions to the Perandus caches.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14036, 'CadiroMultipleUniques2D', '[]', 'These will make excellent additions to the Perandus caches.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_02_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14037, 'CadiroMultipleUniques3A', '[]', 'I might even put these on display.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14038, 'CadiroMultipleUniques3B', '[]', 'I might even put these on display.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14039, 'CadiroMultipleUniques3C', '[]', 'I might even put these on display.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14040, 'CadiroMultipleUniques3D', '[]', 'I might even put these on display.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_125_03_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14041, 'CadiroMultipleItemVendorRecipe1A', '[]', 'Let me see what I can rustle up with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14042, 'CadiroMultipleItemVendorRecipe1B', '[]', 'Let me see what I can rustle up with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14043, 'CadiroMultipleItemVendorRecipe1C', '[]', 'Let me see what I can rustle up with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14044, 'CadiroMultipleItemVendorRecipe1D', '[]', 'Let me see what I can rustle up with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_01_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14045, 'CadiroMultipleItemVendorRecipe2A', '[]', 'I know what to do with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14046, 'CadiroMultipleItemVendorRecipe2B', '[]', 'I know what to do with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14047, 'CadiroMultipleItemVendorRecipe2C', '[]', 'I know what to do with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14048, 'CadiroMultipleItemVendorRecipe2D', '[]', 'I know what to do with these.', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_02_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14049, 'CadiroMultipleItemVendorRecipe3A', '[]', 'You want me to do what?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14050, 'CadiroMultipleItemVendorRecipe3B', '[]', 'You want me to do what?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14051, 'CadiroMultipleItemVendorRecipe3C', '[]', 'You want me to do what?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14052, 'CadiroMultipleItemVendorRecipe3D', '[]', 'You want me to do what?', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_126_03_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14053, 'CadiroVendorRecipesItemModifier1A', '[]', 'I''m a banker, not a blacksmith!', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_127_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14054, 'CadiroVendorRecipesItemModifier1B', '[]', 'I''m a banker, not a blacksmith!', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_127_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14055, 'CadiroVendorRecipesItemModifier1C', '[]', 'I''m a banker, not a blacksmith!', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_127_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14056, 'CadiroVendorRecipesItemModifier1D', '[]', 'I''m a banker, not a blacksmith!', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_127_01_04.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
(14057, 'CadiroVendorRecipesItemModifier2A', '[]', 'Do you really expect me, a man of esteem and affluence, to do that? Oh, I suppose...', 'Audio/Dialogue/NPC/CadiroNew/Cadiro_320_127_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[560]', NULL, 0, 0, '[]', 100),
