(14307, 'LyciaCombatEscapeRandom', '[]', 'Impressive, adventurer, but I need more from you. Return when you are stronger.', 'Audio/Dialogue/NPC/Lycia_GodVoice/Lycia_Combat_Escape_01.ogg', '', 0, 0, '', 1, 0, 1, '[567]', NULL, 0, 0, '[]', 100),
(14308, 'LyciaCombatTransformationRandom', '[]', 'The moment is nigh. The ritual is nearly complete. Give me your all!', 'Audio/Dialogue/NPC/Lycia_Combat/Lycia_Combat_Transformation_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[567]', NULL, 0, 0, '[]', 100),
(14309, 'LyciaCombatTransformation2', '[]', 'Yes! The blood moon rises! Beidat, give me your power!', 'Audio/Dialogue/NPC/Lycia_Combat/Lycia_Combat_Transformation_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[567]', NULL, 0, 0, '[]', 100),
