(14334, 'LyciaTransformedCombatDeathRandom', '[]', 'You are only delaying the inevitable.', 'Audio/Dialogue/NPC/LyciaTransformed_Combat/LyciaTransformed_Combat_Death_01.ogg', '', 0, 0, '', 1, 0, 1, '[568]', NULL, 0, 0, '[]', 100),
(14335, 'LyciaTransformedCombatDeath2', '[]', 'I cannot die. You know this.', 'Audio/Dialogue/NPC/LyciaTransformed_Combat/LyciaTransformed_Combat_Death_02.ogg', '', 0, 0, '', 1, 0, 1, '[568]', NULL, 0, 0, '[]', 100),
(14336, 'LyciaTransformedCombatDeath3', '[]', 'Beidat beckons just beyond the door...', 'Audio/Dialogue/NPC/LyciaTransformed_Combat/LyciaTransformed_Combat_Death_03.ogg', '', 0, 0, '', 1, 0, 1, '[568]', NULL, 0, 0, '[]', 100),
