(14339, 'LyciaCombatIntroRepeatRandom', '[]', 'I have an eternity. You are only wasting your own meagre time.', 'Audio/Dialogue/NPC/Lycia_Combat/Lycia_Combat_IntroRepeat_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[567]', NULL, 0, 0, '[]', 100),
(14340, 'LyciaCombatIntroRepeat2', '[]', 'I have an eternity. You are only wasting your own meagre time.', 'Audio/Dialogue/NPC/Lycia_Combat/Lycia_Combat_IntroRepeat_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[567]', NULL, 0, 0, '[]', 100),
