(14419, 'LyciaGodVoiceTakePact4', '[]', 'Feed the beast all that it desires...', 'Audio/Dialogue/NPC/Lycia_GodVoice/Lycia_GodVoice_07_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[566]', NULL, 0, 0, '[]', 100),
(14420, 'LyciaGodVoiceTakePact5', '[]', 'Feed the beast all that it desires...', 'Audio/Dialogue/NPC/Lycia_GodVoice/Lycia_GodVoice_07_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[566]', NULL, 0, 0, '[]', 100),
(14421, 'LyciaGodVoiceTakePact6', '[]', 'Another human tempted by power? A mortal after my own heart.', 'Audio/Dialogue/NPC/Lycia_GodVoice/Lycia_GodVoice_07_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[566]', NULL, 0, 0, '[]', 100),
