(14423, 'LyciaGodVoiceFireBeamRandom', '[]', 'Playing with fire will get you burned...', 'Audio/Dialogue/NPC/Lycia_GodVoice/Lycia_GodVoice_08.ogg', '', 0, 0, '', 1, 0, 1, '[566]', NULL, 0, 0, '[]', 100),
