(14448, 'ChaosEntityPickedUpChaosOrbSmallStack7', '[]', 'We are pleased.', 'Audio/Dialogue/NPC/ChaosOrbArmour/ChaosArmour_01_C_01.ogg', '', 0, 0, '', 1, 2500, 1, '[579]', NULL, 0, 0, '[]', 100),
