(14642, 'ChieftainPortalPlayerDiedRandom', '[]', 'Ah, you have not yet earned your place in death.', 'Audio/Dialogue/NPC/Chieftain_Portal/PlayerDied_ChieftainPortal_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14643, 'ChieftainPortalPlayerDied2', '[]', 'Ah, you have not yet earned your place in death.', 'Audio/Dialogue/NPC/Chieftain_Portal/PlayerDied_ChieftainPortal_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
