(14658, 'ChieftainPortalStashInHideoutRandom', '[]', 'Gird yourself for battle!', 'Audio/Dialogue/NPC/Chieftain_Portal/StashInHideout_ChieftainPortal_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14659, 'ChieftainPortalStashInHideout2', '[]', 'Gird yourself for battle!', 'Audio/Dialogue/NPC/Chieftain_Portal/StashInHideout_ChieftainPortal_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14660, 'ChieftainPortalStashInHideout3', '[]', 'A good weapon is a warrior''s only friend.', 'Audio/Dialogue/NPC/Chieftain_Portal/StashInHideout_ChieftainPortal_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
