(14662, 'ChieftainPortalStashInHideout5', '[]', 'The battlefield awaits.', 'Audio/Dialogue/NPC/Chieftain_Portal/StashInHideout_ChieftainPortal_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
