(14664, 'ChieftainPortalTradeInHideoutRandom', '[]', 'Why trade when you can conquer?', 'Audio/Dialogue/NPC/Chieftain_Portal/TradeInHideout_ChieftainPortal_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14665, 'ChieftainPortalTradeInHideout2', '[]', 'Why trade when you can conquer?', 'Audio/Dialogue/NPC/Chieftain_Portal/TradeInHideout_ChieftainPortal_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14666, 'ChieftainPortalTradeInHideout3', '[]', 'Warriors are remembered. Merchants are not.', 'Audio/Dialogue/NPC/Chieftain_Portal/TradeInHideout_ChieftainPortal_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14667, 'ChieftainPortalTradeInHideout4', '[]', 'Warriors are remembered. Merchants are not.', 'Audio/Dialogue/NPC/Chieftain_Portal/TradeInHideout_ChieftainPortal_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14668, 'ChieftainPortalTradeInHideout5', '[]', 'The glory of battle dims in the darkness of safety.', 'Audio/Dialogue/NPC/Chieftain_Portal/TradeInHideout_ChieftainPortal_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14669, 'ChieftainPortalTradeInHideout6', '[]', 'The glory of battle dims in the darkness of safety.', 'Audio/Dialogue/NPC/Chieftain_Portal/TradeInHideout_ChieftainPortal_C_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14670, 'ChieftainPortalVendorInHideoutRandom', '[]', 'Wealth is the weapon of the weak.', 'Audio/Dialogue/NPC/Chieftain_Portal/VendorInHideout_ChieftainPortal_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14671, 'ChieftainPortalVendorInHideout2', '[]', 'Wealth is the weapon of the weak.', 'Audio/Dialogue/NPC/Chieftain_Portal/VendorInHideout_ChieftainPortal_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14672, 'ChieftainPortalVendorInHideout3', '[]', 'The war is waiting.', 'Audio/Dialogue/NPC/Chieftain_Portal/VendorInHideout_ChieftainPortal_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14673, 'ChieftainPortalVendorInHideout4', '[]', 'The war is waiting.', 'Audio/Dialogue/NPC/Chieftain_Portal/VendorInHideout_ChieftainPortal_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14674, 'ChieftainPortalVendorInHideout5', '[]', 'The Ancestors grow impatient.', 'Audio/Dialogue/NPC/Chieftain_Portal/VendorInHideout_ChieftainPortal_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14675, 'ChieftainPortalVendorInHideout6', '[]', 'The Ancestors grow impatient.', 'Audio/Dialogue/NPC/Chieftain_Portal/VendorInHideout_ChieftainPortal_C_02.ogg', '', 0, 0, '', 1, 0, 1, '[580]', NULL, 0, 0, '[]', 100),
(14676, 'MoltenOneEntranceSpeechRandom', '[]', 'Ah, surface-dweller. You have entered a place largely untouched by mankind.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_01.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14677, 'MoltenOneEntranceSpeech2', '[]', 'Welcome, surface-dweller... to a place created by the titans. Your kind have stood upon our shoulders since time immemorial.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_02.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14678, 'MoltenOneEntranceSpeech3', '[]', 'Hail, surface-dweller. You have entered a place almost lost to time itself... one in which you must prove your might.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_03.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14679, 'MoltenOnePlayerApproachAnvilRandom', '[]', 'Evolution is an inevitable strengthening process – beautiful in its happenstance and terrible in its viciousness.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_04.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14680, 'MoltenOnePlayerApproachAnvil2', '[]', 'You may use this tool to ensure your own survival... and the longevity of Wraeclast itself.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_05.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14681, 'MoltenOnePlayerApproachAnvil3', '[]', 'Soon you will become one with our primordial power.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_06.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14682, 'MoltenOnePlayerApproachAnvil4', '[]', 'This is our centre of power – our forge, where the heartblood of the world flows forth as magma.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_07.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14683, 'MoltenOneOnPlayerCraftingWeaponsRandom', '[]', 'To forge weapons from the heat of the Crucible is to bend the very essence of the world to your will.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_08.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14684, 'MoltenOneOnPlayerCraftingWeapons2', '[]', 'To forge weapons from the heart of the Crucible is to bend the very essence of the world to your will.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_09.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14685, 'MoltenOneOnPlayerCraftingWeapons3', '[]', 'A new instrument of destruction.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_10.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14686, 'MoltenOneOnPlayerCraftingWeapons4', '[]', 'A powerful creation.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_11.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14687, 'MoltenOneOnPlayerCraftingWeapons5', '[]', 'Borne of red-hot magma.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_12.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14688, 'MoltenOneOnPlayerCraftingWeapons6', '[]', 'Where the Redblades failed, you have succeeded.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_13.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14689, 'MoltenOneOnPlayerCraftingWeapons7', '[]', 'You are achieving mastery over the forge. Impressive.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_14.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14690, 'MoltenOneOnPlayerCraftingWeapons8', '[]', 'An impressive feat for one so small. You show undeniable promise.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_15.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14691, 'MoltenOneOnPlayerCraftingWeapons9', '[]', 'A series of small steps can conquer a mountain.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_16.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14692, 'MoltenOneOnPlayerCraftingWeapons10', '[]', 'A series of small steps pave the path to success.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_17.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14693, 'MoltenOneOnPlayerCraftingWeapons11', '[]', 'May we triumph over our common enemies.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_18.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14694, 'MoltenOneOnPlayerCraftingWeapons12', '[]', 'Together, we will achieve an alliance in the face of ancient evil!', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_19.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14695, 'MoltenOneOnTreesCombiningRandom', '[]', 'Ascend, mortal, and wield the power you know yourself to be worthy of.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_20.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14696, 'MoltenOneOnTreesCombining2', '[]', 'Use this to annihilate those who threaten to consume Wraeclast.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_21.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14697, 'MoltenOneOnTreesCombining3', '[]', 'A monumental creation which will inevitably beget destruction.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_22.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14698, 'MoltenOneOnTreesCombining4', '[]', 'The Redblades could not have hoped to achieve what you have. Truly remarkable.', 'Audio/Dialogue/NPC/TheMoltenOne/MoltenOne_23.ogg', '', 0, 0, '', 1, 0, 1, '[583]', NULL, 0, 0, '[]', 100),
(14699, 'MoltenOneGlyphOne', '[]', 'Our mountain was once overrun by various human tribes vying amongst themselves for dominance. Little did the Redblades know that they encroached upon our territory and we were largely indifferent to their plights. It wasn''t until the mountain erupted that their petty disputes were quelled.', 'Audio/Dialogue/NPC/TheMoltenOneGlyph/MoltenOne_Glyph_01.ogg', '', 0, 0, '', 1, 0, 1, '[584]', NULL, 0, 0, '[]', 100),
(14700, 'MoltenOneGlyphTwo', '[]', 'We were largely indifferent to the struggles of humanity for millennia. Their suffering has become our own, now that we have a common goal to unite us. The hostile entities that threatened to overwhelm us still lurk deep beneath the surface of our world. We must ally with mankind in order to keep them at bay.', 'Audio/Dialogue/NPC/TheMoltenOneGlyph/MoltenOne_Glyph_02.ogg', '', 0, 0, '', 1, 0, 1, '[585]', NULL, 0, 0, '[]', 100),
(14701, 'DemonCraftingBench_FirstInteraction', '[]', 'You are not of the Ramako Tribe. How have you chained me?!', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_01.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14702, 'DemonCraftingBench_OnWakingUpRandom', '[]', 'What now?', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14703, 'DemonCraftingBench_OnWakingUp2', '[]', 'What now?', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_02_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14704, 'DemonCraftingBench_OnWakingUp3', '[]', 'What now?', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_02_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14705, 'DemonCraftingBench_OnWakingUp4', '[]', 'Release me!', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14706, 'DemonCraftingBench_OnWakingUp5', '[]', 'Release me!', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14707, 'DemonCraftingBench_LowTierCraftRandom', '[]', 'You chained me for such paltry use?', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14708, 'DemonCraftingBench_LowTierCraft2', '[]', 'You chained me for such paltry use?', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14709, 'DemonCraftingBench_LowTierCraft3', '[]', 'How ignoble.', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14710, 'DemonCraftingBench_LowTierCraft4', '[]', 'How ignoble.', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_03_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14711, 'DemonCraftingBench_LowTierCraft5', '[]', 'How ignoble.', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_03_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
(14712, 'DemonCraftingBench_LowTierCraft6', '[]', 'Disappointing.', 'Audio/Dialogue/NPC/DemonCraftingBench/DemonCraftingBench_03_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[586]', NULL, 0, 0, '[]', 100),
