(14798, 'NavaliBackroomCallForward1', '[]', 'Come closer, mortal.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Wild/Navali_Wild_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[587]', NULL, 0, 0, '[]', 100),
(14799, 'NavaliBackroomCallForward2', '[]', 'Come closer, mortal.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Wild/Navali_Wild_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[587]', NULL, 0, 0, '[]', 100),
(14800, 'NavaliBackroomAboutDeath', '[]', 'Have no fear. The Water of Sight does not slay the living, just nearly so. You may resume your mortal life, such as it is, once you return your spirit to your body.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Wild/Navali_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[587]', NULL, 0, 0, '[]', 100),
(14801, 'NavaliBackroomIntroduction', '[]', 'Your coming was foretold, but you are decades early. How odd. I am Navali, once a <i>{hatungo} for my people, now a revenant in service of the Mother of Death. Here you shall be tested by the greatest warriors that ever lived. You will be weighed and measured on the scales of Fate, and we shall determine your true worth.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali/Navali_01.ogg', '', 0, 0, '', 1, 0, 1, '[587]', NULL, 0, 0, '[]', 100),
(14802, 'NavaliBackroomAboutHallsOfTheDead', '[]', 'Here in the Halls of the Dead, we wile away our days by holding grand competitions of skill and daring. You may participate in these Trials, but be warned, the warriors of the Karui never hold back.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali/Navali_02.ogg', '', 0, 0, '', 1, 0, 1, '[587]', NULL, 0, 0, '[]', 100),
(14803, 'NavaliAnnouncerBeginsAnnouncement', '[]', 'Noble Ancestors! A new challenger has arrived!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_01.ogg', '', 0, 0, '', 2, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(14804, 'NavaliAnnouncerAnnouncesWitch', '[]', 'A Witch, banished from her coven for her ambitions, seeks to prove herself. ', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_02.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(14805, 'NavaliAnnouncerAnnouncesTemplar', '[]', 'A Templar, full of righteous anger, seeks a worthy opponent.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_03.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(14806, 'NavaliAnnouncerAnnouncesMarauder', '[]', 'A Marauder, one of our proud sons returned, has come to prove himself.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_04.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(14807, 'NavaliAnnouncerAnnouncesDuelist', '[]', 'A Duelist, lonely and hollow, seeks to put on a show for us.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_05.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
