(14881, 'AncestralAkoyaCutDown4', '[]', 'Cut down!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_23_04.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14882, 'AncestralAkoyaNoneCanStandRandom', '[]', 'None can stand against us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_24_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14883, 'AncestralAkoyaNoneCanStand2', '[]', 'None can stand against us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_24_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14884, 'AncestralAkoyaForTukohamaRandom', '[]', 'For Tukohama!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14885, 'AncestralAkoyaForTukohama2', '[]', 'For Tukohama!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_25_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14886, 'AncestralAkoyaForTukohama3', '[]', 'For Tukohama!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_25_03.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14887, 'AncestralAkoyaForTukohama4', '[]', 'For Tukohama!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_25_04.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14888, 'TawhanukuDeathFromOnHighRandom', '[]', 'Death from on high!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_19_01.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14889, 'TawhanukuDeathFromOnHigh2', '[]', 'Death from on high!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_19_02.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14890, 'TawhanukuDeathFromOnHigh3', '[]', 'Death from on high!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_19_03.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14891, 'TawhanukuChoirOfSoulsRandom', '[]', 'Choir of souls!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_20_01.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14892, 'TawhanukuChoirOfSouls2', '[]', 'Choir of souls!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_20_02.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14893, 'TawhanukuChoirOfSouls3', '[]', 'Choir of souls!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_20_03.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14894, 'TawhanukuChoirOfSouls4', '[]', 'Choir of souls!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_20_04.ogg', '', 0, 0, '', 1, 0, 1, '[608]', NULL, 0, 0, '[]', 100),
(14895, 'RakiataLikesPlayerIsChampion', '[]', 'You are in control, makanga. Just keep your guard up.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14896, 'RakiataNeutralPlayerIsChampion', '[]', 'The title of makanga comes and goes. Do not fret.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14897, 'RakiataDislikesPlayerIsChampion', '[]', 'Perhaps the tide is about to turn against you, makanga.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14898, 'RakiataLikesPlayerLostLast', '[]', 'This is your opportunity to seize back your honour, outsider!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14899, 'RakiataNeutralPlayerLostLast', '[]', 'The outsider seems intent on winning this one.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14900, 'RakiataDislikesPlayerLostLast', '[]', 'The outcome for this one seems clear.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14901, 'RakiataLikesPlayerNoRecord', '[]', 'The waves often bring unexpected treasures.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14902, 'RakiataNeutralPlayerNoRecord', '[]', 'I''m curious what skills you bring to our Halls, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14903, 'RakiataDislikesPlayerNoRecord', '[]', 'I am unclear what the point of this is.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14904, 'RakiataCommentsOnAkoya', '[]', 'Stuffy traditions make for poor warriors.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14905, 'RakiataCommentsOnIkiaho', '[]', 'Take it all, Ikiaho! You are the strongest of all of us.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14906, 'RakiataCommentsOnKahuturoa', '[]', 'We''ve got an immovable object. Who shall be his unstoppable force?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14907, 'RakiataCommentsOnKaom', '[]', 'Eh, Kaom, recognize me? I''m cheering for you to lose your head this time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14908, 'RakiataCommentsOnKiloava', '[]', 'Calm yourself, you great bag of wind.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14909, 'RakiataCommentsOnMaata', '[]', 'Bring Tawhoa''s peace to all of us, Maata.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14910, 'RakiataCommentsOnTawhanuku', '[]', 'The future is yours, Tawhanuku.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14911, 'RakiataCommentsOnUtula', '[]', 'Be the sea that puts out Utula''s fire.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14912, 'RakiataCommentsOnAhuana', '[]', 'Such warmth and light, shining on the sea.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14913, 'RakiataFightBeginsPlayerWonLast', '[]', 'You won last time. Perhaps it is my turn', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14914, 'RakiataFightBeginsPlayerLostLast', '[]', 'I expect you''re highly motivated to face me after last time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_02.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14915, 'RakiataFightBeginsPlayerMoreSoldiers', '[]', 'A mighty host. I''ll have to cut them all down.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_03.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14916, 'RakiataFightBeginsPlayerLessSoldiers', '[]', 'We are vast like the sea.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_04.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14917, 'RakiataFightBeginsPlayerMoreItems', '[]', 'So many charms and bangles. I hope it works for you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_05.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14918, 'RakiataFightBeginsPlayerLessItems', '[]', 'We seem to have more equipment than you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_06.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14919, 'RakiataFightBeginsPlayerMoreFieldItems', '[]', 'Rocky shoals, placed in the hopes of breaking us.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_07.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14920, 'RakiataFightBeginsPlayerLessFieldItems', '[]', 'A battlefield swept clean by the sea.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_08.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14921, 'RakiataWarcry1', '[]', 'For Tasalio!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_09_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14922, 'RakiataWarcry2', '[]', 'For Tasalio!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_09_02.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14923, 'RakiataWarcry3', '[]', 'Make war!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_10_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14924, 'RakiataWarcry4', '[]', 'Make war!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_10_02.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14925, 'RakiataWarcry5', '[]', 'Crash like the waves!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_11_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14926, 'RakiataWarcry6', '[]', 'Crash like the waves!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_11_02.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14927, 'RakiataTeamTotemDestroyed1', '[]', 'The tide turns against us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_12.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14928, 'RakiataTeamTotemDestroyed2', '[]', 'One''s been downed!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_13.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14929, 'RakiataTeamTotemDestroyed3', '[]', 'Cover our flank!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_14.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14930, 'RakiataTotemDestroyed1', '[]', 'All part of the plan. Continue the battle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_15.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14931, 'RakiataTotemDestroyed2', '[]', 'A crashing wave cannot be stopped so easily.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_16.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14932, 'RakiataTotemDestroyed3', '[]', 'No matter.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_17_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14933, 'RakiataYourTeamTotemDestroyed1', '[]', 'Nothing is decided yet.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_18_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14934, 'RakiataYourTeamTotemDestroyed2', '[]', 'Continue the plan!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_19_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14935, 'RakiataYourTeamTotemDestroyed3', '[]', 'Onwards and over!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_20_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14936, 'RakiataYourTotemDestroyed1', '[]', 'We have struck a mighty blow.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_21_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14937, 'RakiataYourTotemDestroyed2', '[]', 'They begin to crumble.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_22_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14938, 'RakiataYourTotemDestroyed3', '[]', 'The sea erodes even the mightiest fortress!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_23_01.ogg', '', 0, 0, '', 1, 60000, 1, '[600]', NULL, 0, 0, '[]', 100),
(14939, 'RakiataCommentDefeatedYou1', '[]', 'Until next time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_24_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14940, 'RakiataCommentDefeatedYou2', '[]', 'Victory comes and goes. We''ll battle again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14941, 'RakiataCommentDefeatedYou3', '[]', 'A good fight.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14942, 'RakiataCommentWhenDefeated', '[]', 'So it goes. Well done.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Field/Rakiata_Field_27_01.ogg', '', 0, 0, '', 1, 0, 1, '[600]', NULL, 0, 0, '[]', 100),
(14943, 'RakiataCommentsFromStandsOnMatch', '[]', 'That was rather satisfying to watch!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_22_01.ogg', '', 0, 0, '', 1, 0, 1, '[610]', NULL, 0, 0, '[]', 100),
(14944, 'RakiataCommentPurchaseItem1', '[]', 'You are welcome.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_01_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14945, 'RakiataCommentPurchaseItem2', '[]', 'Fair choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_01_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14946, 'RakiataCommentPurchaseFieldItem1', '[]', 'Make the battlefield your own.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14947, 'RakiataCommentPurchaseFieldItem2', '[]', 'Where we fight is often just as important as how.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14948, 'RakiataCommentInspectRecruits1', '[]', 'These are mine to offer.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14949, 'RakiataCommentInspectRecruits2', '[]', 'Take a look.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14950, 'RakiataCommentRecruitRecruit1', '[]', 'That''ll work.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14951, 'RakiataCommentRecruitRecruit2', '[]', 'Fair.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14952, 'RakiataPlayerWonVsAkoya', '[]', 'Akoya takes our traditions far too seriously. Maybe her defeat will give her time to relax.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_05.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14953, 'RakiataPlayerLostVsAkoya', '[]', 'Too bad about losing to Akoya. I''m sure she won''t rub it in.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_06.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14954, 'RakiataPlayerWonVsKaom', '[]', 'Kaom needed a reminder that he is not the sole bearer of the Karui way.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_07.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14955, 'RakiataPlayerLostVsKaom', '[]', 'You lost to Kaom? That''s mildly disappointing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_08.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14956, 'RakiataPlayerWonVsKiloava', '[]', 'Kiloava won''t be any quieter after his loss to you. In fact, he might get louder.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_09.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14957, 'RakiataPlayerLostVsKiloava', '[]', 'Kiloava seems to be rather excited he defeated you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_10.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14958, 'RakiataPlayerWonVsUtula', '[]', 'If Utula sets this place on fire, it seems I can depend upon you to douse his flames.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_11.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14959, 'RakiataPlayerLostVsUtula', '[]', 'Hmm. Losing to Utula might encourage him. Best not do that again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_12.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14960, 'RakiataPlayerWonVsAhuana', '[]', 'It''s always enjoyable to battle against Ahuana, is it not?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_13.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14961, 'RakiataPlayerLostVsAhuana', '[]', 'Ahuana''s tribe fights with the light of the Karui... and the chill pain of a forbidden love. That''s how they defeated you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_14.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14962, 'RakiataPlayerWonVsTawhanuku', '[]', 'Fighting Tawhanuku was enjoyable, was it not? Something about subverting fate is quite satisfying.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_15.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14963, 'RakiataPlayerLostVsTawhanuku', '[]', 'Lost to Tawhanuku, eh? We''ve all done it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_16.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14964, 'RakiataPlayerWonVsMaata', '[]', 'Maata is a unique challenge among these chieftains. He uses his mind more than most.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_17.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14965, 'RakiataPlayerLostVsMaata', '[]', 'Maata always has a strong plan going in. That''s how he wins.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_18.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14966, 'RakiataPlayerWonAgainstThem', '[]', 'I''m looking forward to our next bout.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_19.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14967, 'RakiataPlayerLostAgainstThem', '[]', 'Can''t win them all, can you?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_20.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14968, 'RakiataPlayerWonNeutral', '[]', 'Keep fighting like that, and you''ll become a legend yourself.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_21.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14969, 'RakiataPlayerLostNeutral', '[]', 'Training is a warrior''s best weapon.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_22.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14970, 'RakiataCommentOnPurchaseItemIkiaho', '[]', 'Trust anything you get from her.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14971, 'RakiataCommentOnPurchaseEliteIkiaho', '[]', 'Ikiaho''s warriors are unmatched.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_24.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14972, 'RakiataConversationWithIkiahoOne', '[]', 'I wish I could smell the sea.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_25.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14973, 'RakiataConversationWithKahuOne', '[]', 'That was a long time ago, Kahu. Leave it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_26.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14974, 'RakiataRandomShout1', '[]', 'Today is a good day to be dead.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata_Wild/Rakiata_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[590]', NULL, 0, 0, '[]', 100),
(14975, 'RakiataGossipFirstBattle', '[]', 'I was thirteen when an Eternal army attacked my tribe. They were in search of an ancient and powerful weapon from our myths, but we only had a single piece of it. Our chieftain was felled in his sleep. My father was as well. So, I took up his weapons, and I went about the work that needed to be done. Once they were dead, knowing that more would come if we had what they wanted, I entrusted Tasalio with our piece of that fabled spear. My tribe tried to put me in charge after that, but I refused the mantle. I just did what I thought was right, and they followed.' || char(13) || '
' || char(13) || '
Although... there was something to the myth of that spear''s power. In the few moments I held just a piece of it, my hand was permanently scarred, as if I''d been burned by unseen and unfelt heat.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_23.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14976, 'RakiataGossipTheWay', '[]', 'Even in my earliest memories, I was training for battle. I do enjoy fighting, but not the way others around me did. To them, it was a savage contest of dominance and manhood. To me, there was an elegance to warfare. It had an ebb and flow, like the tide. It was a kind of dance. When they say I have an unconventional fighting style, it is because they do not realize that I am not fighting. I am dancing. I may feel the bite of an axe at any moment, so why not enjoy each sweep, and each slash? They have their Way. What I have, I call the Flow.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_24.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14977, 'RakiataGossipTasalio', '[]', 'Tasalio has never spoken to me directly. I think I hear his influence in the waves, and the wind over the ocean. I found a ring on the shore one day, bearing his graven pattern. It had washed up from the ocean, and I still believe it was a gift from him. It had a great power within it, but I never used it. I didn''t need to. There were no problems I could not face with my own strength and cunning.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_25.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14978, 'RakiataGossipIkiaho', '[]', 'She''s stronger than she knows. She doesn''t need me to fight battles on her behalf, nor would she want me to. When I first arrived here, many of the other chieftains were hostile, and the most traditional among them outright rejected me. It was she who vouched for me. The opportunity to fight allowed me to prove myself, as I knew I could, and I have led Tasalio''s warriors ever since. In Ikiaho, I could not have asked for a better friend. Sometimes, we even sneak out of here, for a glimpse at the Moon and the sea.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_26.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14979, 'RakiataGossipSneakOut', '[]', 'There is a forgotten passage, a narrow but lengthy crack in the earth that leads to the main well, though the dead just find themselves back here after a few minutes. Still, that few minutes on the ocean, seeing the living world again... glorious. I go up there whenever I lose my tranquility.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_27.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14980, 'RakiataGossipTheEndOfTime', '[]', 'You''ll have to ask everyone else what they think. True followers of Tasalio do not trouble themselves with thoughts of such a far-flung future. Each day that you can recline on your <i>{waikoama}, feel the waves beneath you, and take in the sun and the sky... that is a day to treasure. I do not have those anymore, but I console myself with the knowledge that my descendants do. Live for today, outsider. Yesterday... tomorrow... they do not exist. You are only ever here, now.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_28.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14981, 'RakiataGossipTheFlow', '[]', 'There is a flow to the world, to the sea, and to battle. I could lose myself for hours in a war, just running, fighting, and hewing down my enemies. I sense that you know this joy as well. I have nothing to teach you, for you already know what makes you happy.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Rakiata/Rakiata/Rakiata_29.ogg', '', 0, 0, '', 1, 0, 1, '[590,627]', NULL, 0, 0, '[]', 100),
(14982, 'AkoyaObjectsToPlayer', '[]', 'Why should we allow an outsider to participate in our sacred traditions? This has always been a place for Karui warriors to hone their mettle against the best that ever lived. This outsider cannot possibly stand against us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14983, 'AkoyaDoesFirstChallenge', '[]', 'Very well. I shall make the challenge myself. I will be the first to fight!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14984, 'AkoyaAfterPlayerWinsFirstFight', '[]', 'I am impressed. It seems you may be worthy to participate here after all. Next time, of course, I shall not go so easy on you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14985, 'AkoyaAfterPlayerLosesFirstFight', '[]', 'You have some skill, outsider. Perhaps you may be worthy to participate here after all. I withdraw my objection, on the assumption that you will train and improve.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(14986, 'AkoyaLikesPlayerIsChampion', '[]', 'Honour our ways, makanga! Win again, on pure strength!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14987, 'AkoyaNeutralPlayerIsChampion', '[]', 'Makanga or not, you must prove yourself!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14988, 'AkoyaDislikesPlayerIsChampion', '[]', 'The title of makanga means nothing for one who cannot defend it!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14989, 'AkoyaLikesPlayerLostLast', '[]', 'It is the duty of the weak to become stronger, outsider!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14990, 'AkoyaNeutralPlayerLostLast', '[]', 'The strongest will win this battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14991, 'AkoyaDislikesPlayerLostLast', '[]', 'This is a waste of our time, and I say that knowing we have forever!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14992, 'AkoyaLikesPlayerNoRecord', '[]', 'I am eager to see whether this outsider has the strength needed!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14993, 'AkoyaNeutralPlayerNoRecord', '[]', 'I have no idea what to expect here...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14994, 'AkoyaDislikesPlayerNoRecord', '[]', 'The old ways demand only the best warriors!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14995, 'AkoyaCommentsOnRakiata', '[]', 'Impress us once again, Rakiata!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_19.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14996, 'AkoyaCommentsOnIkiaho', '[]', 'Fight for the honour of your tribe, Ikiaho!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14997, 'AkoyaCommentsOnKahuturoa', '[]', 'The oldest among us will show us the Way!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14998, 'AkoyaCommentsOnKaom', '[]', 'I''m eager to see how you snatch defeat from the jaws of victory, Kaom!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(14999, 'AkoyaCommentsOnKiloava', '[]', 'Show us how you earned the title, first Herald of War!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100);
INSERT INTO "NPCTextAudio" ("_row", "Id", "Characters", "Text", "Mono_AudioFile", "Stereo_AudioFile", "HasStereo", "__col6", "Video", "__col8", "__col9", "__col10", "NPCs", "NPCPortrait", "__col13", "__col14", "Cooldown", "__col16") VALUES
(15000, 'AkoyaCommentsOnMaata', '[]', 'What is your grand strategy this time, Maata?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(15001, 'AkoyaCommentsOnTawhanuku', '[]', 'Have you foreseen the victor of this battle, Tawhanuku? How boring!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_20.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(15002, 'AkoyaCommentsOnUtula', '[]', 'Utula, you will lose, because you do not honour the Way!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_21.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(15003, 'AkoyaCommentsOnAhuana', '[]', 'As you would say, Ahuana, have fun!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_22.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(15004, 'AkoyaFightBeginsPlayerWonLast', '[]', 'I will put your strength to the test!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15005, 'AkoyaFightBeginsPlayerLostLast', '[]', 'I hope you''ve improved since last we fought!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15006, 'AkoyaFightBeginsPlayerMoreSoldiers', '[]', 'Numbers mean nothing. Only strength matters!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15007, 'AkoyaFightBeginsPlayerLessSoldiers', '[]', 'Fighting outnumbered is a bold choice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15008, 'AkoyaFightBeginsPlayerMoreItems', '[]', 'Equipment cannot compensate for weakness!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15009, 'AkoyaFightBeginsPlayerLessItems', '[]', 'Did you even prepare for this battle?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15010, 'AkoyaFightBeginsPlayerMoreFieldItems', '[]', 'Your battlefield strategy won''t matter if you''re not strong enough to win!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15011, 'AkoyaFightBeginsPlayerLessFieldItems', '[]', 'Even if you''re strong, you can''t ignore the battlefield!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15012, 'AkoyaWarcry1', '[]', 'Vala Tukohama!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_09_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15013, 'AkoyaWarcry2', '[]', 'Makanui, ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_09_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15014, 'AkoyaWarcry3', '[]', 'Do battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_09_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15015, 'AkoyaWarcry4', '[]', 'Vala Tukohama!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_09_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15016, 'AkoyaWarcry5', '[]', 'Makanui, ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_09_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15017, 'AkoyaWarcry6', '[]', 'Do battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_09_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15018, 'AkoyaTeamTotemDestroyed1', '[]', 'Come on, team!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_10_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15019, 'AkoyaTeamTotemDestroyed2', '[]', 'Come on, team!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_10_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15020, 'AkoyaTeamTotemDestroyed3', '[]', 'They got us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_10_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15021, 'AkoyaTeamTotemDestroyed4', '[]', 'They got us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_10_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15022, 'AkoyaTeamTotemDestroyed5', '[]', 'Let''s rally!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_10_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15023, 'AkoyaTeamTotemDestroyed6', '[]', 'Let''s rally!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_10_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15024, 'AkoyaTotemDestroyed1', '[]', 'Good move!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_11_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15025, 'AkoyaTotemDestroyed2', '[]', 'Good move!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_11_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15026, 'AkoyaTotemDestroyed3', '[]', 'Hah, got me!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_11_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15027, 'AkoyaTotemDestroyed4', '[]', 'Hah, got me!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_11_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15028, 'AkoyaTotemDestroyed5', '[]', 'Oops!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_11_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15029, 'AkoyaTotemDestroyed6', '[]', 'Oops!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_11_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15030, 'AkoyaYourTeamTotemDestroyed1', '[]', 'Keep fighting!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_12_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15031, 'AkoyaYourTeamTotemDestroyed2', '[]', 'Keep fighting!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_12_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15032, 'AkoyaYourTeamTotemDestroyed3', '[]', 'You should have guarded your totems more carefully!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_12_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15033, 'AkoyaYourTeamTotemDestroyed4', '[]', 'You should have guarded your totems more carefully!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_12_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15034, 'AkoyaYourTeamTotemDestroyed5', '[]', 'Continue the assault!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_12_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15035, 'AkoyaYourTeamTotemDestroyed6', '[]', 'Continue the assault!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_12_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15036, 'AkoyaYourTotemDestroyed1', '[]', 'Not strong enough!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_13_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15037, 'AkoyaYourTotemDestroyed2', '[]', 'Not strong enough!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_13_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15038, 'AkoyaYourTotemDestroyed3', '[]', 'The Way prevails!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_13_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15039, 'AkoyaYourTotemDestroyed4', '[]', 'The Way prevails!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_13_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15040, 'AkoyaYourTotemDestroyed5', '[]', 'This battle nears its end!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_13_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15041, 'AkoyaYourTotemDestroyed6', '[]', 'This battle nears its end!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_13_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[607]', NULL, 0, 0, '[]', 100),
(15042, 'AkoyaCommentDefeatedYou1', '[]', 'The true victor emerges.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_14_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15043, 'AkoyaCommentDefeatedYou2', '[]', 'The true victor emerges.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_14_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15044, 'AkoyaCommentWhenDefeated1', '[]', 'Not bad, outsider. Not bad at all.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_15_01.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15045, 'AkoyaCommentWhenDefeated2', '[]', 'Not bad, outsider. Not bad at all.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Field/Akoya_Field_15_02.ogg', '', 0, 0, '', 1, 0, 1, '[607]', NULL, 0, 0, '[]', 100),
(15046, 'AkoyaCommentsFromStandsOnMatch1', '[]', 'You have honoured our Way!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(15047, 'AkoyaCommentsFromStandsOnMatch2', '[]', 'You have honoured our Way!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_26_02.ogg', '', 0, 0, '', 1, 0, 1, '[617]', NULL, 0, 0, '[]', 100),
(15048, 'AkoyaCommentPurchaseItem1', '[]', 'Our equipment is forged solely for war.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_01_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15049, 'AkoyaCommentPurchaseItem2', '[]', 'Our equipment is forged solely for war.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_01_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15050, 'AkoyaCommentPurchaseItem3', '[]', 'It will never fail you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_01_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15051, 'AkoyaCommentPurchaseItem4', '[]', 'It will never fail you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_01_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15052, 'AkoyaCommentPurchaseFieldItem1', '[]', 'Strategy is a kind of strength.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15053, 'AkoyaCommentPurchaseFieldItem2', '[]', 'Strategy is a kind of strength.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_02_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15054, 'AkoyaCommentPurchaseFieldItem3', '[]', 'Bolster your strengths, guard your weaknesses.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15055, 'AkoyaCommentPurchaseFieldItem4', '[]', 'Bolster your strengths, guard your weaknesses.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15056, 'AkoyaCommentInspectRecruits1', '[]', 'The Tukohama Tribe''s warriors cannot be matched.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15057, 'AkoyaCommentInspectRecruits2', '[]', 'The Tukohama Tribe''s warriors cannot be matched.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15058, 'AkoyaCommentInspectRecruits3', '[]', 'These are the best that ever lived.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15059, 'AkoyaCommentInspectRecruits4', '[]', 'These are the best that ever lived.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_03_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15060, 'AkoyaCommentInspectRecruits5', '[]', 'Each one has been tested and proven true.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_03_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15061, 'AkoyaCommentInspectRecruits6', '[]', 'Each one has been tested and proven true.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_03_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15062, 'AkoyaCommentRecruitRecruit1', '[]', 'You honour us with your choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15063, 'AkoyaCommentRecruitRecruit2', '[]', 'You honour us with your choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_04_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15064, 'AkoyaCommentRecruitRecruit3', '[]', 'Now, you will most certainly win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15065, 'AkoyaCommentRecruitRecruit4', '[]', 'Now, you will most certainly win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15066, 'AkoyaPlayerWonVsKaom', '[]', 'It was good that you defeated Kaom in battle. Our Way is about true strength, not arrogant boasts. He needs to learn the difference.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_09.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15067, 'AkoyaPlayerLostVsKaom', '[]', 'Kaom is one of the best I have ever seen. I will give him that. Next time, however, I would prefer that you find a way to defeat him.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_10.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15068, 'AkoyaPlayerWonVsUtula', '[]', 'Thank you for defeating Utula. Perhaps this may teach him some humility. I doubt it, but I still have hope.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_05.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15069, 'AkoyaPlayerLostVsUtula', '[]', 'If that battle had happened in life, Utula would be carving out your heart right now.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_06.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15070, 'AkoyaPlayerWonVsAhuana', '[]', 'Your battle with Ahuana was engaging to watch. I think she might have gone a bit easy on you, but you did win, and that is all that matters.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_11.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15071, 'AkoyaPlayerLostVsAhuana', '[]', 'Ahuana may speak kindly, but she is a true follower of the Way. You will need great strength to defeat her.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_12.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15072, 'AkoyaPlayerWonVsTawhanuku', '[]', 'I hope Tawhanuku did not see her loss coming.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_07.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15073, 'AkoyaPlayerLostVsTawhanuku', '[]', 'How shameful of her, to take a battle while already knowing the outcome. You must defeat Tawhanuku next time, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_08.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15074, 'AkoyaPlayerWonVsRakiata', '[]', 'I am surprised that you managed to defeat Rakiata. Well done.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_13.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15075, 'AkoyaPlayerLostVsRakiata', '[]', 'Rakiata has a fighting style all her own. It will take some time to adapt to it. Train hard for next time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_14.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15076, 'AkoyaPlayerWonAgainstThem', '[]', 'Defeat stings, but I am pleased you have embraced our Way. You have my respect.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_15.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15077, 'AkoyaPlayerLostAgainstThem', '[]', 'Victory must be earned. It is not so easily achieved.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_16.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15078, 'AkoyaPlayerWonNeutral', '[]', 'You fight like no warrior I have ever seen. Perhaps we should invite more outsiders here, to bring us new knowledge.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_17.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15079, 'AkoyaPlayerLostNeutral', '[]', 'Clearly, the Karui styles of fighting are superior, but I see potential in you. Perhaps, with enough training, you will have something to teach us.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_18.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15080, 'AkoyaCommentOnPurchaseItemAhuana', '[]', 'Interesting choice...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15081, 'AkoyaCommentOnPurchaseItemKiloava', '[]', 'Hmm... curious...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_28.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15082, 'AkoyaCommentOnPurchaseEliteAhuana', '[]', 'Ahuana''s warriors always fight with honour.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_30.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15083, 'AkoyaCommentOnPurchaseEliteKiloava', '[]', 'A formidable choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_29.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15084, 'AkoyaConversationWithAhuanaOne', '[]', 'Same as every other day down here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_32_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15085, 'AkoyaConversationWithAhuanaTwo', '[]', 'Actually... yes!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_32_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15086, 'AkoyaConversationWithKiloavaOne', '[]', 'Can you believe Hinekora accepted Kaom here?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_33_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15087, 'AkoyaConversationWithKiloavaTwo', '[]', 'Perhaps it is a chance to enact our vengeance...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_33_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15088, 'AkoyaRandomShout1', '[]', 'Stop running! This is a sacred place!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_31_01.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15089, 'AkoyaRandomShout2', '[]', 'Stop running! This is a sacred place!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya_Wild/Akoya_Wild_31_02.ogg', '', 0, 0, '', 1, 0, 1, '[597]', NULL, 0, 0, '[]', 100),
(15090, 'AkoyaGossipTukohamaPreDefeat', '[]', 'Our Father of War was the first to put axes in Karui hands. We learned that we could take from this world rather than accept what was given. Many of the other gods are generous, but why should we subsist in harmony with the land when we have the strength to be its masters?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_19.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15091, 'AkoyaGossipTukohamaPostDefeat', '[]', 'You have wounded us, outsider. Though he has slept for thousands of years, Tukohama plays a very real role in our cultural and spiritual lives. He helped create the Way, and he set the Ngakuramakoi on the proper path. With the defeat of our god, my tribe will suffer a mark of shame and a spiritual restlessness that I cannot overstate. I understand why you did what you did, and I will try to remain fair to you, but I am not certain I can ever forgive what you''ve done.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_20.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15092, 'AkoyaGossipNgakuramakoi', '[]', 'That word, ''Karui,'' is an informal name for anyone of the blood, whether a chieftain, a child, or a <i>{kaivana}. The Ngakuramakoi, however, are those who truly comprise our culture. They must be followers of the Way, and they must have passed their test of adulthood, at the Isle of Shrikes or elsewhere. A great warrior does not have to be Karui by blood to become Ngakuramakoi. It is rare, but it does happen. I shall be watching you with great interest.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_21.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15093, 'AkoyaGossipNgamahu', '[]', 'Thousands of years before I was born, the Tukohama Tribe and the Ngamahu Tribe were in continual conflict. A cycle of vengeance kept the two groups raiding each other, and they were beginning to lose their superior positions. There was a danger of the other tribes becoming dominant. To put an end to it, Ngamahu and Tukohama went through the traditions together. Tukohama aided her in the forging of a legendary axe, while her ring, a sign of fire and fertility, was given to us. Eventually, her ring passed down to me. Kaom took it, and my head, when he slew me in his bid to unite the tribes. It is our Way, but my defeat still stings.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_22.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15094, 'AkoyaGossipTawhanuku', '[]', 'I don''t know what to make of the Hinekora tribe. They have always lived halfway in death and halfway in life. Their eyes are elsewhere, and their words are meaningless. They have some kind of strength, but I don''t know what to make of it, and I certainly don''t feel they are passing down any wisdom to their descendants when they speak in riddles. Maybe it''s just the particular warriors here? I can''t imagine their children talking in prophecies and enigmas.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_23.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15095, 'AkoyaGossipDeath', '[]', 'My battle with Kaom began at sunrise. Our warriors were assembled on either side, ready to slaughter each other, but neither of us gave the sign. By dawn''s light, we fought on the sand, axe against axe. Kaom was strong, but arrogant, which showed through in his fighting style. When he overextended himself, I made him pay for it in blood. However, his greater strength kept me on the defensive. Every hour, the <i>{hatungo} called a truce, and we drank, ate, and were tended to. By nightfall, Kaom and I were moving like turtles, guarding ourselves behind our axes and taking only the most calculated movements. Eventually, he overextended again, and I dealt him a heavy wound to his chest—but this was an acceptable sacrifice he had made on purpose. He broke my knee with the end of his axe handle, and that was it. He gave me a warrior''s death, rather than leave me broken on the sands. I would not have had it any other way.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_24.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15096, 'AkoyaGossipUtula', '[]', 'Now Utula has been accepted here, and his fiery words make me wary. I believe in the traditional and unchanging Way, but Utula wants to tear it all down. I fear he is seeking to fulfill Kitava''s vow. We must show him how wrong he is.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_25.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15097, 'AkoyaGossipAhuana', '[]', 'Like Ramako in stories, Ahuana is a ray of light in this dark place. The Halls of the Dead are a good thing, but the years keep passing, and weigh heavily on all of us. Kahuturoa was one of the first souls here, and I fear becoming like him. Right now, after only three centuries or so, I can still take the Way seriously and uphold all of our traditions with pride. What will I be like in thousands of years? With good friends like Ahuana remaining positive, perhaps I can make it to the end with my dignity.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_26.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15098, 'AkoyaGossipKiloava', '[]', 'Kiloava makes grand claims about his own abilities, but he backs them up with the strength to win. I care little for bluster, so long as the warriors in these Halls adhere to the Way.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_27.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15099, 'AkoyaGossipTheEndOfTime', '[]', 'Personally, I hope it will not be too long before the end. I have already existed three centuries longer than I was alive. Each tribe has its own belief about how the world will end, but you must understand, these tales do not conflict. They are all correct. Our traditional expectations are not literal.' || char(13) || '
' || char(13) || '
Our <i>{hatungo} speaks of a time when all Ngakuramakoi will become so strong, and so skilled at warfare, that every man and woman will seek to become their own chieftain. Blood lust will take over the people, and war will continue until only one warrior remains. That warrior will be the strongest that ever lived in all of history, and he will die soon after from his wounds. His fallen body will become the new world, and his blood, the rivers. His dying warcry will become the sky, and his fierce eyes will become the new Sun and Moon. Of course, this is not a literal tale. It is meant to give us a sense of place in a chaotic existence. There is immense value in this. Our traditions give us meaning and purpose, that is why I have dedicated my life—and my death—to upholding them. Otherwise, we would be adrift, and full of fear.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_28.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15100, 'AkoyaGossipTheReturnOfTheGods', '[]', 'Like many others, the Karui gods have awakened, but aside from Tukohama and Kitava, we have heard nothing of their activities. They walk Wraeclast like in times of old, so—where are they? Our descendants come to us and ask us when the gods will return home. For this, we have no answer. Even Hinekora seems unwilling to speak on what she sees.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Akoya/Akoya/Akoya_29.ogg', '', 0, 0, '', 1, 0, 1, '[597,634]', NULL, 0, 0, '[]', 100),
(15101, 'TawhanukuLikesPlayerIsChampion', '[]', 'A strong chieftain must answer a challenge with blood.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15102, 'TawhanukuNeutralPlayerIsChampion', '[]', 'A wave may rise or fall, but there is always another.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15103, 'TawhanukuDislikesPlayerIsChampion', '[]', 'The Sun never dawns twice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15104, 'TawhanukuLikesPlayerLostLast', '[]', 'A mountain is only imposing until it is climbed.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15105, 'TawhanukuNeutralPlayerLostLast', '[]', 'Pain is simply the knowledge that you are alive.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15106, 'TawhanukuDislikesPlayerLostLast', '[]', 'The weak envy the strong.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15107, 'TawhanukuLikesPlayerNoRecord', '[]', 'Mysteries intrigue the mind...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15108, 'TawhanukuNeutralPlayerNoRecord', '[]', 'Fate has no favourites.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15109, 'TawhanukuDislikesPlayerNoRecord', '[]', 'The eyes of the watcher close when they see nothing of interest.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15110, 'TawhanukuCommentsOnAkoya', '[]', 'Jade idols may dot the battlefield, but only one moves with fierce intent.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15111, 'TawhanukuCommentsOnIkiaho', '[]', 'The Moon may be cold, but it is not lonely.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15112, 'TawhanukuCommentsOnKahuturoa', '[]', 'The boulder moves only when it must.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
(15113, 'TawhanukuCommentsOnKaom', '[]', 'The volcano''s rage is mighty indeed!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Tawhanuku/Tawhanuku_Wild/Tawhanuku_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[613]', NULL, 0, 0, '[]', 100),
