(15290, 'AhuanaCommentPurchaseFieldItem3', '[]', 'Battle control is key.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15291, 'AhuanaCommentPurchaseFieldItem4', '[]', 'Battle control is key.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15292, 'AhuanaCommentInspectRecruits1', '[]', 'The Ramako Tribe is unmatched in skill!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15293, 'AhuanaCommentInspectRecruits2', '[]', 'The Ramako Tribe is unmatched in skill!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15294, 'AhuanaCommentInspectRecruits3', '[]', 'You won''t find any of my warriors lacking.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15295, 'AhuanaCommentInspectRecruits4', '[]', 'You won''t find any of my warriors lacking.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_03_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15296, 'AhuanaCommentInspectRecruits5', '[]', 'What do you think?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_03_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15297, 'AhuanaCommentInspectRecruits6', '[]', 'What do you think?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_03_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15298, 'AhuanaCommentRecruitRecruit1', '[]', 'Nice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15299, 'AhuanaCommentRecruitRecruit2', '[]', 'Nice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_04_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15300, 'AhuanaCommentRecruitRecruit3', '[]', 'Good choice, my friend!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15301, 'AhuanaCommentRecruitRecruit4', '[]', 'Good choice, my friend!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15302, 'AhuanaCommentRecruitRecruit5', '[]', 'Victory just became that much closer!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_04_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15303, 'AhuanaCommentRecruitRecruit6', '[]', 'Victory just became that much closer!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_04_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15304, 'AhuanaPlayerWonVsUtula', '[]', 'I''m glad you defeated Utula. He is... well, he just doesn''t fit in, you know? He needs to understand that this is a positive place, not meant for anger and savagery.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_05.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15305, 'AhuanaPlayerLostVsUtula', '[]', 'Sorry about your loss, my friend. Utula takes everything a bit too seriously. Don''t let him bully you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_06.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15306, 'AhuanaPlayerWonVsAkoya', '[]', 'Great job against Koko! She''s no easy opponent!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_07.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15307, 'AhuanaPlayerLostVsAkoya', '[]', 'Koko is a fantastic fighter. You''ll have to hone your skills to take her down!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_08.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15308, 'AhuanaPlayerWonVsIkiaho', '[]', 'Defeating Iky was no mean feat. Keep up the good work!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_09.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15309, 'AhuanaPlayerLostVsIkiaho', '[]', 'Iky''s ice abilities are hard to counter. Maybe you''ll defeat her next time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_10.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15310, 'AhuanaPlayerWonVsKahuturoa', '[]', 'I greatly enjoyed your battle against Kahu. You two will have a laugh about it later, I''m sure!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_11.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15311, 'AhuanaPlayerLostVsKahuturoa', '[]', 'Sorry about your loss. Kahu is an incredible fighter. He''s the oldest soul here, so he certainly knows his stuff!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_12.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15312, 'AhuanaPlayerWonVsKaom', '[]', 'Kaom of legend, defeated by the newcomer. Now that''s a tale!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_13.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15313, 'AhuanaPlayerLostVsKaom', '[]', 'Take heart, my friend. Kaom is a legendary warrior. You''ll have another chance at him!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_14.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15314, 'AhuanaPlayerWonVsKiloava', '[]', 'Keely might act angry about his loss, but he''s secretly a softy. Don''t be intimidated!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_15.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15315, 'AhuanaPlayerLostVsKiloava', '[]', 'You almost had Keely, I just know it. Try to take him on again when you''re ready!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_16.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15316, 'AhuanaPlayerWonVsMaata', '[]', 'Old man Maata, taken down by the newcomer. That was a fight for the ages!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_17.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15317, 'AhuanaPlayerLostVsMaata', '[]', 'The old man''s wisdom counts for more in battle than most might think. You''ll have to outsmart him to truly defeat him!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_18.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15318, 'AhuanaPlayerWonVsRakiata', '[]', 'Rocky''s one of the best around. I''m amazed you beat her! Good on you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_19.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15319, 'AhuanaPlayerLostVsRakiata', '[]', 'The key to defeating Rocky is not so simple... you''ll have to study her unconventional fighting style. I''m sure you''ll figure it out!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_20.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15320, 'AhuanaPlayerWonVsTawhanuku', '[]', 'I''m surprised Toffee took that fight. She had to know she would lose. Maybe it''s for a reason we have yet to understand!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_21.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15321, 'AhuanaPlayerLostVsTawhanuku', '[]', 'Losing to Toffee is nothing to feel bad about. When she takes fights, it''s mostly because she''s already foreseen that she''s going to win! Takes quite the effort to subvert fate!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_22.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15322, 'AhuanaPlayerWonAgainstThem', '[]', 'I am impressed, my friend! You''re becoming a fantastic fighter!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_23.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15323, 'AhuanaPlayerLostAgainstThem', '[]', 'Try again next time, friend! I''m always here!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_24.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15324, 'AhuanaPlayerWonNeutral', '[]', 'Great work! That was a fun match to watch!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_25.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15325, 'AhuanaPlayerLostNeutral', '[]', 'You fought well! That''s the most any of us can hope for!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_26.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15326, 'AhuanaCommentOnPurchaseItemAkoya', '[]', 'If you want something made for war, go to the Tukohama Tribe, that''s what I always say!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15327, 'AhuanaCommentOnPurchaseItemKiloava', '[]', 'Valako Tribe equipment is always high quality!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_24.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15328, 'AhuanaCommentOnPurchaseEliteKiloava', '[]', 'Keely''s warriors are top tier!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_25.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15329, 'AhuanaCommentOnPurchaseEliteAkoya', '[]', 'Now that''s a warrior!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_26.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15330, 'AhuanaRandomShout1', '[]', 'I hope you''re having a good time, my friend!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_27_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15331, 'AhuanaRandomShout2', '[]', 'I hope you''re having a good time, my friend!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_27_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15332, 'AhuanaGossipTavukai', '[]', 'The ancient <i>{tavukai} against the use of projectile weapons is not a rule that applies to us. It was a matter of pride for those tribes that lauded brutish men with large axes. The Ramako Tribe prefers to fell warriors like that with well-placed arrows, long before their axes ever come close.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_27.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15333, 'AhuanaGossipHyrri', '[]', 'My mother was a great woman, and continues to be my role model, despite her inexplicable absence here. The other chieftains often talk about her wartime acts when she fought alongside Kaom, but by the time I was old enough to know her, she had long been Queen of the still-united tribes. I grew up in a time of turmoil and nightmare in the wake of the Cataclysm that destroyed the Eternals. Because she once helped put the men in power who likely caused it, my mother taught me that war is not the glorious endeavour our Way makes it out to be. All she wanted, by the end, was peace. She was begrudgingly taking an army raised from multiple tribes to deal with a strange threat on the edge of Ngamakanui... when she and her legion vanished without a trace. I did my best in the chaos that followed, but it wasn''t enough...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_28.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15334, 'AhuanaGossipCataclysm', '[]', 'I was quite young when the world ruptured. The moon turned crimson, fire rained from the sky, warriors went mad with blood fever, and the seas boiled. None of us knew what caused it, but the destruction came from the direction of Sarn, and the mountains near it. The madmen must have gone too far... I had nightmares about that time for over a decade, until I finally traveled to the Isle of the Shrikes and passed my test of adulthood. After that, I felt like I could handle anything.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_29.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15335, 'AhuanaGossipBeingQueen', '[]', 'After my mother''s disappearance, the tribes began to fracture. I tried to take on the role of Queen, but inheriting such a title felt a bit too much like monarchy and empire, and the other tribes weren''t receptive. Not after their experiences battling the Eternals. So, I used what meager power I had to suggest a new form of united government, a council of chieftains. From the trickle of news we get through living Karui that come to us for guidance, I hear that some form of that is still going on. I''m rather proud of that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_30.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15336, 'AhuanaGossipVictario', '[]', 'Oh, you''ve heard of my father? I''ve never met him. My mother only rolled her eyes whenever I asked about him. She told me of him once, the night before she left on her final campaign. She said he spoke with a poet''s grace and made myriad boastful promises, but his heart truly belonged to a dead woman. He remained in Sarn when she took our people home, so he must have died in the Cataclysm. I would very much like to know more about him.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_31.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15337, 'AhuanaGossipHyrriSoul', '[]', 'You found my mother''s soul? I knew she was still out there somewhere! Though I do not believe she needs our aid. If you knew my mother like I did, you would know that nothing could keep her trapped against her will, especially not with an army at her back. If she is still fighting there, then she must believe that the battle is necessary. We have no idea what the stakes are, so we should leave her to it. If she required our aid, she would have requested it long ago.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_32.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15338, 'AhuanaGossipDeath', '[]', 'I died in childbirth, which is considered a warrior''s death. I died knowing my daughter would live on. Then, because I was here, I was able to see her grow and thrive. She visited me for advice often, and I treasure those memories. Now, she fights as one of my own in these Halls. Among others, <i>{her} daughter, and her daughter''s daughter, also joined us. We now have dozens of descendants coming to us for wisdom. Life and death are strange partners. I have been here for far longer than I was alive, and my extended family only knows me as an ancestral spirit.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_33.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15339, 'AhuanaGossipTheEndOfTime', '[]', 'The other tribes tell all sorts of stories about the end of time. Those are just fables. You see, the Sun sets somewhere inside the world each night, but it also changes course from season to season. Eventually, it will stray too near, and Wraeclast will be burned away by its heat. However, the Sun brings life as well, so once it returns to the sky, as it always does, there will be a burst of verdancy unlike we have never ever seen. If you think about it, it''s the only end that makes sense.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_34.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15340, 'AhuanaGossipRamako', '[]', 'Ramako is both the Father of Light, and Father of the Sun. These are not the same duty. In the early days, he was just the Father of Light, and he brought beauty and warmth everywhere he went. The Mother of the Sun, Sione, lived alone in a jade palace in the sky. At that time, the Sun was no brighter than any other star, and it was verdant green. Sione, however, was the most ambitious of the gods. She traded away all of her tribe''s possessions to foreign cultures in exchange for gold, and she plated her entire palace with that useless but shiny material. Her tribe was on the verge of starvation, but she asked them to trust her. They put on a festival with what little they had left, and to this, Ramako was invited.' || char(13) || '
' || char(13) || '
In awe of the supposed wealth of Sione, Ramako accepted her invitation to go through the traditions together. Once he entered her golden palace, his light reflected countless times, blazing warmth and life all over the world. Sione''s palace cyclically rose above the world, then back into it, and while it was in the sky, that time became known as Day. To her credit, this shining beacon drew food, wealth, and respect to her tribe. Her gambit paid off. Ramako became the Father of the Sun ever after.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_35.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15341, 'AhuanaGossipRongokurai', '[]', 'Ah, Ramako''s brother! During the traditions, when Ramako first joined with Sione, Rongokurai came to the feasts at her palace. This confused the people and the animals, as the sky became dark at strange times when Rongokurai''s darkness dimmed the reflecting light of her golden walls. This greatly irritated Sione, but there was nothing she could do. He was family! Her own sister often caused such disruptions already when that silver palace neared hers, and now Ramako''s brother would interfere as well. She resolved to hold family gatherings as little as possible. That is why eclipses only happen every few years. The two sisters put aside their eternal war for a brief time to satisfy their traditional familial obligations. Even the gods must follow the Way.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_36.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15342, 'AhuanaGossipLaniHua', '[]', 'Ah... yes... Ramako was  impersonated by someone who visited Lani Hua, the Mother of the Moon, in his guise. My ancestors suspected the truth of this immediately. Arohongui had a very strange inheritance, with abilities prone to darkness and illusions, quite unlike Ramako''s golden strength and honesty. There is a tale, very rarely told, of a deceiver being caught and locked away for this crime. Supposedly, it was the ancient elders of my tribe that enacted this justice. We consider the matter settled, but Sione and Lani Hua continue to battle for eternity in distant realms... they do not listen to us. They do not listen to anyone. All they care about is vengeance. It might be controversial in Western Ngamakanui, but I say that the gods who forget their people are not owed our loyalty.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana/Ahuana_37.ogg', '', 0, 0, '', 1, 0, 1, '[596,633]', NULL, 0, 0, '[]', 100),
(15343, 'AhuanaConversationWithAkoyaOne', '[]', 'How are you doing today, Koko?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_28_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15344, 'AhuanaConversationWithAkoyaTwo', '[]', 'So, good then?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_28_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15345, 'AhuanaConversationWithKiloavaOne', '[]', 'Perfection is a goal, not a destination!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_29_01.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15346, 'AhuanaConversationWithKiloavaTwo', '[]', 'Of course you are, Keely!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ahuana/Ahuana_Wild/Ahuana_Wild_29_02.ogg', '', 0, 0, '', 1, 0, 1, '[596]', NULL, 0, 0, '[]', 100),
(15347, 'KahuturoaLikesPlayerIsChampion', '[]', 'Another win would please me, makanga!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15348, 'KahuturoaNeutralPlayerIsChampion', '[]', 'Makanga! I don''t care what happens in this fight. That is all!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15349, 'KahuturoaDislikesPlayerIsChampion', '[]', 'I hope you lose, makanga!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15350, 'KahuturoaLikesPlayerLostLast', '[]', 'You must not fail like last time, outsider!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15351, 'KahuturoaNeutralPlayerLostLast', '[]', 'I expect nothing from this battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15352, 'KahuturoaDislikesPlayerLostLast', '[]', 'Do not bore me again!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15353, 'KahuturoaLikesPlayerNoRecord', '[]', 'I would like to see what the outsider is capable of!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15354, 'KahuturoaNeutralPlayerNoRecord', '[]', 'What is this? Who is fighting? I wasn''t listening!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15355, 'KahuturoaDislikesPlayerNoRecord', '[]', 'Why are we letting an outsider fight? Who is this again?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15356, 'KahuturoaCommentsOnKaom', '[]', 'Swing that axe as hard as you can, Kaom! I''ll catch any wayward heads! Ha ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15357, 'KahuturoaCommentsOnRakiata', '[]', 'Careful, outsider! When Rakiata loses, she becomes as salty as the sea!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15358, 'KahuturoaCommentsOnIkiaho', '[]', 'The night belongs to us, Ikiaho, not to the meddling Moon!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15359, 'KahuturoaCommentsOnKiloava', '[]', 'Who blusters like a hurricane, but fights like a light spring rain?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15360, 'KahuturoaCommentsOnTawhanuku', '[]', 'I miss when Navali used to fight for Hinekora!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15361, 'KahuturoaCommentsOnMaata', '[]', 'Go on, tree man! Show us the blinding speed of an unmoving oak! Ha ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15362, 'KahuturoaCommentsOnUtula', '[]', 'That Utula is going to rip someone apart!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15363, 'KahuturoaCommentsOnAhuana', '[]', 'Give them an arrow in the eye, Ahuana!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15364, 'KahuturoaCommentsOnAkoya', '[]', 'Is that Akoya? Everything''s jade, I can''t see!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[618]', NULL, 0, 0, '[]', 100),
(15365, 'KahuturoaFightBeginsPlayerWonLast1', '[]', 'I must retake my honour!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15366, 'KahuturoaFightBeginsPlayerWonLast2', '[]', 'I must retake my honour!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15367, 'KahuturoaFightBeginsPlayerLostLast1', '[]', 'I will probably defeat you again!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15368, 'KahuturoaFightBeginsPlayerLostLast2', '[]', 'I will probably defeat you again!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15369, 'KahuturoaFightBeginsPlayerMoreSoldiers1', '[]', 'More soldiers does not mean a greater chance for victory!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15370, 'KahuturoaFightBeginsPlayerMoreSoldiers2', '[]', 'More soldiers does not mean a greater chance for victory!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15371, 'KahuturoaFightBeginsPlayerLessSoldiers1', '[]', 'Fighting us outnumbered seems unwise!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15372, 'KahuturoaFightBeginsPlayerLessSoldiers2', '[]', 'Fighting us outnumbered seems unwise!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
(15373, 'KahuturoaFightBeginsPlayerMoreItems1', '[]', 'That''s a lot of equipment! Compensating much?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Field/Kahuturoa_Field_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[605]', NULL, 0, 0, '[]', 100),
