(15441, 'KahuturoaPlayerWonVsIkiaho', '[]', 'The Moon hangs a bit lower in the sky tonight, outsider. Good work.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_05.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15442, 'KahuturoaPlayerLostVsIkiaho', '[]', 'Ikiaho knows how to leave a mark. Believe me, I know.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_06.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15443, 'KahuturoaPlayerWonVsKiloava', '[]', 'You defeated Kiloava. That makes me happy.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_07.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15444, 'KahuturoaPlayerLostVsKiloava', '[]', 'Please stop losing to Kiloava.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_08.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15445, 'KahuturoaPlayerWonVsMaata', '[]', 'I don''t understand Maata, but I do like it when he gets a beating.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_09.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15446, 'KahuturoaPlayerLostVsMaata', '[]', 'You lost... to Maata. You need to practice before you fight again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_10.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15447, 'KahuturoaPlayerWonVsRakiata', '[]', 'Rakiata is highly capable. I am surprised you defeated her. It may just be luck.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_11.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15448, 'KahuturoaPlayerLostVsRakiata', '[]', 'I bet on you, and lost. Defeat Rakiata next time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_12.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15449, 'KahuturoaPlayerWonVsAhuana', '[]', 'I''m certain Ahuana is proud that you defeated her. She is not a woman of ego.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_13.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15450, 'KahuturoaPlayerLostVsAhuana', '[]', 'Ahuana is trying to teach you through battle. You should listen.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_14.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15451, 'KahuturoaPlayerWonVsKaom', '[]', 'Kaom will not take his loss well. Don''t take it to heart. He''s got some things to work through.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_15.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15452, 'KahuturoaPlayerLostVsKaom', '[]', 'Kaom will never let you hear the end of your loss, ha ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_16.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15453, 'KahuturoaPlayerWonVsUtula', '[]', 'Perhaps you are the most savage warrior of them all! Have no doubt, Utula will remember his defeat.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_17.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15454, 'KahuturoaPlayerLostVsUtula', '[]', 'Utula is a savage warrior. You''ll need more to take him down.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_18.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15455, 'KahuturoaPlayerWonAgainstThem', '[]', 'Not bad. I enjoy a challenge. You did well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_19.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15456, 'KahuturoaPlayerLostAgainstThem1', '[]', 'Keep training and improving. You''ll get there.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_20_01.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15457, 'KahuturoaPlayerLostAgainstThem2', '[]', 'You''ll get me next time. Keep training.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_20_02.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15458, 'KahuturoaPlayerWonNeutral', '[]', 'Did you win your battle? I wasn''t paying much attention.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_21.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15459, 'KahuturoaPlayerLostNeutral', '[]', 'Did you just lose a battle? I don''t know any of the rankings at the moment.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_22.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15460, 'KahuturoaCommentOnPurchaseItemIkiaho', '[]', 'Careful! That one''s got a heart of ice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_21.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15461, 'KahuturoaCommentOnPurchaseEliteMaata', '[]', 'Yes, buy a skilled warrior from a peacemaker! Ha ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_22.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15462, 'KahuturoaCommentOnPurchaseEliteUtula', '[]', 'Utula''s warriors are the finest alive! Or... dead.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15463, 'KahuturoaCommentOnPurchaseEliteKaom', '[]', 'Kaom''s warriors once took on all of Wraeclast!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_24.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15464, 'KahuturoaRandomShout1', '[]', 'When''s the next match? I didn''t know being dead involved so much waiting!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15465, 'KahuturoaRandomShout2', '[]', 'Is it day or night right now? Does anyone know?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15466, 'KahuGossipOnRongokurai', '[]', 'Rongokurai is the Father of Night. Many associate that with evil. Not so. The night shrouds the innocent, hiding them from those who would do harm. The night gives cover to warriors on their raids. More importantly, the night is cool, bringing relief from a hot day. My armour is heavy, and gets quite hot, so I look forward to the sunset. It''s the little things.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_23.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15467, 'KahuGossipOnRamako', '[]', 'Oh, oh, let me tell you this tale of this ancient drama. Sione is the harsh and ambitious Mother of the Sun, yes? Ramako is her, what is your word? Husband. Ramako can''t stand her, and secretly longs for Lani Hua, the Mother of the Moon, who is kind and caring to all, and very beautiful as well. Ramako goes to our Father of Night, Rongokurai, and asks for the cover of darkness to secretly visit Lani Hua without his wife knowing. Poor Rongo, being a good brother, obliges. Ramako visits Lani Hua many times, until... as happens with such things... Arohongui is born. Sione becomes <i>{furious}, as you can imagine. The Sun becomes so bright, fire scorches the world... ' || char(13) || '
' || char(13) || '
My tribe survives that fire easily because we tend to live in caves, but Lani Hua, being a natural healer, steps in to preserve the rest of the Karui. Sione goes to war against her, and she and Lani Hua have been fighting <i>{ever since}. Now, Ramako lives alone in his golden palace, and Arohongui tends wounded souls in the silver palace of the Moon, taking care of it in her mother''s absence. The most absurd part? Ramako claims it wasn''t him! He calls his brother a liar, and now Ramako and Rongo don''t speak. The Day and the Night are forever avoiding each other because the Father of the Sun couldn''t keep his belt tied on... fortunately, we Karui are much more mature and responsible in modern times.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_24.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15468, 'KahuGossipOnTheHallsOfTheDead', '[]', 'I don''t enjoy fighting all that much. I just happen to be very good at it. I was given this position because I kept winning. The others get very excited for every battle, but there are parts of the Halls of the Dead I wish I could see. Supposedly, there is a place for the souls of warriors that weren''t very skilled, and there they laze around in ''dishonour'' eating, drinking, and doing whatever they want. Where would you rather be, outsider?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_25.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15469, 'KahuGossipOnIkiaho', '[]', 'The afterlife is long, outsider. Think of the longest time you can remember. A winter that went on for many extra months, or back to your childhood. That long. Then it''s even longer than <i>{that}. We might be dead here, but we''re all still alive. Everyone here has gone through the traditions with everyone else. Some were even married for centuries. Eventually, though, time has a way of wearing everything away. You think you''ve found your partner for eternity, then a hundred years later, you find the same thing with someone else... but not Ikiaho. Never Ikiaho. She turns down everyone, even <i>{me}, and quite publicly. She has been alone all this time...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_26.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15470, 'KahuGossipOnKaom', '[]', 'He is a legendary warrior, but still new to the Halls of the Dead. One of the first things he did when he got here was show interest in Ikiaho, because he had heard she refuses all suitors. Surely, the great Kaom could thaw this frozen heart! No. She turned him down in front of everyone during meal time. Ha ha! That Kaom, what an ego!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_27.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15471, 'KahuGossipOnUtula', '[]', 'Utula has the right idea. Why should we Karui listen to anyone who tells us what to do and how to live? We have such strength, yet we remain subservient. If I want to leave the Halls of the Dead and go to the Chambers of the Dishonoured, where they drink and carouse for eternity, why shouldn''t I? Down with tyranny!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_28.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15472, 'KahuGossipOnTheEndOfTime', '[]', 'Oh, you''ve been talking to the Hinekora Tribe, have you? They''re very dramatic with the end of time fable. The Rongokurai Tribe has a much more dignified end in mind. When the world gets tired, it will be a quiet and calm slip into twilight, a night that goes on so long it blends into death itself. No more sunlight, no more plants, no more animals... no more people. Then, just as it always has, the sun will rise again on a new world. With sunlight comes plants, then animals... then people. It''s obvious!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_29.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15473, 'KahuGossipOnKitavasDefeat', '[]', 'You defeated Kitava, did you? Which one is that again? The Hungry God? No, the God of Hunger, right? There are so many Karui tribes, and so many gods. We don''t all share the same ones, either. There are tribes in Western Ngamakanui, beyond Ezomyr, with gods most of us are barely aware of. Those tribes are strange, and we don''t go there.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_30.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15474, 'KahuGossipOnNgamakanui', '[]', 'Ngamakanui isn''t a place, not really. <i>{Makanui} is our Way, and <i>{Nga} means ''from'' or ''of.'' So anywhere that our people go—mostly islands, we like to roam—that is Ngamakanui, because we have brought our Way to it. Outsiders that don''t understand us often mark Ngamakanui in a particular place on a map, but that is a mistake we don''t care to correct. It is better that the Vaal don''t know where we are. Speaking of the Vaal, I haven''t heard anything about them in a long time. I wonder how they''re doing these days...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_31.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15475, 'KahuGossipOnTheVaal', '[]', 'Oh... the Vaal are <i>{dead?} All of them? They were such a massive empire in my time... that''s... unsettling... well, at least our friends, the Azmeri, can move on down from the mountains now and set up an empire of their own.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_32.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15476, 'KahuGossipOnTheEternalEmpire', '[]', 'Oh... the Azmeri <i>{did} set up an empire, and <i>{they died too?} What''s going on up there?! I suppose that golden cult they banished to Oriath is going to take over the world now!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_33.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15477, 'KahuGossipOnOriathsDestruction', '[]', 'Oriath <i>{did} become a dominant power, and then <i>{it got destroyed too?!} Wraeclast is a disaster! Who''s even left? The Maraketh? At the very least, the lush rivers and forests of that verdant region will still carry on some form of beauty in Wraeclast!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_34.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15478, 'KahuGossipOnTheVastiriDesert', '[]', 'Vastiri <i>{Desert?} The rivers and the forests are gone? Everything I knew has been erased by time! Everyone I mention, turns out they''re dead! I should just stop asking, but I have to know! The Ezomytes...?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_35.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15479, 'KahuGossipOnTheEzomytes', '[]', 'Ah. A plague wiped out Ezomyr? Of course. I''ve been down here thousands of years! Everything and everyone I''ve ever heard of... all dead! What about the Caaltu? They had the absolute best wines, feasts that went on for days, and the women... by Rongo, the women! Please tell me the Caaltu are still thriving!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_36.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15480, 'KahuGossipOnTheCaaltu', '[]', 'You''ve never even <i>{heard} of the Caaltu? I give up! Nothing makes sense anymore, and Wraeclast is, apparently, a cursed wasteland that only leads to oblivion!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_37.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15481, 'KahuGossipOnDeath', '[]', 'Don''t you know it''s rude to ask a man about his death?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa/Kahuturoa_38.ogg', '', 0, 0, '', 1, 0, 1, '[598,635]', NULL, 0, 0, '[]', 100),
(15482, 'KahuConversationWithRakiataOne', '[]', 'Rakiata, shall we give it another go?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15483, 'KahuConversationWithTawhanukuOne', '[]', 'Cryptic woman, are you calling me fat?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_28.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15484, 'KahuConversationWithIkiahoOne', '[]', 'How goes it, Ikiaho?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_29_01.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15485, 'KahuConversationWithIkiahoTwo', '[]', 'I was just being friendly!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_29_02.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15486, 'KahuConversationWithMaataOne', '[]', 'What? I can''t hear you from over there! Speak up, old man!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kahuturoa/Kahuturoa_Wild/Kahuturoa_Wild_30.ogg', '', 0, 0, '', 1, 0, 1, '[598]', NULL, 0, 0, '[]', 100),
(15487, 'MaataLikesPlayerIsChampion', '[]', 'You already know how to win, makanga. Do not falter!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15488, 'MaataNeutralPlayerIsChampion', '[]', 'Let''s see if this upstart can remain makanga!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15489, 'MaataDislikesPlayerIsChampion', '[]', 'The title must be retaken by a proper Karui tribe!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15490, 'MaataLikesPlayerLostLast', '[]', 'Your previous defeat was a learning experience! Move forward!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15491, 'MaataNeutralPlayerLostLast', '[]', 'Perhaps this upstart now has something to prove!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15492, 'MaataDislikesPlayerLostLast', '[]', 'This will be a savage one!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15493, 'MaataLikesPlayerNoRecord', '[]', 'Show us your foreign skills!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15494, 'MaataNeutralPlayerNoRecord', '[]', 'I am curious to see what the newcomer can do.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15495, 'MaataDislikesPlayerNoRecord', '[]', 'I do not expect much from this one.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15496, 'MaataCommentsOnRakiata', '[]', 'This battle could go either way.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15497, 'MaataCommentsOnIkiaho', '[]', 'I am curious to see how effective Ikiaho will be in this fight.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15498, 'MaataCommentsOnKiloava', '[]', 'The first Herald of War will put on a good show.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15499, 'MaataCommentsOnTawhanuku', '[]', 'Is it fair that the judge belongs to this tribe?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100);
INSERT INTO "NPCTextAudio" ("_row", "Id", "Characters", "Text", "Mono_AudioFile", "Stereo_AudioFile", "HasStereo", "__col6", "Video", "__col8", "__col9", "__col10", "NPCs", "NPCPortrait", "__col13", "__col14", "Cooldown", "__col16") VALUES
(15500, 'MaataCommentsOnKaom', '[]', 'I hope Kaom''s abilities haven''t dulled after so long away from us.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15501, 'MaataCommentsOnUtula', '[]', 'Warmonger and savage! Feel the sting of an enemy''s blade!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15502, 'MaataCommentsOnAhuana', '[]', 'Seems unfair that Ahuana can use ranged weaponry.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15503, 'MaataCommentsOnAkoya', '[]', 'Achieve victory for the Karui, Akoya!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15504, 'MaataCommentsOnKahuturoa', '[]', 'I''m not convinced Kahuturoa wants to be here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[614]', NULL, 0, 0, '[]', 100),
(15505, 'MaataFightBeginsPlayerWonLast1', '[]', 'You might have defeated me before, but there is balance in all things.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15506, 'MaataFightBeginsPlayerWonLast2', '[]', 'You might have defeated me before, but there is balance in all things.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15507, 'MaataFightBeginsPlayerLostLast1', '[]', 'I hope you have trained hard since last we fought.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15508, 'MaataFightBeginsPlayerLostLast2', '[]', 'I hope you have trained hard since last we fought.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15509, 'MaataFightBeginsPlayerMoreSoldiers1', '[]', 'Greater numbers do not always mean a better chance at victory.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15510, 'MaataFightBeginsPlayerMoreSoldiers2', '[]', 'Greater numbers do not always mean a better chance at victory.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15511, 'MaataFightBeginsPlayerLessSoldiers1', '[]', 'Fighting outnumbered is not a wise strategy.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15512, 'MaataFightBeginsPlayerLessSoldiers2', '[]', 'Fighting outnumbered is not a wise strategy.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15513, 'MaataFightBeginsPlayerMoreItems1', '[]', 'You came prepared! That is wise.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15514, 'MaataFightBeginsPlayerMoreItems2', '[]', 'You came prepared! That is wise.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15515, 'MaataFightBeginsPlayerLessItems1', '[]', 'You seem underprepared. It may cost you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15516, 'MaataFightBeginsPlayerLessItems2', '[]', 'You seem underprepared. It may cost you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15517, 'MaataFightBeginsPlayerMoreFieldItems1', '[]', 'I see you''re attempting to control the battlefield. It might work.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15518, 'MaataFightBeginsPlayerMoreFieldItems2', '[]', 'I see you''re attempting to control the battlefield. It might work.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15519, 'MaataFightBeginsPlayerLessFieldItems1', '[]', 'You can''t ignore the battlefield and hope to win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15520, 'MaataFightBeginsPlayerLessFieldItems2', '[]', 'You can''t ignore the battlefield and hope to win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15521, 'MaataWarcry1', '[]', 'For Tawhoa!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_09_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15522, 'MaataWarcry2', '[]', 'For Tawhoa!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_09_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15523, 'MaataWarcry3', '[]', 'Father of the Forest, lend us your might!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_09_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15524, 'MaataWarcry4', '[]', 'Father of the Forest, lend us your might!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_09_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15525, 'MaataWarcry5', '[]', 'Let''s rap some skulls!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_09_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15526, 'MaataWarcry6', '[]', 'Let''s rap some skulls!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_09_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15527, 'MaataChallengesPlayer1', '[]', 'Let us see if strength can triumph over wisdom!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_10_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15528, 'MaataChallengesPlayer2', '[]', 'Let us see if strength can triumph over wisdom!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_10_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15529, 'MaataTeamTotemDestroyed1', '[]', 'How dare you defile sacred wood!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_11_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15530, 'MaataTeamTotemDestroyed2', '[]', 'How dare you defile sacred wood!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_11_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15531, 'MaataTeamTotemDestroyed3', '[]', 'A single trunk is lost, but the forest remains!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_11_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15532, 'MaataTeamTotemDestroyed4', '[]', 'A single trunk is lost, but the forest remains!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_11_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15533, 'MaataTeamTotemDestroyed5', '[]', 'We will persevere!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_11_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15534, 'MaataTeamTotemDestroyed6', '[]', 'We will persevere!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_11_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15535, 'MaataTotemDestroyed1', '[]', 'I believe in my warriors!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_12_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15536, 'MaataTotemDestroyed2', '[]', 'I believe in my warriors!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_12_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15537, 'MaataTotemDestroyed3', '[]', 'My warriors can still win this!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_12_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15538, 'MaataTotemDestroyed4', '[]', 'My warriors can still win this!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_12_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
(15539, 'MaataTotemDestroyed5', '[]', 'The mightiest tree is not the only tree, merely the tallest...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_12_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[602]', NULL, 0, 0, '[]', 100),
