(15553, 'MaataCommentDefeatedYou1', '[]', 'You have much to learn, child.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_15_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15554, 'MaataCommentDefeatedYou2', '[]', 'You have much to learn, child.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_15_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15555, 'MaataCommentDefeatedYou3', '[]', 'I hope you think on this, and learn from your mistakes.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_15_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15556, 'MaataCommentDefeatedYou4', '[]', 'I hope you think on this, and learn from your mistakes.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Field/Maata_Field_15_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15557, 'MaataCommentsWhenDefeated1', '[]', 'A fair fight. Honourable!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_21_01.ogg', '', 0, 0, '', 1, 0, 1, '[602]', NULL, 0, 0, '[]', 100),
(15558, 'MaataCommentPurchaseItem1', '[]', 'That carries Tawhoa''s blessing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_01_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15559, 'MaataCommentPurchaseItem2', '[]', 'That carries Tawhoa''s blessing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_01_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15560, 'MaataCommentPurchaseItem3', '[]', 'Trade is the essence of understanding.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_01_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15561, 'MaataCommentPurchaseItem4', '[]', 'Trade is the essence of understanding.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_01_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15562, 'MaataCommentPurchaseFieldItem1', '[]', 'Make your own forest, then fight among the trunks.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15563, 'MaataCommentPurchaseFieldItem2', '[]', 'Make your own forest, then fight among the trunks.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_02_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15564, 'MaataCommentPurchaseFieldItem3', '[]', 'Battles are won before they are ever fought.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15565, 'MaataCommentPurchaseFieldItem4', '[]', 'Battles are won before they are ever fought.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15566, 'MaataCommentInspectRecruits1', '[]', 'Warriors of Tawhoa stand tall.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15567, 'MaataCommentInspectRecruits2', '[]', 'Warriors of Tawhoa stand tall.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15568, 'MaataCommentInspectRecruits3', '[]', 'Any of my warriors will serve you diligently.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15569, 'MaataCommentInspectRecruits4', '[]', 'Any of my warriors will serve you diligently.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_03_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15570, 'MaataCommentInspectRecruits5', '[]', 'Think long on your choices.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_03_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15571, 'MaataCommentInspectRecruits6', '[]', 'Think long on your choices.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_03_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15572, 'MaataCommentRecruitRecruit1', '[]', 'A fine warrior.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15573, 'MaataCommentRecruitRecruit2', '[]', 'A fine warrior.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_04_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15574, 'MaataCommentRecruitRecruit3', '[]', 'You are assembling a good team.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15575, 'MaataCommentRecruitRecruit4', '[]', 'You are assembling a good team.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15576, 'MaataCommentRecruitRecruit5', '[]', 'I''m impressed. Good choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_04_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15577, 'MaataCommentRecruitRecruit6', '[]', 'I''m impressed. Good choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_04_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15578, 'MaataPlayerWonVsUtula', '[]', 'I am glad you taught Utula some humility. Whether he will take your lesson to heart remains to be seen.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_05.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15579, 'MaataPlayerLostVsUtula', '[]', 'Utula will be insufferable after defeating you. He needs to learn that not all problems can be solved with violence.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_06.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15580, 'MaataPlayerWonVsAkoya', '[]', 'You fought well, and honourably, against Akoya. I can tell she enjoyed herself.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_07.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15581, 'MaataPlayerLostVsAkoya', '[]', 'Did you learn anything from your loss to Akoya? Apply those lessons to your training.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_08.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15582, 'MaataPlayerWonAgainstThem', '[]', 'Our match was quite enjoyable! I hope to fight you again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_09.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15583, 'MaataPlayerLostAgainstThem', '[]', 'I did not defeat you to humiliate you, but to teach you. Think on our contest, and you will find room for improvement.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_10.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15584, 'MaataPlayerWonNeutral', '[]', 'You''re advancing quite well! I look forward to seeing you grow.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_11.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15585, 'MaataPlayerLostNeutral', '[]', 'Take heart. Yes, you lost, but you held yourself well. You may one day earn a place here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_12.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15586, 'MaataCommentOnPurchaseItemUtula', '[]', 'I wouldn''t trust anything from that warmonger!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_22.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15587, 'MaataCommentOnPurchaseEliteAkoya', '[]', 'You can rely on Akoya''s warriors!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15588, 'MaataCommentOnPurchaseEliteUtula', '[]', 'Careful his warriors don''t betray you on the field!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_24.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15589, 'MaataRandomShout1', '[]', 'The Halls of the Dead echo with battle, but in our hearts, there is peace!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15590, 'MaataRandomShout2', '[]', 'Each day, we grow. Never forget that tomorrow is another day!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15591, 'MaataGossipTawhoa', '[]', 'Tawhoa is the Son of the Forest, and its Father. His alone is the perspective of the ages, of centuries of life, growth, death, and decay. We exist within a grand cycle, one that extends far beyond the outcomes of petty battles or even great wars. Tawhoa stands apart from all this, aiming not for any grand goal, but simply to teach. That is why he gifted us with the ability to dream, so that we may see beyond ourselves. Inner peace can only be attained by accepting that life and death are inevitable. You, young one. Do you wish to waste away your time fighting here in the Halls of the Dead? Or do you want to live what time you have left to the fullest? Only you know the answer.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_13.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15592, 'MaataGossipHisRole', '[]', 'You must be wondering how an old man comes to find himself among these honoured warriors. I practiced a very different type of combat, one that operated in ways that we Karui normally disdain. I was a diplomat, a peacemaker, and an ambassador. In contrast to the warriors around me, I brought unmatched prosperity to my tribe not by raiding or conquest, but through cooperation. I was brought here because it is important that the young and headstrong do not forget the importance of these values. That, and I can crack a skull or two with my cane. So listen when I speak, child! Or you''ll get a tap!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_14.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15593, 'MaataGossipTheVaal', '[]', 'My fellow Karui never wanted to face the hard truth: if the Vaal wanted to wipe us out, they could have. They wouldn''t even have needed to invade us, and our lauded might would have been useless. Their Empire rose to power on the back of Corruption, and those gems the Azmeri called the Tears of Maji. Corruption has a tendency to make Karui sick with a kind of... blood fever. That is the true reason our Way forbids the use of Tears of Maji.' || char(13) || '
' || char(13) || '
During my life, a handful of Karui tried to implant them in their flesh. They became filled with rage and unnatural strength, and we had to put them down... then burn their bodies. Their mere proximity made others sick, too, so for every warrior that transgressed, five others gave their lives to protect the rest of us. To wipe us out, the Vaal could have simply spread the blood fever. My peacemaking, concessions, and treaties were born of that vulnerability, and I am glad I forged such a path. The Vaal Empire eventually succumbed to its own disease, and we remained.' || char(13) || '
', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_15.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15594, 'MaataGossipInnerPeace', '[]', 'Stand still for a moment. You''re always running all over the place! Ask yourself: how are you feeling? Are you alright? What is it that you truly need? Why aren''t you pursuing it? The answers will not bring you peace, but it''s a good first step.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_16.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15595, 'MaataGossipUtula', '[]', 'Utula believes in everything I have fought against my entire life... and my entire death. His is an ethos of violence, depravity, and anarchy. I believe the Karui deserve order, harmony, and peace. You can''t live in a beautiful forest if you burn it down. I understand why Utula was given a place here, but I still think it is a step in the wrong direction.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_17.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15596, 'MaataGossipKaom', '[]', 'Kaom mocks my peacemaking ways, but what did his warmongering earn him? Centuries of torture in a corrupted nightmare. I see no reason to quarrel with him. He already knows the truth.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_18.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15597, 'MaataGossipLessons', '[]', 'In this world, there are several routes to power. There is personal power, which was best exemplified by Kaom personally besting the leaders of each tribe and uniting the Karui with his own strength. There is communal power, which I try to exemplify. Cooperation and unity produce great works that last for thousands of years. Then, there is faith, which we have yet to fully understand. Somehow, in a bygone era, it turned exceptional men and women into divine beings... I wonder, after all you have done, how many people believe in <i>{you?}', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_19.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15598, 'MaataGossipTheEndOfTime', '[]', 'The other tribes have it all wrong. We exist in a grand cycle, yes, but there will be no singular moment or event that marks some sort of disastrous end. You were a seedling. You grew into an infant, then a child, then an adult, and one day you will be old... And then, you will die. But in every stage of your life, there were others just beginning theirs. When you die, there will be others just starting their lives. A tree falls, but that only clears the way for new seedlings. Trees die every season, but the forest remains. So it is with the Karui, and, indeed, all peoples. So it is with the world itself. Nothing ever ends, the perspective of existence just... shifts.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_20.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15599, 'MattaGossipInterconnectedness', '[]', 'The Tawhoa tribe found its unique perspective in the ancient days. The forest depends upon the light given by Ramako. It also depends upon the rains brought by Valako, and the coolness brought by Rongokurai. At night, we hunted by the light given by Lani Hua, and then Arohongui, her daughter. As you can see, right from the start, we realised that our existence is inextricably linked with all life... and theirs is linked with ours. Some tribes are too blind or arrogant to see this connection, and we try to pull them back from their excesses, so that we may all thrive.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_21.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15600, 'MaataGossipTheHallsOfTheDead', '[]', 'While I greatly enjoy advising generations of Karui that come to us for wisdom, I do wonder if the Halls of the Dead are a good idea in and of themselves. Hinekora brings our souls here after we die, but where do the souls of other peoples go? Where would we have gone? We assume the alternative is oblivion, but nobody knows for certain. These unanswerable questions plague me at night, when I am trying to sleep.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_22.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15601, 'MaataOnTheCaaltu', '[]', 'The Caaltu? I vaguely recall hearing about them once as a child, but they were long before my time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_23.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15602, 'MaataOnKahuturoa', '[]', 'Kahuturoa has been here the longest of any of us, since the Halls of the Dead were first forged by Hinekora. It feels strange saying this, because I look so much older, but I worry about the effect the years are having on him...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_24.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15603, 'MaataOnDeath', '[]', 'Alone among the warriors here, I lived my full life, and died of old age. I consider it a mark not of cowardice, but of a master strategist who was never defeated.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata/Maata_25.ogg', '', 0, 0, '', 1, 0, 1, '[594,631]', NULL, 0, 0, '[]', 100),
(15604, 'MaataConversationWithKahuOne', '[]', 'Kahuturoa, how goes it?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15605, 'MaataConversationWithKahuTwo', '[]', 'And I thought I was hard of hearing!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Maata/Maata_Wild/Maata_Wild_28.ogg', '', 0, 0, '', 1, 0, 1, '[594]', NULL, 0, 0, '[]', 100),
(15606, 'IkiahoLikesPlayerIsChampion', '[]', 'The makanga will win again. I am sure of it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15607, 'IkiahoNeutralPlayerIsChampion', '[]', 'Makanga or not, this one''s up in the air.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15608, 'IkiahoDislikesPlayerIsChampion', '[]', 'Will someone please take down this makanga already?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15609, 'IkiahoLikesPlayerLostLast', '[]', 'Win this time, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15610, 'IkiahoNeutralPlayerLostLast', '[]', 'The outsider might be able to take this one.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15611, 'IkiahoDislikesPlayerLostLast', '[]', 'There''s no way the outsider wins this battle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15612, 'IkiahoLikesPlayerNoRecord', '[]', 'I will be watching your fighting style carefully, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15613, 'IkiahoNeutralPlayerNoRecord', '[]', 'If nothing else, this will be new.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15614, 'IkiahoDislikesPlayerNoRecord', '[]', 'I''m not convinced letting an outsider participate is a good idea.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15615, 'IkiahoCommentsOnAkoya', '[]', 'Surely the followers of the God of War can handle a simple battle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15616, 'IkiahoCommentsOnKahuturoa', '[]', 'The Night is all-encompassing. It cannot be defeated.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15617, 'IkiahoCommentsOnKaom', '[]', 'Look at all those warriors following Kaom! Have they not heard what happens to his men?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15618, 'IkiahoCommentsOnKiloava', '[]', 'Bluster like thunder, strike like lightning, Kiloava.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15619, 'IkiahoCommentsOnMaata', '[]', 'Maata''s probably got this one. Uses his head.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15620, 'IkiahoCommentsOnRakiata', '[]', 'The sea is most beautiful when it reflects the Moon!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15621, 'IkiahoCommentsOnTawhanuku', '[]', 'Tawhanuku! Bring death to the field!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15622, 'IkiahoCommentsOnUtula', '[]', 'It''s amazing the Kitavans can move at all with such gorged bellies.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15623, 'IkiahoCommentsOnAhuana', '[]', 'How does such a heavy ego stay hanging in the sky? Ramako should fall, so that the Moon may rise instead.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[611]', NULL, 0, 0, '[]', 100),
(15624, 'IkiahoFightBeginsPlayerWonLast1', '[]', 'You reached your apex in our last fight. Now, you will fall.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15625, 'IkiahoFightBeginsPlayerWonLast2', '[]', 'You reached your apex in our last fight. Now, you will fall.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15626, 'IkiahoFightBeginsPlayerLostLast1', '[]', 'Let us see what you have learned since our last conflict.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15627, 'IkiahoFightBeginsPlayerLostLast2', '[]', 'Let us see what you have learned since our last conflict.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15628, 'IkiahoFightBeginsPlayerMoreSoldiers1', '[]', 'You may have more warriors than us, but the Moon has always shined alone.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15629, 'IkiahoFightBeginsPlayerMoreSoldiers2', '[]', 'You may have more warriors than us, but the Moon has always shined alone.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15630, 'IkiahoFightBeginsPlayerLessSoldiers1', '[]', 'You think you can defeat us while outnumbered? Intriguing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15631, 'IkiahoFightBeginsPlayerLessSoldiers2', '[]', 'You think you can defeat us while outnumbered? Intriguing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15632, 'IkiahoFightBeginsPlayerMoreItems1', '[]', 'A well-equipped enemy is more satisfying to defeat.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15633, 'IkiahoFightBeginsPlayerMoreItems2', '[]', 'A well-equipped enemy is more satisfying to defeat.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15634, 'IkiahoFightBeginsPlayerLessItems1', '[]', 'Curious choice of equipment...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15635, 'IkiahoFightBeginsPlayerLessItems2', '[]', 'Curious choice of equipment...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15636, 'IkiahoFightBeginsPlayerMoreFieldItems1', '[]', 'I appreciate your battlefield strategy. That will make this interesting.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15637, 'IkiahoFightBeginsPlayerMoreFieldItems2', '[]', 'I appreciate your battlefield strategy. That will make this interesting.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
(15638, 'IkiahoFightBeginsPlayerLessFieldItems1', '[]', 'Battles are often won or lost based on the field itself. We seem to have put more thought into our strategy...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Field/Ikiaho_Field_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[604]', NULL, 0, 0, '[]', 100),
