(15690, 'IkiahoCommentRecruitRecruit3', '[]', 'Okay.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15691, 'IkiahoCommentRecruitRecruit4', '[]', 'Okay.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15692, 'IkiahoLikesHerTurtle1', '[]', 'Tortoises are nature''s armored knights.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15693, 'IkiahoPlayerWonVsAhuana', '[]', 'Ahuana is very positive, even in defeat. I don''t despise positivity, I just don''t often feel it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_06.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15694, 'IkiahoPlayerLostVsAhuana', '[]', 'It doesn''t matter that you lost to Ahuana. You''ll have plenty of chances to try again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_07.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15695, 'IkiahoPlayerWonVsKaom', '[]', 'Kaom will not learn humility from his defeat.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_08.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15696, 'IkiahoPlayerLostVsKaom', '[]', 'Defeating you likely just grew Kaom''s ego three sizes.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_09.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15697, 'IkiahoPlayerWonVsUtula', '[]', 'Utula needs a lesson enforced by strength. I won''t let him tear this place down.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_10.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15698, 'IkiahoPlayerLostVsUtula', '[]', 'Don''t let Utula defeat you again. He might think he can take us all on.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_11.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15699, 'IkiahoPlayerWonVsKahuturoa', '[]', 'Your victory against Kahuturoa would not have happened a thousand years ago. He''s fighting with less interest these days.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_12.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15700, 'IkiahoPlayerLostVsKahuturoa', '[]', 'Kahuturoa defeated you, as expected. You''ll have to strategise to win against him.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_13.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15701, 'IkiahoPlayerWonVsKiloava', '[]', 'The first Herald of War does not enjoy losing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_14.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15702, 'IkiahoPlayerLostVsKiloava', '[]', 'Kiloava greatly enjoys battle. I''m sure he enjoyed defeating you, too.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_15.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15703, 'IkiahoPlayerWonVsRakiata', '[]', 'I''m rather amazed you managed to defeat Rakiata. I''ll be watching you, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_16.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15704, 'IkiahoPlayerLostVsRakiata', '[]', 'Rakiata has a strength most aren''t expecting. I''m sure you felt that, though, when you got hit in the face.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_17.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15705, 'IkiahoPlayerWonVsTawhanuku', '[]', 'Hmm. Tawhanuku lost a battle. Curious.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_18.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15706, 'IkiahoPlayerLostVsTawhanuku', '[]', 'I expected Tawhanuku to defeat you. She chooses her battles carefully.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_19.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15707, 'IkiahoPlayerWonAgainstThem', '[]', 'The Moon can''t stay high in the sky forever. I didn''t expect to win every time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_20.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15708, 'IkiahoPlayerLostAgainstThem', '[]', 'The Moon soars high above the mortal world. So it is with battle as well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_21.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15709, 'IkiahoPlayerWonNeutral', '[]', 'That was certainly a victory, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_22.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15710, 'IkiahoPlayerLostNeutral', '[]', 'You lost, outsider. You must do better.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_23.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15711, 'IkiahoCommentOnPurchaseItemKahuturoa', '[]', 'Rongokurai, ally to the night, ally to mortals!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15712, 'IkiahoCommentOnPurchaseItemRakiata', '[]', 'They''ll never let you down.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_24.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15713, 'IkiahoCommentOnPurchaseEliteKahuturoa', '[]', 'A strong choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_25.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15714, 'IkiahoCommentOnPurchaseEliteRakiata', '[]', 'No one can fight the sea and win!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_26.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15715, 'IkiahoConversationWithKahuturoaOne', '[]', 'The answer''s still no, Kahu!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15716, 'IkiahoConversationWithRakiataOne', '[]', 'I wish I could see the Moon from here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_28_01.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15717, 'IkiahoConversationWithRakiataTwo', '[]', 'That would be nice...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_28_02.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15718, 'IkiahoRandomShout1', '[]', 'Does anyone have any meat left over from today''s meal? I''m still hungry.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho_Wild/Ikiaho_Wild_29.ogg', '', 0, 0, '', 1, 0, 1, '[591]', NULL, 0, 0, '[]', 100),
(15719, 'IkiahoGossipArohongui', '[]', 'The Daughter of the Moon has my tribe''s eternal loyalty. Alone among the gods, she has no agenda of her own. The rest all seek something endlessly—whatever it was that gave each of them a divine spark—but Arohongui was born divine, and chose to aid the Karui people as much as she could. She did not ask us for loyalty, and that is why she has it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_24.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15720, 'IkiahoGossipTheDeceiver', '[]', 'Ramako''s claim that someone impersonated him and visited with Lani Hua in his guise... may be true. We follow Arohongui with utmost loyalty, but my tribe certainly noticed that she never expressed any divine abilities having to do with light or warmth. When tending wounded warriors, she would often give them visions of beautiful landscapes and shining waters to help calm them. When tending the dying, she gave them visions of their family, until the spirits of their Ancestors truly greeted them here in the Halls of the Dead. These are acts of mercy and kindness, but they are not powers of the Sun or the Moon.' || char(13) || '
' || char(13) || '
I have long suspected that there is something within each of us, some pattern or essence of who we are, that each parent passes down to a child. If my suspicion is correct, then it is not possible that Ramako is Arohongui''s father. There is only one sensible conclusion, and that, we keep to ourselves, so as not to disrupt the balance of the skies.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_25.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15721, 'IkiahoGossipLaniHua', '[]', 'Many believe that the Mother of the Moon has been off fighting a war against the Mother of the Sun for thousands of years. While Lani Hua is indeed absent, it is not to fight against her sister. The wounded souls from that war are sent to the silver palace, where Arohongui tends to them until they may rejoin the fight. Those warrior souls cry out in fear and torment as they lay in hospice. They speak not of war with Sione, but of a war with the stars themselves. They have been sworn to silence by both Sione and Lani Hua, but the feverish ones cannot help but rant. Apparently, the two sisters did go out into the night sky to wage war upon one another, but when they got there, they encountered something horrible, something that drives even the strongest warrior to madness and panic. We have not been abandoned by our two strongest gods. They are out there protecting us every single minute of every single day, and they cannot rest for even a moment.' || char(13) || '
' || char(13) || '
That''s what the tales say, in any case. I don''t know how much of that I actually believe.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_26.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15722, 'IkiahoGossipRamako', '[]', 'The Ramako Tribe, like us, often uses ice and cold in their warmaking. That is because Ramako has long loved Lani Hua, Arohongui''s mother, in secret. He fights not for himself, but for her. His people do the same. I don''t understand it at all, but it is what it is.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_27.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15723, 'IkiahoGossipTraditions', '[]', 'They never stop asking. How arrogant! Even if we remain here for ten thousand years, I will never go through the traditions with them. I will participate in the battles because I enjoy fighting, but this is <i>{their} culture. They seem unaware that I do not intend to fit their expectations. My heart warms for no one. I do not know what love is, only that it motivates others to act like fools and monsters, depending on their inclinations. Perhaps I do have a frozen heart, but that doesn''t mean I feel nothing. Their words still hurt me, perhaps even more than their weapons.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_28.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15724, 'IkiahoGossipRakiata', '[]', 'There are few here who understand. Karui culture can often be excessively focused on having certain traits, such as strength or bravado. Certain duties are expected of each of us, whether or not we want to fulfill them. I died long before Rakiata, so we never met in life, but here in the Halls of the Dead, they''re my closest friend. In death, I actually feel understood. For that, I can never begrudge this place.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_29.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15725, 'IkiahoGossipTheEndOfTime', '[]', 'There are many fables about the end of the world, but those are just metaphors. My tribe knows how it will really happen. The Moon, in the sky above, follows a roughly oval path around us. Did you know that our world is actually shaped like the Moon? Most believe that Wraeclast is flat, because that is the obvious interpretation of what we see. However, in studying the Moon, my tribe has discovered the truth. Also, we realised that the Moon''s path is not exact. Over many, <i>{many} thousands of years, it is changing slightly... toward us. We have come to understand that the world will end when the Moon comes too close and falls upon us. This is not myth. This is knowledge. What else could possibly happen when two such titanic spheres of stone crash into each other?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_30.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15726, 'IkiahoGossipKnowledge', '[]', 'I have always been fascinated by the pursuit of knowledge. There is a pattern underneath everything we see. This pattern preceded even the gods. If something in the world around you works a certain way, it will always work that way. If it does not, something else is happening, and you must investigate. In life, I followed these questions to the heart of the pattern, and it took me to a vast lake... but I do not remember what I found there...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Ikiaho/Ikiaho/Ikiaho_31.ogg', '', 0, 0, '', 1, 0, 1, '[591,628]', NULL, 0, 0, '[]', 100),
(15727, 'UtulaChallengesPlayer', '[]', 'Come, fool. I will cut out your heart!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15728, 'UtulaLikesPlayerIsChampion', '[]', 'Yes, ''Champion!'' Embarrass these fools!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15729, 'UtulaNeutralPlayerIsChampion', '[]', 'Tear it all down, ''Champion!''', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15730, 'UtulaDislikesPlayerIsChampion', '[]', 'Humble this arrogant ''Champion!''', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15731, 'UtulaLikesPlayerLostLast', '[]', 'You can''t change anything unless you win!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15732, 'UtulaNeutralPlayerLostLast', '[]', 'Put up a fight this time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15733, 'UtulaDislikesPlayerLostLast', '[]', 'This will be embarrassing to watch!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15734, 'UtulaLikesPlayerNoRecord', '[]', 'Let''s see if you have what it takes to defy this place!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15735, 'UtulaNeutralPlayerNoRecord', '[]', 'Is this what we''re expected to do for all of eternity?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15736, 'UtulaDislikesPlayerNoRecord', '[]', 'You are too weak to change anything!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15737, 'UtulaCommentsOnAkoya', '[]', 'May this ''pillar of tradition'' fall!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15738, 'UtulaCommentsOnIkiaho', '[]', 'Arrogant and aloof leaves one alone and ripe for defeat!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15739, 'UtulaCommentsOnKahuturoa', '[]', 'I''ve never even heard of Kahuturoa! What are we watching?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15740, 'UtulaCommentsOnKaom', '[]', 'Burn it all down, Kaom the conqueror!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15741, 'UtulaCommentsOnKiloava', '[]', 'Your bloodline was ended by Kaom, Kiloava! Why must we still put up with you?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15742, 'UtulaCommentsOnMaata', '[]', 'Peacemaker and fool are the same thing!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15743, 'UtulaCommentsOnRakiata', '[]', 'Resign and make room for someone stronger, Rakiata!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15744, 'UtulaCommentsOnTawhanuku', '[]', 'What cryptic nonsense do you have for us today, Tawhanuku?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15745, 'UtulaCommentsOnAhuana', '[]', 'We are not here to ''have fun,'' half-blood! Act like a real Karui!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_19.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15746, 'UtulaFightBeginsPlayerWonLast1', '[]', 'You were lucky last time! Your luck is about to run out!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_01.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15747, 'UtulaFightBeginsPlayerLostLast1', '[]', 'You''re about to lose again. No mercy!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_02.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15748, 'UtulaFightBeginsPlayerMoreSoldiers1', '[]', 'Surrounding yourself with other warriors won''t save you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_03.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15749, 'UtulaFightBeginsPlayerLessSoldiers1', '[]', 'Ha! We outnumber you! This will be easy!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_04.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15750, 'UtulaFightBeginsPlayerMoreItems1', '[]', 'So much equipment. Your chains are all the heavier!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_05.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15751, 'UtulaFightBeginsPlayerLessItems1', '[]', 'You seem rather unprepared for this battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_06.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15752, 'UtulaFightBeginsPlayerMoreFieldItems1', '[]', 'Look at this battlefield. So strategic. It won''t change the outcome!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_07.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15753, 'UtulaFightBeginsPlayerLessFieldItems1', '[]', 'This will be a killing ground!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_08.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15754, 'UtulaWarcry1', '[]', 'For Kitava!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_09_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15755, 'UtulaWarcry2', '[]', 'For Kitava!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_09_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15756, 'UtulaWarcry3', '[]', 'Kill them all!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_09_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15757, 'UtulaWarcry4', '[]', 'Kill them all!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_09_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15758, 'UtulaWarcry5', '[]', 'Warriors, ravage this place!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_09_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15759, 'UtulaWarcry6', '[]', 'Warriors, ravage this place!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_09_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15760, 'UtulaTeamTotemDestroyed1', '[]', 'How dare you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_10_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15761, 'UtulaTeamTotemDestroyed2', '[]', 'How dare you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_10_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15762, 'UtulaTeamTotemDestroyed3', '[]', 'No matter!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_10_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15763, 'UtulaTeamTotemDestroyed4', '[]', 'No matter!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_10_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15764, 'UtulaTeamTotemDestroyed5', '[]', 'Press on!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_10_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15765, 'UtulaTeamTotemDestroyed6', '[]', 'Press on!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_10_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15766, 'UtulaTotemDestroyed1', '[]', 'How?!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_11_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15767, 'UtulaTotemDestroyed2', '[]', 'How?!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_11_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15768, 'UtulaTotemDestroyed3', '[]', 'Warriors of Kitava, press the attack!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_11_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15769, 'UtulaTotemDestroyed4', '[]', 'Warriors of Kitava, press the attack!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_11_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15770, 'UtulaTotemDestroyed5', '[]', 'This means nothing!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_11_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15771, 'UtulaTotemDestroyed6', '[]', 'This means nothing!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_11_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15772, 'UtulaYourTeamTotemDestroyed1', '[]', 'Your empire is burning, fool!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_12_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15773, 'UtulaYourTeamTotemDestroyed2', '[]', 'Your empire is burning, fool!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_12_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15774, 'UtulaYourTeamTotemDestroyed3', '[]', 'Your time is almost up!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_12_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15775, 'UtulaYourTeamTotemDestroyed4', '[]', 'Your time is almost up!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_12_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15776, 'UtulaYourTeamTotemDestroyed5', '[]', 'We are unstoppable!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_12_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15777, 'UtulaYourTeamTotemDestroyed6', '[]', 'We are unstoppable!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_12_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15778, 'UtulaYourTotemDestroyed1', '[]', 'The king has fallen!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_13_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15779, 'UtulaYourTotemDestroyed2', '[]', 'The king has fallen!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_13_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15780, 'UtulaYourTotemDestroyed3', '[]', 'Let us see if your warriors can fight without you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_13_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15781, 'UtulaYourTotemDestroyed4', '[]', 'Let us see if your warriors can fight without you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_13_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15782, 'UtulaYourTotemDestroyed5', '[]', 'I''ve beaten you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_13_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15783, 'UtulaYourTotemDestroyed6', '[]', 'I''ve beaten you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_13_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[601]', NULL, 0, 0, '[]', 100),
(15784, 'UtulaCommentDefeatedYou1', '[]', 'I must confess, that was rather exhilarating!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_14.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15785, 'UtulaCommentWhenDefeated1', '[]', 'Gah! I''ll get you next time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_15_01.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15786, 'UtulaCommentWhenDefeated2', '[]', 'Gah! I''ll get you next time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Field/Utula_Field_15_02.ogg', '', 0, 0, '', 1, 0, 1, '[601]', NULL, 0, 0, '[]', 100),
(15787, 'UtulaCommentsFromStandsOnMatch1', '[]', 'Yes! Win it all! Show them the error of their ways!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_23_01.ogg', '', 0, 0, '', 1, 0, 1, '[615]', NULL, 0, 0, '[]', 100),
(15788, 'UtulaCommentPurchaseItem1', '[]', 'Use that to punish everyone else here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_01_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15789, 'UtulaCommentPurchaseItem2', '[]', 'Use that to punish everyone else here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_01_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15790, 'UtulaCommentPurchaseItem3', '[]', 'Consider it a torch on the pyre.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_01_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15791, 'UtulaCommentPurchaseItem4', '[]', 'Consider it a torch on the pyre.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_01_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15792, 'UtulaCommentPurchaseFieldItem1', '[]', 'Meh.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15793, 'UtulaCommentPurchaseFieldItem2', '[]', 'Meh.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_02_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15794, 'UtulaCommentPurchaseFieldItem3', '[]', 'Do what you want with that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15795, 'UtulaCommentPurchaseFieldItem4', '[]', 'Do what you want with that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15796, 'UtulaCommentInspectRecruits1', '[]', 'Choose, if you must.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15797, 'UtulaCommentInspectRecruits2', '[]', 'Choose, if you must.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15798, 'UtulaCommentInspectRecruits3', '[]', 'My warriors will fight for you, if they must.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15799, 'UtulaCommentRecruitRecruit1', '[]', 'Fine.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15800, 'UtulaCommentRecruitRecruit2', '[]', 'Fine.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_04_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15801, 'UtulaCommentRecruitRecruit3', '[]', 'Go ahead then.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15802, 'UtulaCommentRecruitRecruit4', '[]', 'Go ahead then.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15803, 'UtulaPlayerWonVsAhuana', '[]', 'Maybe defeating the half-blood will dim her relentless positivity, but somehow I doubt we''re that lucky.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_05.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15804, 'UtulaPlayerLostVsAhuana', '[]', 'I''m sure the smiling half-blood will be kind about defeating you. How ridiculous.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_06.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15805, 'UtulaPlayerWonVsAkoya', '[]', 'Yes! Akoya must be feeling the sting of defeat right about now. Delicious.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_07.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15806, 'UtulaPlayerLostVsAkoya', '[]', 'Don''t let Akoya win again. She''s already the worst one here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_08.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15807, 'UtulaPlayerWonVsKahuturoa', '[]', 'Kahuturoa is a good example of why we must change this place. He hardly cares that he lost to you. I doubt the dumbarse even knows what''s going on.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_09.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15808, 'UtulaPlayerLostVsKahuturoa', '[]', 'I was not aware that ancient Karui like Kahuturoa could fight like that. Why have we not advanced more in all this time?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_10.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15809, 'UtulaPlayerWonVsKiloava', '[]', 'The famed Kiloava, the first Herald of War, defeated by one such as yourself. These people are so disappointing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_11.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15810, 'UtulaPlayerLostVsKiloava', '[]', 'Kiloava is a name I heard in stories as a child. Our <i>{hatungo} spoke of him as the first Herald of War. It''s no surprise he beat you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_12.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15811, 'UtulaPlayerWonVsMaata', '[]', 'What fools they are, bringing a peacemaker here. Of course you kicked his arse.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_13.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15812, 'UtulaPlayerLostVsMaata', '[]', 'You lost to an old man, a <i>{diplomat}. I knew his kind in the slave pens. He''d have turned on his own to become an overseer. I''d cut his throat if he weren''t already dead.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_14.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15813, 'UtulaPlayerWonVsRakiata', '[]', 'Rakiata fights strangely. Your victory over her made waves among the others. Keep doing that. Keep winning.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_15.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15814, 'UtulaPlayerLostVsRakiata', '[]', 'Hmm... fight Rakiata again, even though you lost. I''m suspicious of something... I must see her fight more.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_16.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15815, 'UtulaPlayerWonVsTawhanuku', '[]', 'It was good that you got one over on Tawhanuku. I have yet to determine whether the Hinekora tribe are our jailors, or fellow slaves. We shall see.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_17.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15816, 'UtulaPlayerLostVsTawhanuku', '[]', 'If you cannot defeat the Hinekora Tribe in battle, then we will never get out of here. Try harder.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_18.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15817, 'UtulaPlayerWonVsIkiaho', '[]', 'Ikiaho knows something. Something hides behind her grimness. Keep defeating her. We must demoralise her. Then, maybe she will talk to me...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_19.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15818, 'UtulaPlayerLostVsIkiaho', '[]', 'Strange, how well Arohongui''s brood fights. I''ll keep an eye on them.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_20.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15819, 'UtulaPlayerWonVsKaom', '[]', 'You defeated the legendary Kaom in battle. I''ve never seen anything quite like it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_21.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15820, 'UtulaPlayerLostVsKaom', '[]', 'Kaom united an empire of squabbling Karui tribes, and unleashed a sequence of events that eventually destroyed the Eternal Empire. Of course you lost to him. Get over it.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_22.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15821, 'UtulaPlayerWonAgainstThem', '[]', 'You take this nonsense far too seriously.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_23.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15822, 'UtulaPlayerLostAgainstThem', '[]', 'You will not defeat me so easily. I suppose we have a very long time for you to try again, since I can never leave this place.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_24.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15823, 'UtulaPlayerWonNeutral', '[]', 'Perhaps you are the ally I am looking for in this prison...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_25.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15824, 'UtulaPlayerLostNeutral', '[]', 'If we are going to stage a prison break here, I am going to need you to be far stronger than that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_26.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15825, 'UtulaCommentOnPurchaseItemKaom', '[]', 'Yes, Kaom, give your aid...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_24_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15826, 'UtulaCommentOnPurchaseEliteKaom', '[]', 'Not bad.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15827, 'UtulaRandomShout1', '[]', 'Kitava will one day return to consume all the souls in this domain!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15828, 'UtulaRandomShout2', '[]', 'Forget the rules! Let us revel in blood and madness!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_27_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15829, 'UtulaRandomShout3', '[]', 'How do I get to the Chambers of the Dishonoured! I should be there, not here!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_28_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15830, 'UtulaRandomShout4', '[]', 'How do I get to the Chambers of the Dishonoured! I should be there, not here!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_28_02.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15831, 'UtulaRandomShout5', '[]', 'Why must we remain in this place?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_29_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15832, 'UtulaRandomShout6', '[]', 'I miss the sun!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_30_01.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15833, 'UtulaGossipOnYou', '[]', 'So, it''s you. Come to kill me again? Tough luck, since I''m already dead. Did you get yourself killed too? No, I can sense some tether to life about you. Whatever. I don''t care.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_27.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15834, 'UtulaGossipOnKitavasDefeat', '[]', 'The Father of Hunger may be dead, but his essence lives on in his people. I challenge my fellow Karui. How dare we accept this fate? How dare we accept these Halls of the Dead? We should be free, to roam the world, or enter oblivion if we wish! Kitava once promised to devour all the souls in this domain, and it seems I must fulfill that promise!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_28.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15835, 'UtulaGossipOnTheHallsOfTheDead', '[]', 'Imagine my surprise when you killed me and I found myself in this dank and dour dungeon. I didn''t even know about this place. I grew up in the slave pens, and my knowledge of my own culture was fragmented at best. When the blood spilled out of me and my heart stilled, I thought I was finally free. No. I still exist, because Hinekora scooped up my soul, and they even ''honoured'' me with a position here. You know what I''ll be doing? Fighting. Bleeding. Dying. <i>{Forever.} I died! I''m dead! But I''m still imprisoned! This is a load of horse dung the size of Wraeclast! This place will burn! ', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_29.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15836, 'UtulaGossipOnHinekora', '[]', 'Hinekora is our jailer. I imagine she had good intentions when she made this place. Preserve the souls of the Karui so that they may guide their descendants, sure. Sounds lovely. Then, she went to sleep for thousands of years. All the souls of my people have been collecting here unattended ever since. That seems like a massive blunder. I don''t care that she''s awake now. She''s hardly present. There''s no way she''s the same as she was, not after a sleep like that. We''re stuck in a prison without a warden, and there is <i>{no way out.}', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_30.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15837, 'UtulaGossipOnRakiata', '[]', 'You know what''s strange? I always thought Rakiata was a man. I suppose I don''t know much about my own people, beyond the remnants of knowledge the slaves passed on in Oriath''s pens. Coming here, I''m furious at how much of my own history was denied me. I''m basically locked in a permanent family reunion with relatives I''ve never met.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_31.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15838, 'UtulaGossipOnTheEndOfTime', '[]', 'They tell me I am here until the end of Time itself. When I ask how long that is, they all give me a different answer. I don''t think any of them actually know. They console themselves with tales of endings and rebirths, but I think they''re terrified of the most likely possibility. What if Time never ends at all? What if we are here <i>{forever?} That Rongokurai chieftain has been here thousands of years already, and he''s gone a bit off. What happens when we''ve all been here for ten thousand years? A <i>{million} years? We''ll be stark raving mad, and we''ll <i>{never get out}, unless we unite and assault the walls of this prison directly!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_32.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15839, 'UtulaGossipOnTheKaruiWay', '[]', 'The Way means nothing to me. Where were my fellow Karui tribes when we prisoners were rotting in slave pens since the time of Lioneye? I guess nobody was very interested in rescuing us. What does all that strength matter if it only benefits the strong? I was born into slavery. I never had a choice. I refuse to continue being a prisoner in my own afterlife!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula/Utula_33.ogg', '', 0, 0, '', 1, 0, 1, '[595,632]', NULL, 0, 0, '[]', 100),
(15840, 'UtulaConversationsWithKaomOne', '[]', 'By the hand of the same Exile that recently showed you a thing or two.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Utula/Utula_Wild/Utula_Wild_31.ogg', '', 0, 0, '', 1, 0, 1, '[595]', NULL, 0, 0, '[]', 100),
(15841, 'KaomLikesPlayerIsChampion', '[]', 'Entertain us once more, makanga!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15842, 'KaomNeutralPlayerIsChampion', '[]', 'This will be a glorious battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15843, 'KaomDislikesPlayerIsChampion', '[]', 'The Karui will take back our honour!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15844, 'KaomLikesPlayerLostLast', '[]', 'Let your warrior spirit take over, outsider!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15845, 'KaomNeutralPlayerLostLast', '[]', 'Make it quick!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15846, 'KaomDislikesPlayerLostLast', '[]', 'This is a waste of time.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15847, 'KaomLikesPlayerNoRecord', '[]', 'Perhaps we shall witness a spectacle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15848, 'KaomNeutralPlayerNoRecord', '[]', 'Let''s see something new.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15849, 'KaomDislikesPlayerNoRecord', '[]', 'This should be quick. Get it over with!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15850, 'KaomCommentsOnRakiata', '[]', 'Rakiata, try to keep your head this time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15851, 'KaomCommentsOnIkiaho', '[]', 'Ikiaho! Show them what that frozen heart of yours can do!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15852, 'KaomCommentsOnKiloava', '[]', 'Kiloava is a former Herald of War for a reason!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15853, 'KaomCommentsOnTawhanuku', '[]', 'None can stand against the children of the Mother of Death!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15854, 'KaomCommentsOnMaata', '[]', 'Let''s see how the peacemaker does battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15855, 'KaomCommentsOnUtula', '[]', 'Show them the savageness of a true warrior, Utula!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15856, 'KaomCommentsOnAhuana', '[]', 'Fight with honour, daughter of Hyrri!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15857, 'KaomCommentsOnAkoya', '[]', 'Akoya! Honour the old ways!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15858, 'KaomCommentsOnKahuturoa', '[]', 'Let''s see what those cowardly night fighters can do!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[609]', NULL, 0, 0, '[]', 100),
(15859, 'KaomFightBeginsPlayerWonLast1', '[]', 'No one, living or dead, defeats Kaom twice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15860, 'KaomFightBeginsPlayerLostLast1', '[]', 'Last we fought, you lost. Nothing has changed.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_02.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15861, 'KaomFightBeginsPlayerMoreSoldiers1', '[]', 'My warriors have always fought outnumbered. This will be no different.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_03.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15862, 'KaomFightBeginsPlayerLessSoldiers1', '[]', 'You seek to take us on with so few warriors? You are a fool!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_04.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15863, 'KaomFightBeginsPlayerMoreItems1', '[]', 'You are well-equipped. It won''t help you.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_05.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15864, 'KaomFightBeginsPlayerLessItems1', '[]', 'You should have better prepared for battle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_06.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15865, 'KaomFightBeginsPlayerMoreFieldItems1', '[]', 'Like you, the Eternals had the terrain advantage. They still died.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_07.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15866, 'KaomFightBeginsPlayerLessFieldItems1', '[]', 'We control this battlefield. The outcome is certain.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_08.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15867, 'KaomWarcry1', '[]', 'Ngamahu, lend us your fire!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_09_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15868, 'KaomWarcry2', '[]', 'Ngamahu, lend us your fire!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_09_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15869, 'KaomWarcry3', '[]', 'To battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_09_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15870, 'KaomWarcry4', '[]', 'To battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_09_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15871, 'KaomWarcry5', '[]', 'Warriors, attack!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_09_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15872, 'KaomWarcry6', '[]', 'Warriors, attack!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_09_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15873, 'KaomTeamTotemDestroyed1', '[]', 'Victory requires sacrifice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_10_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15874, 'KaomTeamTotemDestroyed2', '[]', 'Victory requires sacrifice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_10_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15875, 'KaomTeamTotemDestroyed3', '[]', 'We will persevere!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_10_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15876, 'KaomTeamTotemDestroyed4', '[]', 'We will persevere!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_10_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15877, 'KaomTeamTotemDestroyed5', '[]', 'You''ve accomplished nothing!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_10_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15878, 'KaomTeamTotemDestroyed6', '[]', 'You''ve accomplished nothing!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_10_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15879, 'KaomTotemDestroyed1', '[]', 'My warriors cannot possibly win now...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_11_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15880, 'KaomTotemDestroyed2', '[]', 'My warriors cannot possibly win now...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_11_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15881, 'KaomTotemDestroyed3', '[]', 'Ridiculous!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_11_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15882, 'KaomTotemDestroyed4', '[]', 'Ridiculous!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_11_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15883, 'KaomTotemDestroyed5', '[]', 'Impossible!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_11_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15884, 'KaomTotemDestroyed6', '[]', 'Impossible!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_11_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15885, 'KaomYourTeamTotemDestroyed1', '[]', 'One less to stand against us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_12_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15886, 'KaomYourTeamTotemDestroyed2', '[]', 'One less to stand against us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_12_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15887, 'KaomYourTeamTotemDestroyed3', '[]', 'Our war has only just begun!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_12_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15888, 'KaomYourTeamTotemDestroyed4', '[]', 'Our war has only just begun!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_12_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15889, 'KaomYourTeamTotemDestroyed5', '[]', 'Keep up the assault!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_12_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15890, 'KaomYourTeamTotemDestroyed6', '[]', 'Keep up the assault!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_12_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15891, 'KaomYourTotemDestroyed1', '[]', 'Victory is inevitable now!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_13_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15892, 'KaomYourTotemDestroyed2', '[]', 'Victory is inevitable now!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_13_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15893, 'KaomYourTotemDestroyed3', '[]', 'You never had a chance.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_13_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15894, 'KaomYourTotemDestroyed4', '[]', 'You never had a chance.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_13_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15895, 'KaomYourTotemDestroyed5', '[]', 'The Karui always win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_13_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15896, 'KaomYourTotemDestroyed6', '[]', 'The Karui always win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_13_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[599]', NULL, 0, 0, '[]', 100),
(15897, 'KaomCommentDefeatedYou1', '[]', 'How did you think this would go when you challenged me? You fought well. Just... not well enough.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_14_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15898, 'KaomCommentDefeatedYou2', '[]', 'How did you think this would go when you challenged me?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Field/Kaom_322_Field_14_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15899, 'KaomCommentsWhenDefeated1', '[]', 'Disgraceful!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_21_01.ogg', '', 0, 0, '', 1, 0, 1, '[599]', NULL, 0, 0, '[]', 100),
(15900, 'KaomCommentPurchaseItem1', '[]', 'You can always depend on that which was forged by the Mother of Fire.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_01_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15901, 'KaomCommentPurchaseItem2', '[]', 'You can always depend on that which was forged by the Mother of Fire.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_01_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15902, 'KaomCommentPurchaseItem3', '[]', 'It will serve you well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_01_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15903, 'KaomCommentPurchaseItem4', '[]', 'It will serve you well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_01_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15904, 'KaomCommentPurchaseFieldItem1', '[]', 'Strategy is everything.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15905, 'KaomCommentPurchaseFieldItem2', '[]', 'Strategy is everything.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_02_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15906, 'KaomCommentPurchaseFieldItem3', '[]', 'Control the battlefield, control the outcome.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15907, 'KaomCommentPurchaseFieldItem4', '[]', 'Control the battlefield, control the outcome.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15908, 'KaomCommentInspectRecruits1', '[]', 'There are no finer warriors.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15909, 'KaomCommentInspectRecruits2', '[]', 'There are no finer warriors.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15910, 'KaomCommentInspectRecruits3', '[]', 'Who do you wish to recruit?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15911, 'KaomCommentInspectRecruits4', '[]', 'Who do you wish to recruit?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_03_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15912, 'KaomCommentInspectRecruits5', '[]', 'Make your choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_03_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15913, 'KaomCommentInspectRecruits6', '[]', 'Make your choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_03_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15914, 'KaomCommentRecruitRecruit1', '[]', 'The correct choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15915, 'KaomCommentRecruitRecruit2', '[]', 'The correct choice.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_04_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15916, 'KaomCommentRecruitRecruit3', '[]', 'They will serve you well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15917, 'KaomCommentRecruitRecruit4', '[]', 'They will serve you well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15918, 'KaomCommentRecruitRecruit5', '[]', 'Victory is certain with one of my warriors at your side.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_04_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15919, 'KaomCommentRecruitRecruit6', '[]', 'Victory is certain with one of my warriors at your side.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_04_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15920, 'KaomPlayerWonVsKahuturoa', '[]', 'It is always a pleasure seeing my enemies laid low.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_05.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15921, 'KaomPlayerLostVsKahuturoa', '[]', 'You lost to the cowardly night fighters. How disappointing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_06.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15922, 'KaomPlayerWonVsKiloava', '[]', 'Seeing Kiloava humiliated was... satisfying. You fought well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_07.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15923, 'KaomPlayerLostVsKiloava', '[]', 'As much as I dislike Kiloava, your loss to him was not unexpected.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_08.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15924, 'KaomPlayerWonVsMaata', '[]', 'No surprise that you defeated the peacemaker.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_09.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15925, 'KaomPlayerLostVsMaata', '[]', 'How did you manage to lose to the peacemaker?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_10.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15926, 'KaomPlayerWonVsRakiata', '[]', 'You should have cut off Rakiata''s head. I did.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_11.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15927, 'KaomPlayerLostVsRakiata', '[]', 'Train hard, and take on Rakiata again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_12.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15928, 'KaomPlayerWonVsAhuana', '[]', 'Ahuana goes too easy on newcomers. Don''t think you won for any other reason.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_13.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15929, 'KaomPlayerLostVsAhuana', '[]', 'Only the greatest of warriors can take on Ahuana. Don''t be ashamed of your loss.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_14.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15930, 'KaomPlayerWonVsAkoya', '[]', 'Akoya upholds our Way, even in defeat. It was an honourable battle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_15.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15931, 'KaomPlayerLostVsAkoya', '[]', 'I enjoyed watching Akoya take you down. She''s a very talented warrior.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_16.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15932, 'KaomPlayerWonVsIkiaho', '[]', 'That was rather impressive. I didn''t expect you to defeat Ikiaho.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_17.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15933, 'KaomPlayerLostVsIkiaho', '[]', 'No one thaws Ikiaho. Do not be disheartened.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_18.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15934, 'KaomPlayerWonVsTawhanuku', '[]', 'That was a gripping battle against Tawhanuku. I''m certain she saw it coming.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_19.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15935, 'KaomPlayerLostVsTawhanuku', '[]', 'Tawhunuku serves Hinekora, and Hinekora sees all. She took that battle knowing she would win.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_20.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15936, 'KaomPlayerWonVsUtula', '[]', 'Alright, I''m impressed. Defeating Utula was no small success.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_21.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15937, 'KaomPlayerLostVsUtula', '[]', 'Utula is a true Karui warrior. He will win time and time again!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_22.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15938, 'KaomPlayerWonAgainstThem', '[]', 'You seemed like you needed a win, so I let you have one. It''s as simple as that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_23.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15939, 'KaomPlayerLostAgainstThem', '[]', 'Do not be disheartened, outsider. You never had a chance against me. There was nothing you could have done.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_24.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15940, 'KaomPlayerWonNeutral', '[]', 'Your victory was interesting to watch, at the very least.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15941, 'KaomPlayerLostNeutral', '[]', 'You held yourself well against the Karui''s greatest warriors. That is all you can really hope for, outsider.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15942, 'KaomCommentOnPurchaseItemMaata', '[]', 'Peacemaker, your deals will only aid your enemy!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_22_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15943, 'KaomCommentOnPurchaseEliteAhuana', '[]', 'How original!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_23_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15944, 'KaomCommentOnPurchaseEliteAkoya', '[]', 'The traditional Way leads to victory!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_24_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15945, 'KaomCommentOnPurchaseEliteKiloava', '[]', 'My warriors would have been a better choice!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15946, 'KaomRandomShout1', '[]', 'The outsider walks among us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_26_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15947, 'KaomRandomShout2', '[]', 'Today is a good day for battle.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_26_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15948, 'KaomGossipOnTrappedInADream', '[]', 'My dream, my Nightmare, seemed without end. I couldn''t think, couldn''t hope, couldn''t fight to escape. There was only madness and pain. I believed I had built a home and an empire for my people, but in truth, it was all a lie. You shattered my nightmare and slew Malachai, and for that, I have made no argument against your presence in this sacred place. Consider us even. I owe you nothing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_27.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15949, 'KaomGossipOnTukohamasDefeat', '[]', '<i>{You} defeated Tukohama in battle? No, you defeated a shadow of the Father of War. He was weakened by his long sleep, or by the pervasive Corruption of Wraeclast. You struck when he was feeble and confused. Keep your ego small. ' || char(13) || '
' || char(13) || '
Hmm... perhaps <i>{I} could be the next Father of War... if such a thing is possible....', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_28.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15950, 'KaomGossipOnKitavasDefeat', '[]', 'I did hear that you ''defeated'' Kitava. You should be aware that he was nothing more than a hungry blind child, propped up and fed by Utula''s tribe. How exactly did you fear he would consume the whole world when he could hardly move from his cathedral cradle? Your great victory, ''Godslayer,'' is nothing to brag about. We have not needed our gods to be personally present for thousands of years, and we will not be diminished by their loss. We have our own strength.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_29.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15951, 'KaomGossipOnInvasionOfWraeclast', '[]', 'Uniting the tribes was a worthy endeavour. Invading the mainland, however, was a fool''s errand. Wraeclast has only ever been an accursed place that no true Karui should ever step foot on. I wish I had known how tainted it truly was. I would have set fire to it rather than try to claim it. Every empire that has ever arisen there eventually collapsed under the weight of its own disease.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_30.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15952, 'KaomGossipOnHyrri', '[]', 'Hyrri is not here... I hoped to greet her in the afterlife, but her soul has not found its way to the Halls of the Dead. My tribe''s <i>{hatungo}, Lavianga, believed that Hyrri damned herself by breaking the <i>{tavukai}, but that is not a rule the Ramako Tribe follows. I was certain there would be no dishonour in the eyes of the gods, yet Navali remains cryptic on her absence. She should be here. I am... incensed.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_31.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15953, 'KaomGossipOnHyrrisSoul', '[]', 'So, you have found Hyrri''s soul! Our <i>{hatungo} knows nothing of this Domain of Timeless Conflict, but it seems that we have a new realm to make war upon. We will find it and rescue Hyrri and her army, no matter the cost. Not a single Karui soul will be left behind. This is the promise I make to our Ancestors! We will have our vengeance!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_32.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15954, 'KaomGossipOnTheKaruiWay', '[]', 'I have already proven that the Karui Way is the one true path. I united the otherwise squabbling tribes into one mighty horde, the greatest the world has ever known, and I did that with the sheer force of my axe. There are chieftains among us here that experienced that firsthand. They know not to challenge me. You should know that as well.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_33.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15955, 'KaomGossipOnWraeclast', '[]', 'Let Wraeclast fester in darkness. It is a diseased land not fit for life. My advice to future generations of Karui shall always be so: keep to the islands and their abundance. Let the ruins of the Eternal and the Vaal Empires rot like the corpses they are. If Wraeclast needs anything, it is fire, to burn away that which can never be pure again.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_34.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15956, 'KaomGossipOnTheHallsOfTheDead', '[]', 'Even before I ventured to the Isle of the Shrikes, I knew I would earn my place here. Now, I will prove my might in each new Trial. I will never be deposed. This honour is mine forever... or until Time ends, as Navali claims it will one day. How absurd.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_35.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15957, 'KaomGossipOnTheEndOfTime', '[]', 'The Hinekora Tribe thinks Time will simply stop one day. No. The Ngamahu Tribe believes the world will end, not with some pathetic unraveling of the seasons, but with a tremendous eruption. Wraeclast will stab itself and pour forth its lifeblood to burn away all life, both the mighty and the diseased, as it has done before. Then, the first of a new line of Karui will emerge from the molten caldera, as we did before. They will be different. Maybe better, in some sense, having learned from the wisdom our souls will carry forward. Theirs will be a savage new world to conquer all over again. I wish I could be there to see it... a glorious new challenge unlike any other... but my soul will be returned to the volcano with all the others here in the Halls of the Dead, to be melted and reforged into that entirely new Karui essence, that new line. I could wish for no better end.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_36.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15958, 'KaomGossipOnHinekora', '[]', 'Hinekora shall always be honoured as the Mother of Death and the creator of this place, but she rarely speaks. I believe she is lost in her visions. It is unclear how much Navali communicates with her, and how much the <i>{hatungo} is saying on her own...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_37.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15959, 'KaomGossipOnNgamahu', '[]', 'For countless generations, a small number of my tribe secretly watched over Ngamahu as she slept. She must have awoken by now, but I have heard nothing of her whereabouts or intent. It is frustrating having to remain here in the Halls of the Dead while the Mother of Fire walks the world in the flesh. I would very much like to meet her. Before I was of age, my father''s father allowed me to look upon her sleeping face. It was only then that I understood that there are types of fire unknown to a mere boy.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_38.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15960, 'KaomGossipToMarauder', '[]', 'You are a true son of the Karui. You honour the Way with your strength. Though I may challenge you in the Trials, you have my respect.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom/Kaom_322_39.ogg', '', 0, 0, '', 1, 0, 1, '[589,626]', NULL, 0, 0, '[]', 100),
(15961, 'KaomConversationWithUtulaOne', '[]', 'Utula! You are most welcome here. Tell me, how did you die?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_27_01.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15962, 'KaomConversationWithUtulaTwo', '[]', 'I should have guessed. How... irritating.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_27_02.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15963, 'KaomConversationWithKiloavaOne', '[]', 'Insult me all you want, but not like that. Never like that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kaom/Kaom_Wild/Kaom_322_Wild_28.ogg', '', 0, 0, '', 1, 0, 1, '[589]', NULL, 0, 0, '[]', 100),
(15964, 'KiloavaLikesPlayerIsChampion', '[]', 'Makanga!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15965, 'KiloavaNeutralPlayerIsChampion', '[]', 'Fight! Fight! Fight!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15966, 'KiloavaDislikesPlayerIsChampion', '[]', 'Karui! Karui!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15967, 'KiloavaLikesPlayerLostLast', '[]', 'Rise up, outsider!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15968, 'KiloavaNeutralPlayerLostLast', '[]', 'Let''s see some blood!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15969, 'KiloavaDislikesPlayerLostLast', '[]', 'This is going to be a bloodbath!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15970, 'KiloavaLikesPlayerNoRecord', '[]', 'Outsider! Kill them all!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15971, 'KiloavaNeutralPlayerNoRecord', '[]', 'Someone get me some mead!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15972, 'KiloavaDislikesPlayerNoRecord', '[]', 'What''s this disgraceful setup?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15973, 'KiloavaCommentsOnAkoya', '[]', 'Akoya! Akoya! Akoya!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15974, 'KiloavaCommentsOnIkiaho', '[]', 'Boo, Ikiaho! Chill someone else''s battlefield!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15975, 'KiloavaCommentsOnKahuturoa', '[]', 'Can the turtle be taken down?!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15976, 'KiloavaCommentsOnKaom', '[]', 'Kick Kaom right in his massive ego!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15977, 'KiloavaCommentsOnMaata', '[]', 'Let''s get some real warmongers out there!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15978, 'KiloavaCommentsOnRakiata', '[]', 'Move like the ocean, sting like the storm!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15979, 'KiloavaCommentsOnTawhanuku', '[]', 'No one ever knows what you''re talking about, woman!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15980, 'KiloavaCommentsOnUtula', '[]', 'Let''s see if Utula really can burn it all down!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15981, 'KiloavaCommentsOnAhuana', '[]', 'Go wanna-wanna!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(15982, 'KiloavaFightBeginsPlayerWonLast1', '[]', 'I''m going to crush you... like a hurricane!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15983, 'KiloavaFightBeginsPlayerLostLast1', '[]', 'This should be easy!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15984, 'KiloavaFightBeginsPlayerMoreSoldiers1', '[]', 'Your army means nothing to me!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15985, 'KiloavaFightBeginsPlayerLessSoldiers1', '[]', 'You should have brought more warriors!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15986, 'KiloavaFightBeginsPlayerMoreItems1', '[]', 'Look at all that gear. I''m still going to win!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15987, 'KiloavaFightBeginsPlayerLessItems1', '[]', 'Did you forget to equip your warriors?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15988, 'KiloavaFightBeginsPlayerMoreFieldItems1', '[]', 'This battlefield is so cluttered!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15989, 'KiloavaFightBeginsPlayerLessFieldItems1', '[]', 'A nice clean battlefield!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15990, 'KiloavaWarcry1', '[]', 'For Valako!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_09_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15991, 'KiloavaWarcry2', '[]', 'For Valako!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_09_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15992, 'KiloavaWarcry3', '[]', 'Become the storm!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_09_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(15993, 'KiloavaWarcry4', '[]', 'Become the storm!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_09_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
