(16004, 'KiloavaTotemDestroyed3', '[]', 'Cheater! They''re cheating!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_11_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16005, 'KiloavaTotemDestroyed4', '[]', 'Cheater! They''re cheating!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_11_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16006, 'KiloavaTotemDestroyed5', '[]', 'Valako ravage you all!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_11_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
