(16010, 'KiloavaYourTeamTotemDestroyed3', '[]', 'We just keep winning!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_12_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16011, 'KiloavaYourTeamTotemDestroyed4', '[]', 'We just keep winning!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_12_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16012, 'KiloavaYourTeamTotemDestroyed5', '[]', 'So easy!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_12_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16013, 'KiloavaYourTeamTotemDestroyed6', '[]', 'So easy!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_12_03_02.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16014, 'KiloavaYourTotemDestroyed1', '[]', 'I didn''t even break a sweat!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_13_01_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16015, 'KiloavaYourTotemDestroyed2', '[]', 'I didn''t even break a sweat!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_13_01_02.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16016, 'KiloavaYourTotemDestroyed3', '[]', 'This was hardly a battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_13_02_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16017, 'KiloavaYourTotemDestroyed4', '[]', 'This was hardly a battle!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_13_02_02.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16018, 'KiloavaYourTotemDestroyed5', '[]', 'Woooo!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_13_03_01.ogg', '', 0, 0, '', 1, 60000, 1, '[603]', NULL, 0, 0, '[]', 100),
(16019, 'KiloavaCommentDefeatedYou1', '[]', 'I am the greatest of all time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_14_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16020, 'KiloavaCommentDefeatedYou2', '[]', 'I am the greatest of all time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_14_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16021, 'KiloavaCommentDefeatedYou3', '[]', 'Another victory for me... and Valako!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_14_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16022, 'KiloavaCommentDefeatedYou4', '[]', 'Another victory for me... and Valako!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_14_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16023, 'KiloavaCommentDefeatedYou5', '[]', 'Ha ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_14_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16024, 'KiloavaCommentWhenDefeated1', '[]', 'Lucky! You got lucky!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_15_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16025, 'KiloavaCommentWhenDefeated2', '[]', 'Lucky! You got lucky!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_15_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16026, 'KiloavaCommentWhenDefeated3', '[]', 'My warriors screwed up! It''s their fault!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_15_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16027, 'KiloavaCommentWhenDefeated4', '[]', 'My warriors screwed up! It''s their fault!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Field/Kiloava_Field_15_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[603]', NULL, 0, 0, '[]', 100),
(16028, 'KiloavaCommentsFromStandsOnMatch1', '[]', 'I should show these amateurs a thing or two!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_22_01.ogg', '', 0, 0, '', 1, 0, 1, '[612]', NULL, 0, 0, '[]', 100),
(16029, 'KiloavaCommentPurchaseItem1', '[]', 'You hardly deserve Valako''s gifts!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_01_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16030, 'KiloavaCommentPurchaseItem2', '[]', 'You hardly deserve Valako''s gifts!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_01_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16031, 'KiloavaCommentPurchaseItem3', '[]', 'Better not use that against me!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_01_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16032, 'KiloavaCommentPurchaseItem4', '[]', 'Better not use that against me!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_01_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16033, 'KiloavaCommentPurchaseFieldItem1', '[]', 'Pfft.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_02_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16034, 'KiloavaCommentPurchaseFieldItem2', '[]', 'Pfft.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_02_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16035, 'KiloavaCommentPurchaseFieldItem3', '[]', 'I still can''t believe these things are permitted.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_02_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16036, 'KiloavaCommentPurchaseFieldItem4', '[]', 'I still can''t believe these things are permitted.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_02_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16037, 'KiloavaCommentInspectRecruits1', '[]', 'Valako''s finest!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_03_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16038, 'KiloavaCommentInspectRecruits2', '[]', 'Valako''s finest!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_03_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16039, 'KiloavaCommentInspectRecruits3', '[]', 'The best in all of history!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_03_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16040, 'KiloavaCommentInspectRecruits4', '[]', 'The best in all of history!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_03_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16041, 'KiloavaCommentRecruitRecruit1', '[]', 'You won''t be disappointed.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_04_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16042, 'KiloavaCommentRecruitRecruit2', '[]', 'You won''t be disappointed.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_04_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16043, 'KiloavaCommentRecruitRecruit3', '[]', 'Now you have a chance.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_04_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16044, 'KiloavaCommentRecruitRecruit4', '[]', 'Now you have a chance.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_04_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16045, 'KiloavaPlayerWonVsIkiaho', '[]', 'You humbled Ikiaho! While she''s feeling down, perhaps I''ll once again ask her to go through the traditions with me. What''s the worst she could say?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_05.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16046, 'KiloavaPlayerLostVsIkiaho', '[]', 'Nobody thaws the frozen heart, as they say.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_06.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16047, 'KiloavaPlayerWonVsKaom', '[]', 'Ha ha! Kaom of legend, humiliated! What a match!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_07.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16048, 'KiloavaPlayerLostVsKaom', '[]', 'Of course you lost to Kaom. He''s <i>{Kaom}. Why did you even fight him?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_08.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16049, 'KiloavaPlayerWonVsMaata', '[]', 'Congratulations on beating up an old man.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_09.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16050, 'KiloavaPlayerLostVsMaata', '[]', 'Ha ha! You got thrashed by an old man! I never thought I''d live to see the day.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_10.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16051, 'KiloavaPlayerWonVsAhuana', '[]', 'You haven''t humbled Ahuana. She was a great leader of the united Karui tribes. You can''t even begin to bother her.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_11.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16052, 'KiloavaPlayerLostVsAhuana', '[]', 'Ahuana can''t be matched! Arrow in the eye! Yeah!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_12.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16053, 'KiloavaPlayerWonVsAkoya', '[]', 'You only defeated Akoya because she plays fair. Remember that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_13.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16054, 'KiloavaPlayerLostVsAkoya', '[]', 'Akoya! Now there''s a Karui woman! What strength!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_14.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16055, 'KiloavaPlayerWonAgainstThem', '[]', 'You and I both know you cheated against me. Don''t speak to me like you''re a real competitor.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_15.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16056, 'KiloavaPlayerLostAgainstThem', '[]', 'Ha ha, outsider, I <i>{destroyed} you!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_16.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16057, 'KiloavaPlayerWonNeutral', '[]', 'That was a decent match to watch. You''re something of a warrior. Just something. Don''t get an ego.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_17.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16058, 'KiloavaPlayerLostNeutral', '[]', 'That defeat must sting! You got crushed!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_18.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16059, 'KiloavaCommentOnPurchaseItemAkoya', '[]', 'Akoya! Akoya! Yeah!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16060, 'KiloavaCommentOnPurchaseItemAhuana', '[]', 'The Ramako Tribe knows how to make the good things!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_24.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16061, 'KiloavaCommentOnPurchaseEliteAkoya', '[]', 'Don''t fight me with that.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_25.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16062, 'KiloavaCommentOnPurchaseEliteAhuana', '[]', 'Nobody can stand against Ahuana''s warriors!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_26.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16063, 'KiloavaConversationWithAkoyaOne', '[]', 'I am furious! This is an insult to all of us!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16064, 'KiloavaConversationWithAhuanaOne', '[]', 'Do you think you will ever reach perfection with a bow, Ahuana?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_28_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16065, 'KiloavaConversationWithAhuanaTwo', '[]', 'I don''t know about that. I''m perfect with my weapon.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_28_02.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16066, 'KiloavaConversationWithAhuanaThree', '[]', 'Sometimes, you''re so positive, I think you''re actually mocking—you know what? I''ll just accept the compliment.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_28_03.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16067, 'KiloavaRandomShout1', '[]', 'I am the greatest warrior of all time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_29_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16068, 'KiloavaRandomShout2', '[]', 'Yeaaaaaaaah!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_30_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16069, 'KiloavaRandomShout3', '[]', 'Who can stand against the storm?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_31_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16070, 'KiloavaRandomShout4', '[]', 'What time is it? It''s Kiloava time!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava_Wild/Kiloava_Wild_32_01.ogg', '', 0, 0, '', 1, 0, 1, '[592]', NULL, 0, 0, '[]', 100),
(16071, 'KiloavaGossipOnKaom', '[]', 'Kaom can eat a <i>{rumakino} berry for all I care. I don''t want to talk about him.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_19.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16072, 'KiloavaGossipOnValako', '[]', 'I have a complex relationship with Valako. I speak to him, and he remains silent. It''s just like my last wife! I joke, but... we''re alone. The Karui must forge their own path in this world. Valako is more like our tribe mascot than an actual figure of leadership or aid.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_20.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16073, 'KiloavaGossipOnSouls', '[]', 'Many think I was ''defeated'' by Kaom in some grand battle, but I was seventy-four when he took my head. He essentially bullied an old man. Can you picture my delight when I awoke here in my prime? I know that I give you lots of, what do they say? Shite? Yes, but I''m just overcome with joy at being young and strong again. No harm meant. Oh, and I''m one of the lucky ones. Here, our souls appear as we truly see ourselves. Some of us had some pretty big surprises when they woke up in the Halls of the Dead! Ha ha!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_21.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16074, 'KiloavaGossipOnHeraldOfWar', '[]', 'They call me the first Herald of War, and indeed I was, but they don''t understand. Valako gave a Sign to my people thousands of years ago, a ring with his graven pattern. It passed down from chieftain to chieftain in my tribe. When I put it on, it did something it never had before: it surged with the power of the storm. Valako didn''t know me. How could he? The gods were asleep. So, I appointed <i>{myself} the Herald of War, and I used the power of Valako''s Sign to win many great battles. I laid the foundations for Karui unification before Kaom was even an urge in some bastard''s loins.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_22.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16075, 'KiloavaGossipOnTribes', '[]', 'We all seem neatly divided into our tribes here, but it isn''t so. Warriors switch tribes all the time due to marriage, chieftain successions, or simple wanderlust. We Karui are a nomadic people, in the physical and spiritual sense. When I call my tribe the Valako tribe, yes, we are, but at one time we followed Tukohama, and at another Tasalio, and then Valako again before that. Essentially, each god must prove themselves to us the same way we prove ourselves to each other. If a tribe falls on hard times, clearly, their god has failed them, and it may be time for another. We can also call upon any god we wish at any time, so long as we are in good standing as a warrior. Basically, it''s like children running amok around the campfire.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_23.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16076, 'KiloavaGossipOnTawhanuku', '[]', 'It''s funny, outsider. We think we get to choose who we fight. Tawhanuku already knows ahead of time what we will do, mostly. If you fight her, it''s because she''s chosen to fight <i>{you}. That doesn''t mean she''ll win, though. Even Hinekora''s vision isn''t infallible.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_24.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16077, 'KiloavaGossipOnUtula', '[]', 'He''s an odd tuatara, that one. Seems to think this incredible place is some sort of prison. I for one relish being in my prime again. Maybe he''s just angry he''s got those crazy bug eyes.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_25.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16078, 'KiloavaGossipOnMaata', '[]', 'Ha ha, poor Maata! Because of his true self, he''s cursed to be an old man for eternity! Hilarity!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_26.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16079, 'KiloavaGossipOnBloodline', '[]', 'Certain arrogant warlords claim my bloodline was ended, but they don''t know just how many children I really had... I was something of a madman in my prime! Half the warriors serving under them might be descended from me at this point! Ha ha! Ah... they come to the Halls of the Dead for advice. I tell them to drink, fight, and enjoy life while they have it!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_27.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16080, 'KiloavaGossipOnTheEndOfTime', '[]', 'Have you ever had the feeling, during a rising storm, that the winds and rain might just keep getting stronger and never ebb? That''s how the world will end. A great storm will cover the land, and it will just keep raging harder and harder until everything is swept away. Then, as always happens after a big storm, life will burgeon anew. We see it all the time around us. Why would it be any other way?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_28.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16081, 'KiloavaGossipOnIkiaho', '[]', 'Yes, yes, she has a frozen heart. That''s all anyone ever talks about. She''s turned <i>{me} down a few times, and I''ve gone through the traditions with everyone else here, even Rakiata! No disrespect, if it moves, I''ll chase it! We''re all young again—except for poor Maata, ha ha!—so why shouldn''t we enjoy ourselves?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Kiloava/Kiloava/Kiloava_29.ogg', '', 0, 0, '', 1, 0, 1, '[592,629]', NULL, 0, 0, '[]', 100),
(16082, 'HinekoraTalkOne', '[]', 'Where am I? This cannot be real... but it is. Wraeclast... I long believed this life a dream, but it seems what I just escaped was the true illusion. My family... my boys... my daughter... they weren''t real? Oh, the Halls of the Dead. In this life, I could never... ah... so I gathered up the lost souls of my people, and cherished them as my own. I have so much to tell them, but the dream calls me back! I must... not go...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_01.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16083, 'HinekoraTalkTwo', '[]', '...back again... reality and dream mix together like waves in a tide pool. They called me Mother, but I was forced to abandon them... I remember now, the Imbalance... I foresaw all of this, and the plan is still in motion. We teeter on the edge of oblivion, flailing, waiting to be saved or doomed by the slightest push. The future-past calls to me... I must gaze into the abyss. Heed my words. My children, I will return to you... when the time is right...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_02.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16084, 'HinekoraTalkThree', '[]', 'Waking is such exquisite pain... memory and prophecy are one and the same. I have so much to tell you, but I cannot remember when we are. You''re not even you yet. You come to these Halls of the Dead decades early, wearing a different face, but I''m asleep. You''re here now, as I awaken... and you''re here decades from now, someone else all over again... all these things are true. Time is a hall of mirrors. I... see...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_03.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16085, 'HinekoraTalkFour', '[]', '... it is a gift for you, my daughter... oh. That was just a dream... what does it mean for something to be real? If you loved, and were loved, would it matter if your world was an illusion? He knew the truth. Dominus must catch you. The Arkhon''s plan to rescue his daughter will fail, but you must try anyway. They must all be present at the fulcrum of destiny, if Wraeclast... is to... ', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_04.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16086, 'HinekoraTalkFive', '[]', '... back again... I must fight for every moment of lucidity. Time is shorter than you know. Cataclysms await down most paths, and those paths then turn on and <i>{eat} each other. These things <i>{must happen}. You must make them happen. It begins with the fulcrum of destiny, the moment on which all of existence is balanced. The King of Dreams must be allowed to escape, and though there can be only one, <i>{two} High Templars must witness... this...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_05.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16087, 'HinekoraTalkSix', '[]', '... for once, Chaos is not the enemy... imagine that... they see you for what you truly are, like I do... seek his servant... before that, or after that, I cannot tell... the Maraketh will test you. You will undergo three challenges, and we will be the third... you must prove yourself, or else you... won''t...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_06.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16088, 'HinekoraTalkSeven', '[]', '... listen, quickly... the messenger from the stars was once a man, but before that, he was a father. A sliver of his heart still remains, somewhere deep inside... he knows something vital, but he doesn''t know that he knows... I cannot see it, for I was... never a Mother... Doryani is missing...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_07.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16089, 'HinekoraTalkEight', '[]', '... the Thief... I will suggest he seek counsel in the one place I can never see... upon his return, he will create the Beast... then I am sorry, my children, but I must sleep for time beyond time. The plan is in place. Make no traffic with the Vaal. The horrors of Queen Atziri must happen. On this, we agree, even with our mortal enemy...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_08.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16090, 'HinekoraTalkNine', '[]', '...the Vaal Empire will fall. Doryani... where is Doryani? Malachai must construct his Grand Design, a crucible in which you will be forged, and thus he will be the architect of his own doom. You must... slay the Beast... when the time is right...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_09.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16091, 'HinekoraTalkTen', '[]', '... the King of the Godless must not be allowed to find what he seeks... the Masked One must save his family before crimson touches the mountain peak... the Forger must fail in her reckless mission... just one of these three does not mean the end, but two will spell certain doom...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_10.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16092, 'HinekoraTalkEleven', '[]', '...corruption clouds my sight once more... faithful heroes are trying to save humanity... but they don''t understand... you gathered the peoples of Wraeclast, and stood united... but you failed...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_11.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16093, 'HinekoraTalkTwelve', '[]', '...she will know you by three different faces, as will you, her. You must find her. In her mind... lies... the key...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_12.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16094, 'HinekoraTalkThirteen', '[]', '... how... are... you... here?...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_13.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16095, 'HinekoraTalkFourteen', '[]', '... so... that''s... how it ends... this time...', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16096, 'HinekoraProphecy1', '[]', 'Two hungry children frolic in fire and blood, one small, one enormous. A feast ends at swordpoint. An ivory grin silently faces the oncoming storm.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_01.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16097, 'HinekoraProphecy2', '[]', 'Five brothers vie for kingship in a distant land, yet yearn to be a family once again. Two peoples, seemingly unalike, meet on common ground. The seasons are harsh, and the fruit grows purple and rotted, but a single healthy seed sprouts in a dark place.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_02.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16098, 'HinekoraProphecy3', '[]', 'Beware the gaze of the pale one. A colony of ants burrows through a wall, seeking the treasures beyond. Truth and hope are enemies.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_03.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16099, 'HinekoraProphecy4', '[]', 'Lumbering stomachs with vast mouths consume all that grows. Ignorance is a weapon sharper than any other, though it may cut its wielder just as cleanly.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_04.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16100, 'HinekoraProphecy5', '[]', 'Two enemies, born opposed, clasped hands only once. The silent wall and the raging storm oppose the endless swarm.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_05.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16101, 'HinekoraProphecy6', '[]', 'The cheerful cat is destined, not lucky. The grumpy dog is her guardian, not unlucky. The Queen always was, and always shall—<i>{Alva Valai, stop mucking about in time!}', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_06.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16102, 'HinekoraProphecy7', '[]', 'A liar convinces a good man to flee. A lord ravages his own land in a desperate search for legitimacy. A noblewoman from a distant land is not who she claims to be.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_07.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16103, 'HinekoraProphecy8', '[]', 'A warrior seeks to become a goddess. The rivers flow only with sand. The sins of the parents return in search of blood.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_08.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16104, 'HinekoraProphecy9', '[]', 'A bright future lies in a dark past. The erudite thaumaturge is missing. A grand palace begins to collapse for want of a single brick.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_09.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16105, 'HinekoraProphecy10', '[]', 'A childless Mother sits beneath the sea in a palace filled with the dead. She gives endlessly of herself so that others may live, for she never truly does.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_10.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16106, 'HinekoraProphecy11', '[]', 'Warriors of many different tribes gather to save the world. Warriors of many different tribes gather to doom it. Each thinks the other is the true threat.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_11.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16107, 'HinekoraProphecy12', '[]', 'Great leaders sink into quicksand of the mind. Only a shadow can save the blind.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_12.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16108, 'HinekoraProphecy13', '[]', 'A simple sword against the weight of Time itself. The encircled princes laugh as their blood drains into the soil. The salvation of humanity will be its undoing.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_13.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16109, 'HinekoraProphecy14', '[]', 'Of fear and faith, none can know. One and the same. A new soul arrives. Pain becomes hope becomes apprehension. The hungry child would rather burn it all down.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_14.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16110, 'HinekoraProphecy15', '[]', 'The volcano is mighty and towering, but it consumes all that live in its shadow. The nightmare ends when the dreamer is awakened.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_15.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16111, 'HinekoraProphecy16', '[]', 'The harried mother seeks to pass the entire farm through a pinhole. Though it is the smallest of the animals, the tuatara protests. A river runs between a mountain and a molehill.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_16.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16112, 'HinekoraProphecy17', '[]', 'She will know you by three different faces. You will know her by three different faces. A great silence falls over a vast crowd.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_17.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16113, 'HinekoraProphecy18', '[]', 'The meddlers seek to reflect the world as it was. A court jester leads the nobles through the forest with wild tales and promises of plenty, not knowing the trail ends in a cliff.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_18.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16114, 'HinekoraProphecy19', '[]', 'A spider sits atop a throne of artifice, spinning a web across the world. Corruption begins to ooze like blood across the sea, tainting unspoiled loam.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_19.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16115, 'HinekoraProphecy20', '[]', 'A mask hides grief beyond measure. A man carrying a mountain threatens to rupture the sky.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_20.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16116, 'HinekoraProphecy21', '[]', 'A key passes hands many times, but must be recovered before the Awakener can imprison the King of Dreams. The King of Dreams will be released by the removal of a key from a lock.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora_Prophecy/Hinekora_Prophecy_21.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16117, 'HinekoraPresentRewardsRandom', '[]', 'Approach, and claim your reward.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14_01.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16118, 'HinekoraPresentRewards2', '[]', 'Approach, and claim your reward.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14_02.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16119, 'HinekoraPresentRewards3', '[]', 'Approach, and claim your reward.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14_03.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16120, 'HinekoraPresentRewards4', '[]', 'Approach, and claim your reward.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14_04.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16121, 'HinekoraPresentRewards5', '[]', 'Approach, and claim your reward.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14_05.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16122, 'HinekoraPresentRewards6', '[]', 'Approach, and claim your reward.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Hinekora/Hinekora/Hinekora_14_06.ogg', '', 0, 0, '', 1, 0, 1, '[619]', NULL, 0, 0, '[]', 100),
(16123, 'NavaliAnnouncerAnnouncesRanger', '[]', 'A Ranger, swift and solitary, has come from the living realm to hone her skills here.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_06.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16124, 'NavaliAnnouncerAnnouncesShadow', '[]', 'A Shadow, master of the unseen arts, seeks to learn from us.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_07.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16125, 'NavaliAnnouncerAnnouncesScion', '[]', 'A Scion has come to us, to realize her potential.', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_08.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16126, 'NavaliAnnouncerReinforcesWorthy', '[]', 'Do you doubt the foresight of the Mother of Death? Hinekora wills it, so it must be done. If you are so sure of your own superiority, then make the challenge yourself!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_09.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16127, 'NavaliAnnouncesAkoyaFirstTime', '[]', 'Step forward, then, Akoya of the Tukohama Tribe! Show this newcomer the might of the Karui! ', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_10.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16128, 'NavaliAnnouncerFirstBattleIntroEver', '[]', 'The outsider steps forth! Let us see what skills a foreign warrior brings to the battlefield!', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_11.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16129, 'NavaliAnnouncerAnnouncesPlayerNew1', '[]', 'The newcomer girds for battle. Will this be their victory to claim?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_12.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
(16130, 'NavaliAnnouncerAnnouncesPlayerNew2', '[]', 'Fate conspires to set the stage for a legendary battle. Will the newcomer be up to the task?', 'Audio/Dialogue/Leagues/TrialOfTheAncestors/Navali/Navali_Announcer/Navali_Announcer_13.ogg', '', 0, 0, '', 1, 0, 1, '[588]', NULL, 0, 0, '[]', 100),
