(16955, 'EldritchHunger_Idle_29', '[]', '', 'Audio/Dialogue/NPC/EldritchHunger_Armour/EldritchHungerArmour_Idle_29.dialogue.ogg', '', 0, 0, '', 1, 3, 1, '[664]', NULL, 0, 0, '[]', 100),
(16956, 'EldritchHunger_Idle_30', '[]', '', 'Audio/Dialogue/NPC/EldritchHunger_Armour/EldritchHungerArmour_Idle_30.dialogue.ogg', '', 0, 0, '', 1, 3, 1, '[664]', NULL, 0, 0, '[]', 100),
(16957, 'UndertakerIntroCoast', '[]', 'An exile with a talent for killing? Colour me shocked. I''ll make you the same offer I made the others. Take this lantern. I think you''ll appreciate what you can see by its ghastly light. You go ahead and do what you do, and I''ll collect the most interesting bodies you fell. Once you''ve got one, we''ll talk...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_01.ogg', '', 0, 0, '', 1, 0, 1, '[658,661]', NULL, 0, 0, '[]', 100),
(16958, 'UndertakerWildCollectFirstCorpse', '[]', 'Well well, this one''s got quite the unfinished business.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16959, 'UndertakerFirstCorpseTalk', '[]', 'This corpse''ll do. Full of anguish, just how we need. Keep making them, and I''ll keep scooping them. When we''ve got enough, we can perform certain rites at the Necropolis... visit me, and there''ll be something in it for you. No questions asked.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16960, 'UndertakerWildSummon_Random', '[]', 'It''s dirty work, but somebody''s gotta do it.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16961, 'UndertakerWildSummon_2', '[]', 'It''s dirty work, but somebody''s gotta do it.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16962, 'UndertakerWildSummon_3', '[]', 'It''s dirty work, but somebody''s gotta do it.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16963, 'UndertakerWildSummon_4', '[]', 'Another day, another death.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16964, 'UndertakerWildSummon_5', '[]', 'Another day, another death.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16965, 'UndertakerWildSummon_6', '[]', 'Another day, another death.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16966, 'UndertakerWildSummon_7', '[]', 'The work continues!', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16967, 'UndertakerWildSummon_8', '[]', 'The work continues!', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16968, 'UndertakerWildSummon_9', '[]', 'What have you got for me today, exile?', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16969, 'UndertakerWildSummon_10', '[]', 'What have you got for me today, exile?', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16970, 'UndertakerWildSummon_11', '[]', 'What have you got for me today, exile?', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_05_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16971, 'UndertakerWildSummon_12', '[]', 'More fodder for the pile.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16972, 'UndertakerWildSummon_13', '[]', 'More fodder for the pile.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16973, 'UndertakerWildSummon_14', '[]', 'More fodder for the pile.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_06_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16974, 'UndertakerWildSummon_15', '[]', 'This''ll do nicely.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16975, 'UndertakerWildSummon_16', '[]', 'This''ll do nicely.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16976, 'UndertakerWildSummon_17', '[]', 'This''ll do nicely.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_07_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16977, 'UndertakerWildSummon_18', '[]', 'Oh, it''s a ripe one!', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16978, 'UndertakerWildSummon_19', '[]', 'Oh, it''s a ripe one!', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16979, 'UndertakerWildSummon_20', '[]', 'Ugh.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_09_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16980, 'UndertakerWildSummon_21', '[]', 'Ugh.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_09_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16981, 'UndertakerWildSummon_22', '[]', 'Ugh.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_09_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16982, 'UndertakerWildSummon_23', '[]', 'Sometimes I tire of this job.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_10_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16983, 'UndertakerWildSummon_24', '[]', 'Sometimes I tire of this job.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_10_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16984, 'UndertakerWildSummon_25', '[]', 'Sometimes I tire of this job.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_10_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16985, 'UndertakerWildSummonMaps_Random', '[]', 'Where in the bloody boondocks have you taken us?', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_11_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16986, 'UndertakerWildSummonMaps_2', '[]', 'Where in the bloody boondocks have you taken us?', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_11_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16987, 'UndertakerWildSummonMaps_3', '[]', 'Where in the bloody boondocks have you taken us?', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_11_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16988, 'UndertakerWildSummonMaps_4', '[]', 'How''d you find a corpse in all this misty emptiness? Oh... I see now... how strange...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_12_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16989, 'UndertakerWildSummonMaps_5', '[]', 'How''d you find a corpse in all this misty emptiness? Oh... I see now... how strange...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_12_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16990, 'UndertakerWildSummonMaps_6', '[]', 'How''d you find a corpse in all this misty emptiness? Oh... I see now... how strange...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_12_03.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16991, 'UndertakerWildAlmostFull_Random', '[]', 'We''re almost full up, exile. Might want to make use of our stored corpses. They''re starting to... smell.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_13_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16992, 'UndertakerWildAlmostFull_2', '[]', 'We''re almost full up, exile. Might want to make use of our stored corpses. They''re starting to... smell.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_13_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16993, 'UndertakerWildAlmostFull_3', '[]', 'Morgue''s almost full, exile. Might want to take care of that.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_14_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16994, 'UndertakerWildAlmostFull_4', '[]', 'Morgue''s almost full, exile. Might want to take care of that.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_14_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16995, 'UndertakerWildAlmostFull_5', '[]', 'Running out of room at the Necropolis...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_15_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16996, 'UndertakerWildMorgueFull_Random', '[]', 'Got no more room in the morgue. Let''s talk. See what we want to dump or keep.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_16_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16997, 'UndertakerWildMorgueFull_2', '[]', 'Got no more room in the morgue. Let''s talk. See what we want to dump or keep.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_16_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16998, 'UndertakerWildMorgueFull_3', '[]', 'Morgue''s full. What do you want me to do? We can dump some.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_17_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(16999, 'UndertakerWildMorgueFull_4', '[]', 'Morgue''s full. What do you want me to do? We can dump some.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_17_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100);
INSERT INTO "NPCTextAudio" ("_row", "Id", "Characters", "Text", "Mono_AudioFile", "Stereo_AudioFile", "HasStereo", "__col6", "Video", "__col8", "__col9", "__col10", "NPCs", "NPCPortrait", "__col13", "__col14", "Cooldown", "__col16") VALUES
(17000, 'UndertakerWildMorgueFull_5', '[]', 'Dead man''s locker is overflowing. Time to make some tough choices.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_18_01.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(17001, 'UndertakerWildMorgueFull_6', '[]', 'Dead man''s locker is overflowing. Time to make some tough choices.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Wild/Undertaker_Wild_18_02.ogg', '', 0, 0, '', 1, 0, 1, '[658]', NULL, 0, 0, '[]', 100),
(17002, 'UndertakerIntroNecropolis', '[]', 'Welcome to my little slice of Wraeclast, Exile. Got a morgue that can hold a number of bodies, but if it gets full, we''ll have to choose what we want to keep. While you''re here, we can do some burials... free some spirits. I think you''ll be mighty interested in what happens when we do.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_03.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17003, 'UndertakerOnFirstBuryCorpse', '[]', 'When we bury our anguished friends, the pattern matters. Exorcisms are all about patterns, you see? Patterns of angst, patterns of pain... patterns of Corruption. Choose our plots carefully.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_04.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17004, 'UndertakerOnHimself', '[]', 'You might call me the last true citizen of the Eternal Empire. Or you can call me Arimor, my actual name, but I suppose I do just call you Exile, so fair''s fair. Most exiles don''t live very long, so I don''t bother learning names, but yours is... well, I''ll just say, your parents must have been quite strange.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_05.ogg', '', 0, 0, '', 1, 0, 1, '[659,658,661,660]', NULL, 0, 0, '[]', 100),
(17005, 'UndertakerOnLantern', '[]', 'It''s no Allflame, but it gets the job done. Let''s leave it at that.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_06.ogg', '', 0, 0, '', 1, 0, 1, '[659,658,661,660]', NULL, 0, 0, '[]', 100),
(17006, 'UndertakerOnTheJob', '[]', 'You don''t really want to know. A withered old man, hanging out by himself in a graveyard, collecting corpses... I have to assume you''re not <i>{actually} asking... after all, none of the other exiles I work with have ever shown an interest.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_07.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17007, 'UndertakerOnTheJob2', '[]', 'I''m not up to anything nefarious or disgusting, I can promise you that. Best leave well enough alone.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_08.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17008, 'UndertakerOnTheJob3', '[]', 'What''s this obsession with the meaning behind our work? Aren''t the baubles unearthed here enough to satiate you? Just kill things, and stop asking questions! ', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_09.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17009, 'UndertakerOnPlayerAllflame', '[]', 'Is that... the Allflame? You''ve brought it <i>{here?} Fool! Don''t you know what the Allflame is capable of? Its long and storied history of tragedy and misery—no, no, I shouldn''t blame you. No way for an uncivilised exile to know. Just keep it away from me, and definitely don''t let its light fall upon the graves! I''m sure even a wanderer like you has heard about <i>{that} little disaster...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_10.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17010, 'UndertakerOnExorscisms', '[]', 'You can pilfer shiny things from a corpse, but you can pilfer <i>{glorious} things from a soul! Only source of plasm I''ve ever seen... love this old Wraeclast, I do... Damned fool he was, that Voll...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_11.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17011, 'UndertakerOnPlasm', '[]', 'There''s a white <i>{goo} that comes off properly exorcised souls. I''ve got a colleague I correspond with, he calls them humors, but I don''t see anything funny about it. He''s got plots, too, though I don''t know what it is he''s scheming. He''s a strange one, that. Never quite makes sense. Loves his plants, hates warlocks. Now, what were we talking about? I can''t quite remember. Back to work, I suppose.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_12.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17012, 'UndertakerOnOtherExiles', '[]', 'I''ve long had my fingers in quite a few... pies. I''ve learned to be discreet in my dealings, however. Few exiles can be truly trusted. There was a time when Torr Olgosso simply would not leave me alone. Everywhere I turned, there he was! He and I had to have a talk about boundaries... yes, boundaries... and I certainly did not appreciate Igna Phoenix accidentally setting my work on fire... but the greatest betrayal, of course... my former apprentice and I did not part on good terms, to put it mildly...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_13.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17013, 'UndertakerOnApprentice', '[]', 'Fancies herself a Master of Undeath these days... or would the term be Mistress of Undeath? No, that doesn''t sound right... but she''s meddling with forces beyond mortal control, and it will not end well for any of us. I won''t betray her, though, no matter what she did to me. You''ll have to find her yourself.', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_14.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17014, 'UndertakerOnCatarina', '[]', 'It was you who slew Catarina? I suppose it had to be done. My former apprentice forged her own path, and her own doom. I begrudge you nothing. I did find and retrieve her body, but I''ll not allow it to be part of this sordid business. Sod off. I''ve work to do... rites to perform...', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_15.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17015, 'UndertakerOnChitus', '[]', 'Chitus could have led the Empire to greatness, had he not been viciously betrayed. He was a visionary! My line has worked tirelessly for three centuries to enact this—ah, you clever fox! You almost had me spilling my secrets! The solitude really must be getting to me. This old man''ll never talk!', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker/Undertaker_16.ogg', '', 0, 0, '', 1, 0, 1, '[659,660]', NULL, 0, 0, '[]', 100),
(17016, 'UndertakerChantGeneric_1', '[]', 'May the great Emperor Chitus free you of your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_01.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 7.119999885559082, '[]', 100),
(17017, 'UndertakerChantGeneric_2', '[]', 'May the Shine of Solaris burn away your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 6.880000114440918, '[]', 100),
(17018, 'UndertakerChantGeneric_3', '[]', 'May the Shine of Solaris burn away your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 6.340000152587891, '[]', 100),
(17019, 'UndertakerChantGeneric_4', '[]', 'May the Glow of Lunaris heal your pains and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 5.710000038146973, '[]', 100),
(17020, 'UndertakerChantGeneric_5', '[]', 'May the Glow of Lunaris heal your pains and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 5.989999771118164, '[]', 100),
(17021, 'UndertakerChantGeneric_6', '[]', 'May the Grace of Prospero relieve you of your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 6.360000133514404, '[]', 100),
(17022, 'UndertakerChantGeneric_7', '[]', 'May the Grace of Prospero relieve you of your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 7.170000076293945, '[]', 100),
(17023, 'UndertakerChantGeneric_8', '[]', 'May the Tides of Tsoagoth wash away your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 6.320000171661377, '[]', 100),
(17024, 'UndertakerChantGeneric_9', '[]', 'May the Tides of Tsoagoth wash away your anguish and aid this soldier,', 'Audio/Dialogue/Leagues/Necropolis/Undertaker/Undertaker_Craft/Undertaker_Craft_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[659]', NULL, 1, 6.210000038146973, '[]', 100),
