(18405, 'TujenSettlersWildYellWorker_3', '[]', 'Get those crates where they need to be, now!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_01C.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18406, 'TujenSettlersWildYellWorker_4', '[]', 'We''re not paying you to laze about!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_02A.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18407, 'TujenSettlersWildYellWorker_5', '[]', 'We''re not paying you to laze about!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_02B.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18408, 'TujenSettlersWildYellWorker_6', '[]', 'We''re not bloody paying you to laze about!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_02C.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18409, 'TujenSettlersWildYellWorker_7', '[]', 'That shipment''s got to go out today!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_03A.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18410, 'TujenSettlersWildYellWorker_8', '[]', 'That shipment''s got to go out today!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_03B.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18411, 'TujenSettlersWildYellWorker_9', '[]', 'That shipment''s got to go out today!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_03C.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18412, 'TujenSettlersWildYellWorker_10', '[]', 'Let''s get that loaded!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_04A.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18413, 'TujenSettlersWildYellWorker_11', '[]', 'Let''s get that loaded, c''mon, c''mon!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_04B.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18414, 'TujenSettlersWildYellWorker_12', '[]', 'C''mon, let''s get that loaded!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_04C.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18415, 'TujenSettlersWildYellWorker_13', '[]', 'No, just leave the shipment there, it''s not like it''s gotta go out today or anythin''!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_06_05A.ogg', '', 0, 0, '', 1, 45000, 1, '[674]', NULL, 0, 0, '[]', 100),
(18416, 'TujenSettlersWildTalkToSelf_Random', '[]', 'Now what was the name of that wench last night?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18417, 'TujenSettlersWildTalkToSelf_2', '[]', 'Ah, the smell of sea salt on the wind.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18418, 'TujenSettlersWildTalkToSelf_3', '[]', 'Damn this leg itch.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_07_03.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18419, 'TujenSettlersWildTalkToSelf_4', '[]', 'I <i>{love} this job.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_07_04.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18420, 'TujenSettlersConvoWithDannigOne', '[]', 'Damn it all. Damn the war. Damn the King!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18421, 'TujenSettlersConvoWithDannigTwo', '[]', 'You know why. You were there.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18422, 'TujenSettlersConvoWithDannigThree', '[]', 'Yeah, yeah, yeah...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_08_03.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18423, 'TujenSettlersConvoWithIslaOne', '[]', 'Hey Isla, how''s that self-propelling ship coming along?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_09_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18424, 'TujenSettlersConvoWithIslaTwo', '[]', 'Does it now? I think I can guess the bad news.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_09_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18425, 'TujenSettlersConvoWithRogOne', '[]', 'Rog, when''s our next game?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_10_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18426, 'TujenSettlersConvoWithRogTwo', '[]', 'Ain''t that the bloody truth.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_10_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18427, 'TujenSettlersConvoWithFaustusOne', '[]', 'You seem to know a lot about shipping lane particulars, Faustus.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_11_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18428, 'TujenSettlersConvoWithFaustusTwo', '[]', 'Yeah, yeah.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_11_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18429, 'TujenSettlersConvoWithRaulfOne', '[]', 'How''d you uh, lose the eye, Raulf?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_12_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18430, 'TujenSettlersConvoWithRaulfTwo', '[]', 'Hahahaha! Oh, I like you.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_12_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18431, 'TujenSettlersConvoWithSonjaOne', '[]', 'Is it your day off, Sonja?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_13_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18432, 'TujenSettlersConvoWithSonjaTwo', '[]', 'Then how do you relax?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_13_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18433, 'TujenSettlersConvoWithSonjaThree', '[]', 'Heh heh, don''t mind if I do.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_13_03.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18434, 'TujenSettlersConvoWithGwennenOne', '[]', 'How''s your luck lately?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_14_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18435, 'TujenSettlersConvoWithGwennenTwo', '[]', 'I''ll drink to that.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_14_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18436, 'TujenSettlersConvoWithJohanOne', '[]', 'How do you get off playing both sides, Johan?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_15_01.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18437, 'TujenSettlersConvoWithJohanTwo', '[]', 'Whatever helps you sleep at night.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_15_02.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18438, 'TujenSettlersWildApproach_Random', '[]', 'Eh, whosat?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_16_01A.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18439, 'TujenSettlersWildApproach_2', '[]', 'Eh, whosat?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_16_01B.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18440, 'TujenSettlersWildApproach_3', '[]', 'Eh, whosat?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_16_01C.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
(18441, 'TujenSettlersWildApproach_4', '[]', 'Oh good, more work.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Tujen/Tujen_Wild/TujenSettlers_Wild_16_03A.ogg', '', 0, 0, '', 1, 0, 1, '[674]', NULL, 0, 0, '[]', 100),
