(18493, 'RogSettlersRemoveDisenchantAmazing_Random', '[]', 'Really enjoyed working with them!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_21_01A.ogg', '', 0, 0, '', 1, 45000, 1, '[672]', NULL, 0, 0, '[]', 100),
(18494, 'RogSettlersRemoveDisenchantAmazing_2', '[]', 'Really enjoyed working with them!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_21_01B.ogg', '', 0, 0, '', 1, 45000, 1, '[672]', NULL, 0, 0, '[]', 100),
(18495, 'RogSettlersRemoveDisenchantAmazing_3', '[]', 'I really enjoyed working with them!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_21_01C.ogg', '', 0, 0, '', 1, 45000, 1, '[672]', NULL, 0, 0, '[]', 100),
(18496, 'RogSettlersRemoveDisenchantAmazing_4', '[]', 'Hope to work with them again!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_21_02A.ogg', '', 0, 0, '', 1, 45000, 1, '[672]', NULL, 0, 0, '[]', 100),
(18497, 'RogSettlersRemoveDisenchantAmazing_5', '[]', 'Ha hah, I hope to work with them again!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_21_02B.ogg', '', 0, 0, '', 1, 45000, 1, '[672]', NULL, 0, 0, '[]', 100),
