(18500, 'RogSettlersIdleWorkerNoGold_2', '[]', 'Go see the treasurer - we got idle hands over here!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_22_01B.ogg', '', 0, 0, '', 1, 0, 1, '[672]', NULL, 0, 0, '[]', 100),
(18501, 'RogSettlersIdleWorkerNoGold_3', '[]', 'Go see the treasurer - we got idle hands over here!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_22_01C.ogg', '', 0, 0, '', 1, 0, 1, '[672]', NULL, 0, 0, '[]', 100),
(18502, 'RogSettlersIdleWorkerNoGold_4', '[]', 'We''re out of funding. Can''t do anything at the moment.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_22_02A.ogg', '', 0, 0, '', 1, 0, 1, '[672]', NULL, 0, 0, '[]', 100),
