(18508, 'RogSettlersIdleWorkerNoGold_10', '[]', 'This may be a bit awkward, but we haven''t got any money.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_22_03C.ogg', '', 0, 0, '', 1, 0, 1, '[672]', NULL, 0, 0, '[]', 100),
(18509, 'RogSettlersIdleWorkerNoGold_11', '[]', 'Uh, this may be a bit awkward, but we haven''t got any money.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Rog/Rog/RogSettlers_22_03D.ogg', '', 0, 0, '', 1, 0, 1, '[672]', NULL, 0, 0, '[]', 100),
