(18654, 'DannigSettlersSmelting_15', '[]', 'Understood!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_03_04C.ogg', '', 0, 0, '', 1, 45000, 1, '[673]', NULL, 0, 0, '[]', 100),
(18655, 'DannigSettlersSmelting_16', '[]', 'Understood!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_03_04D.ogg', '', 0, 0, '', 1, 45000, 1, '[673]', NULL, 0, 0, '[]', 100),
(18656, 'DannigSettlersUnlockSmithing', '[]', 'Oh, it''ll be good to have a smithing hammer back in my hand.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18657, 'DannigSettlersUpgradeSmeltWood', '[]', 'Every journey begins with a humble first step.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18658, 'DannigSettlersUpgradeWorkerSpeedOne', '[]', 'We''re just getting into the swing of things!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18659, 'DannigSettlersUpgradeWorkerCountOne', '[]', 'The more the merrier!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18660, 'DannigSettlersUpgradeSmeltBismuth', '[]', 'Bismuth will be no match for our strength!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18661, 'DannigSettlersUpgradeWorkerCountTwo', '[]', 'It''s always best to outnumber the enemy, even if the enemy is inanimate!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18662, 'DannigSettlersUpgradeSmeltVirisium', '[]', 'Ah, Verisium, the most exquisite of metals.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18663, 'DannigSettlersUpgradeExtraOne', '[]', 'Ha hah!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18664, 'DannigSettlersUpgradeWorkerSpeedTwo', '[]', 'We''ll work tirelessly, day and night!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18665, 'DannigSettlersUpgradeWorkerCountThree', '[]', 'It''s a veritable army!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18666, 'DannigSettlersUpgradeExtraTwo', '[]', 'It''s the legendary forge of Kingsmarch, just as I envisioned!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18667, 'DannigSettlersUpgradeGeneric_Random', '[]', 'That will certainly help.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_01.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18668, 'DannigSettlersUpgradeGeneric_2', '[]', 'Starting to look like a real forge now!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_02.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18669, 'DannigSettlersUpgradeGeneric_3', '[]', 'This place is looking decently civilised!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_03.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18670, 'DannigSettlersUpgradeGeneric_4', '[]', 'Reminds me of my forge back home...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_04.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18671, 'DannigSettlersUpgradeGeneric_5', '[]', 'The work continues!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_05.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18672, 'DannigSettlersUpgradeGeneric_6', '[]', 'We''ll accomplish grand things with this.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_06.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18673, 'DannigSettlersUpgradeGeneric_7', '[]', 'It''s wondrous, how far we''ve come.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_07.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18674, 'DannigSettlersUpgradeGeneric_8', '[]', 'I couldn''t ask for a grander forge.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_15_08.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18675, 'DannigSettlersUnlockRunecrafting', '[]', 'We''ll forge wonders. Just you wait and see!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18676, 'DannigSettlersUnlockWarRune', '[]', 'Ah, the War rune. It represents conflict, often in surprising ways.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18677, 'DannigSettlersUnlockRiverRune', '[]', 'The River rune helps direct the flow of energies in the equipment...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_18.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18678, 'DannigSettlersUnlockBountyRune', '[]', 'The Bounty rune is one of the most cryptic to work with.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_19.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18679, 'DannigSettlersUnlockJourneyRune', '[]', 'If there''s a question, or a doubt, the Journey rune is critical. It''s a determinant.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_20.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18680, 'DannigSettlersUnlockMountainRune', '[]', 'Ah, we''re working with expert runes now. The Mountain can mean many things.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_21.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18681, 'DannigSettlersUnlockTimeRune', '[]', 'Onwards and upwards! Time has only one direction, and we can do naught but follow.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_22.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18682, 'DannigSettlersUnlockPowerRune', '[]', 'It''s been many years since I dared smith using the Power rune. It''s a symbol only for use by true artificers.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_23.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18683, 'DannigSettlersConvoToHimself_Random', '[]', 'Hmm... the runes are fickle here...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_24_01.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18684, 'DannigSettlersConvoToHimself_2', '[]', 'Yes... yes, that''s a plausible reason to speak to Isla...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_24_02.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18685, 'DannigSettlersConvoToHimself_3', '[]', 'I should have a drink with Tujen later.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_24_03.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18686, 'DannigSettlersConvoToHimself_4', '[]', 'I really must visit Te Onui again...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_24_04.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18687, 'DannigSettlersConvoToHimself_5', '[]', 'Damn useless virtue gem, doesn''t do anything...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_24_05.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18688, 'DannigSettlersConvoJohanOne', '[]', 'Everything is going forward as sworn.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_25_01.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18689, 'DannigSettlersConvoJohanTwo', '[]', '<i>{You} might not.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_25_02.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18690, 'DannigSettlersConvoTujenOne', '[]', 'Tujen, you''ve had too much to drink.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18691, 'DannigSettlersConvoTujenTwo', '[]', 'Just <i>{watch what you say.}', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_26_02.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18692, 'DannigSettlersConvoRog', '[]', 'Rog! How goes the dream?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_27_01.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18693, 'DannigSettlersConvoIsla', '[]', 'Oh beautiful, just. You. Wait!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_28_01.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
(18694, 'DannigSettlersOnApproach_Random', '[]', 'Hail!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Wild/DannigSettlers_Wild_29_01A.ogg', '', 0, 0, '', 1, 0, 1, '[673]', NULL, 0, 0, '[]', 100),
