(18724, 'DannigSettlersGlyphPartOne', '[]', '<i>{Hark! What grace have I to live in the time of such a great beauty!} Yes... ' || char(13) || '
' || char(13) || '
<i>{With crimson hair unlike any in Middengard}—no! No no no no no no no, too basic!' || char(13) || '
' || char(13) || '
The hair... the hair is nothing compared to the sparkle in her eyes, the spring in her step, the toss of her hair like a... like a stallion in the spring fields! Ohh... alright.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Glyph/DannigSettlers_Glyph_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[673,689]', NULL, 0, 0, '[]', 100),
(18725, 'DannigSettlersGlyphPartTwo', '[]', '<i>{Hark! What luck does this man have}—terrible! Hark? Hark!? Oh...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Glyph/DannigSettlers_Glyph_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[673,690]', NULL, 0, 0, '[]', 100),
(18726, 'DannigSettlersGlyphPartThree', '[]', '<i>{My dearest engineer, by the lamplight on your dirty face, by the stars}—D''oh, where are my words when it comes to this woman?! Ugh...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Dannig/Dannig_Glyph/DannigSettlers_Glyph_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[673,691]', NULL, 0, 0, '[]', 100),
(18727, 'TheBlackKnight_Emerge_Random', '[]', 'Only the worthy may pass!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Emerge_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18728, 'TheBlackKnight_Emerge_2', '[]', 'Only the worthy may pass!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Emerge_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18729, 'TheBlackKnight_Emerge_3', '[]', 'Prove yourself, warrior!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Emerge_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18730, 'TheBlackKnight_Emerge_4', '[]', 'Prove yourself, warrior!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Emerge_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18731, 'TheBlackKnight_Emerge_5', '[]', 'The runic arts do not reveal themselves to just anyone!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Emerge_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18732, 'TheBlackKnight_Emerge_6', '[]', 'The runic arts do not reveal themselves to just anyone!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Emerge_C_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18733, 'TheBlackKnight_Cleave_Random', '[]', 'Take this!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Cleave_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18734, 'TheBlackKnight_Cleave_2', '[]', 'Take this!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Cleave_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
