(18767, 'TheBlackKnight_Raise_Onto_Platform_Start_Random', '[]', 'Let''s test your resolve.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_Start_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18768, 'TheBlackKnight_Raise_Onto_Platform_Start_2', '[]', 'Let''s test your resolve.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_Start_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18769, 'TheBlackKnight_Raise_Onto_Platform_Start_3', '[]', 'Steel yourself, warrior!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_Start_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18770, 'TheBlackKnight_Raise_Onto_Platform_Start_4', '[]', 'Steel yourself, warrior!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_Start_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18771, 'TheBlackKnight_Raise_Onto_Platform_End_Random', '[]', 'Hah, I can truly fight at full strength against you!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_End_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18772, 'TheBlackKnight_Raise_Onto_Platform_End_2', '[]', 'Hah, I can truly fight at full strength against you!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_End_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18773, 'TheBlackKnight_Raise_Onto_Platform_End_3', '[]', 'I''m finally starting to enjoy myself!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_End_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18774, 'TheBlackKnight_Raise_Onto_Platform_End_4', '[]', 'I''m finally starting to enjoy myself!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Raise_Onto_Platform_End_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18775, 'TheBlackKnight_Minion_Phase_Start_Random', '[]', 'How do you fare against numbers?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_Start_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18776, 'TheBlackKnight_Minion_Phase_Start_2', '[]', 'The odds are against you!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_Start_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18777, 'TheBlackKnight_Minion_Phase_Start_3', '[]', 'The odds are against you!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_Start_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18778, 'TheBlackKnight_Minion_Phase_End_Random', '[]', 'Sometimes, one is worth one hundred!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_End_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18779, 'TheBlackKnight_Minion_Phase_End_2', '[]', 'Sometimes, one is worth one hundred!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_End_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18780, 'TheBlackKnight_Minion_Phase_End_3', '[]', 'Shine like the stars!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_End_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18781, 'TheBlackKnight_Minion_Phase_End_4', '[]', 'Shine like the stars!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Minion_Phase_End_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18782, 'TheBlackKnight_Death_Random', '[]', 'You fight well. Partake of this bounty!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Death_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18783, 'TheBlackKnight_Death_2', '[]', 'Satisfactory! Until next time, warrior!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Death_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18784, 'TheBlackKnight_Death_3', '[]', 'You have shown yourself to be worthy.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Death_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18785, 'TheBlackKnight_Glyph', '[]', 'You are ever being watched and judged, warrior. Do not dare disappoint.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/TheBlackKnight/TheBlackKnight_Glyph_01.ogg', '', 0, 0, '', 1, 0, 1, '[681]', NULL, 0, 0, '[]', 100),
(18786, 'FaustusSettlersIntroMetHeist', '[]', 'Why hello, stranger! <i>{Remember, Exile, plausible deniability.}' || char(13) || '
' || char(13) || '
I am Faustus, the Captain of the Fair Marylene. Consider <i>{me} your access to the wealth of Wraeclast. There''s not a single market I can''t reach, so I shall be your most esteemed facilitator. For a small fee, of course.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/Faustus_IntroKingsmarch.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18787, 'FaustusIntroUpdateNotMetHeist', '[]', 'Why hello, stranger!' || char(13) || '
' || char(13) || '
I am Faustus, the Captain of the Fair Marylene. Consider <i>{me} your access to the wealth of Wraeclast. There''s not a single market I can''t reach. You''ve got currency, they''ve got currency, and thus I shall be your most esteemed facilitator. For a small fee, of course.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_01B.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18788, 'FaustusSettlersIntroNotMetHeist', '[]', '''Hail,'' as these Kalguurans say. You''ve just met your most important ally in this strange new town. I am Faustus, the Captain of the Fair Marylene. Consider <i>{me} your access to the wealth of Wraeclast. There''s not a single market I can''t reach. You''ve got currency, they''ve got currency, and thus I shall be your most esteemed facilitator. For a small fee, of course.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_02.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18789, 'FaustusSettlersInviteToHideout', '[]', 'Are you inviting <i>{me} to work with <i>{you?} Hmm, I suppose I could keep worse company. Why not? Consider me... ''in!''', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_03.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18790, 'FaustusSettlersMeetInHideout', '[]', 'It''s not the most comfortable hideaway I''ve ever graced with my presence, but it''ll do. We''re in this to make money, after all. Nothing else matters.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_04.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18791, 'FaustusSettlersOnKingsmarch', '[]', 'Well, as I understand it, the Kalguurans we see here are not... hmm, how to put this delicately... not the, heh, finest wines in the cellar. Some of them are part of official guilds back on Middengard, but most are dissidents, criminals, and suspected rebels. You are an exile from Oriath, just as they are exiles from Kalguur. If not in name, then in circumstance.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_05.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18792, 'FaustusSettlersOnTheRing', '[]', 'Yes, it''s a beautiful ring, mmm! That''s real gold. Inherited it, believe it or not. ' || char(13) || '
' || char(13) || '
<i>{Are you mad? Get out of here with dangerous questions like that!}', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_06.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18793, 'FaustusSettlersOnOriath', '[]', 'With Oriath evacuated, I suppose Kingsmarch is the last bit of civilisation left on Wraeclast. Oh, I <i>{could} go live with the Karui like the rest, but that''s just not the way the winds are taking me.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_07.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18794, 'FaustusSettlersOnAdmiralty', '[]', 'With Darnaw dead, I''ve promoted myself to Admiral. Of course, the Oriathan Navy no longer officially exists... damn that Kirac!... so I''ll have to make my own. The <i>{Faustian Flotilla!} Admiral Faustus commands boldly from the helm! Oh, yes, it''s quite magnificent, I know.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_08.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18795, 'FaustusSettlersOnTheKing', '[]', 'You keep vigilant, Exile. Something''s afoot, and I feel a sinister shadow over my shoulder that only grows longer with each passing day.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_09.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18796, 'FaustusSettlersIntroHeist', '[]', 'Another green footpad? The turnover here... oh, it''s <i>{you!} I can''t say I''m surprised to see you turn up in a place like this.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus/FaustusSettlers_10.ogg', '', 0, 0, '', 1, 0, 1, '[677,679,456,678]', NULL, 0, 0, '[]', 100),
(18797, 'FaustusSettlersOrderFilled_Random', '[]', 'There''s a fair breeze on the wind today, wouldn''t you say, Exile?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_01A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18798, 'FaustusSettlersOrderFilled_2', '[]', 'There''s a fair breeze on the wind today, wouldn''t you say, Exile?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_01B.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18799, 'FaustusSettlersOrderFilled_3', '[]', 'There''s a fair breeze on the wind today, wouldn''t you say, Exile?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_01C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18800, 'FaustusSettlersOrderFilled_4', '[]', 'The dog is in the henhouse, as a commoner might say.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_02A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
