(18802, 'FaustusSettlersOrderFilled_6', '[]', 'The dog is in the henhouse, as a commoner might say.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_02C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18803, 'FaustusSettlersOrderFilled_7', '[]', 'You''ve got affairs you might want to tend.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_03A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
