(18805, 'FaustusSettlersOrderFilled_9', '[]', 'You''ve got affairs you might want to tend.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_03C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18806, 'FaustusSettlersOrderFilled_10', '[]', 'Order''s in. ''Twas a long journey, but the exchange went well enough.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_01_04A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
