(18888, 'FaustusSettlersWildTavernIdle_2', '[]', 'Oh, I spend far too much time here...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_01B.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18889, 'FaustusSettlersWildTavernIdle_3', '[]', 'I spend far too much time here...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_01C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18890, 'FaustusSettlersWildTavernIdle_4', '[]', 'The <i>{Fair Marylene} should be sailing high, not stuck here in port!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_02A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
