(18892, 'FaustusSettlersWildTavernIdle_6', '[]', 'The <i>{Fair Marylene} should be sailing high, not stuck here in port!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_02C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18893, 'FaustusSettlersWildTavernIdle_7', '[]', 'Need to find more of those damned exotic coins for the harbourmaster...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_03A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18894, 'FaustusSettlersWildTavernIdle_8', '[]', 'Need to find more of those damn exotic coins for the harbourmaster...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_03B.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18895, 'FaustusSettlersWildTavernIdle_9', '[]', 'Need to find more of those damned exotic coins for the harbourmaster...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_03C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18896, 'FaustusSettlersWildTavernIdle_10', '[]', 'Around here, far too much money passes through hands that aren''t mine...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_04A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18897, 'FaustusSettlersWildTavernIdle_11', '[]', 'Oh, around here, far too much money passes through hands that aren''t mine...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_04B.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18898, 'FaustusSettlersWildTavernIdle_12', '[]', 'Around here, far too much money passes through hands that aren''t mine...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_10_04C.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18899, 'FaustusSettlersConvoRaulfOne', '[]', 'Raulf, have a drink with me.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_11_01.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18900, 'FaustusSettlersConvoRaulfTwo', '[]', 'That''s... why that''s just insane.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_11_02.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18901, 'FaustusSettlersConvoJohanThree', '[]', 'No, my good chap, we absolutely do not.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_12_01.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18902, 'FaustusSettlersConvoJohanFour', '[]', 'I do not pay taxes to <i>{foreign powers.} I don''t even pay taxes to my own people.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_12_02.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18903, 'FaustusSettlersConvoJohanFive', '[]', 'Yes, the high sea... you can''t tax what you can''t find.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_12_03.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18904, 'FaustusSettlersConvoTujenOne', '[]', 'It pays to be observant.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_13_01.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18905, 'FaustusSettlersConvoIslaOne', '[]', 'You don''t have to... we''ve met here!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_14_01.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18906, 'FaustusSettlersConvoIslaTwo', '[]', 'That''s what meeting <i>{is!}', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_14_02.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
(18907, 'FaustusSettlersWildEnterTavern_Random', '[]', 'Well, look who it is!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Faustus/Faustus_Wild/FaustusSettlers_Wild_15_01A.ogg', '', 0, 0, '', 1, 45000, 1, '[677,679,678]', NULL, 0, 0, '[]', 100),
