(18928, 'HideoutTrialmasterChaosOrb4Mod_5', '[]', 'It was not to be.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_77D_02.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
