(19134, 'BanditArcherBoss_Emerge_Random', '[]', 'Kalguurans got another lapdog eh? No matter, you''ll die like the rest.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Emerge_01.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19135, 'BanditArcherBoss_Emerge_2', '[]', 'Why are you helping these colonising bastards? You in it for the money eh?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Emerge_02.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19136, 'BanditArcherBoss_Emerge_3', '[]', 'I won''t stop until every last one of these colonising bastards are dead!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Emerge_03.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19137, 'BanditArcherBoss_Emerge_4', '[]', 'Kalguurans got you under their thumb eh? None of these bastards are worth savin''!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Emerge_04.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19138, 'BanditArcherBoss_Emerge_5', '[]', 'I''d love to see the look on these Kalguuran faces once you''re dead!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Emerge_05.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
