(19188, 'BanditArcherBoss_Death_5', '[]', 'You ignorant bastard...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Death_05.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19189, 'BanditArcherBoss_Death_6', '[]', 'You ignorant bastard...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Death_06.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19190, 'BanditArcherBoss_Letter', '[]', 'No matter how far I run... no matter where I hide... Raulf''s hiring letters always find me...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/BanditArcherBoss/BanditArcherBoss_Letter.ogg', '', 0, 0, '', 1, 0, 1, '[680]', NULL, 0, 0, '[]', 100),
(19191, 'HideoutTrialmasterVaalOrbNone', '[]', 'So be it, as disappointing as it is.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_91_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19192, 'HideoutTrialmasterVaalOrbSkillGemLevelUp', '[]', 'You play the game well, Challenger. Enjoy the fruits of your luck, and your skill. We shall meet again.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_92_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19193, 'HideoutTrialmasterVaalOrbSkillGemQuality', '[]', 'The expected choice.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_89_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19194, 'HideoutTrialmasterVaalOrbVaalGem', '[]', 'Take your prize and go.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_73H_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19195, 'HideoutTrialmasterVaalOrbMapVaalTemple', '[]', 'A curious choice. Chaos disdains predictability.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_32C_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19196, 'HideoutTrialmasterVaalOrbMapImplicits', '[]', 'The safe choice.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_87_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19197, 'HideoutTrialmasterVaalOrbMap8ModRare', '[]', 'A prism of pain.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_33B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19198, 'HideoutTrialmasterVaalOrbMapReroll', '[]', 'Unpredictability adds that much more spice.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_29B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19199, 'HideoutTrialmasterVaalOrbContract8ModRare', '[]', 'A prism of pain.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_33B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19200, 'HideoutTrialmasterVaalOrbContractReroll', '[]', 'Unpredictability adds that much more spice.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_29B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19201, 'HideoutTrialmasterVaalOrbContractLevelChange', '[]', 'Perhaps you don''t understand the rules...', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_76D_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19202, 'HideoutTrialmasterVaalOrbJewelImplicits', '[]', 'Corruption starts in the blood.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_25A_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19203, 'HideoutTrialmasterVaalOrbJewel4ModRare', '[]', 'Rare is the breath of living air.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_26B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19204, 'HideoutTrialmasterVaalOrbJewelUnique', '[]', 'Take your prize and go.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_73H_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19205, 'HideoutTrialmasterVaalOrbFlask', '[]', 'No defence will be enough.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_16B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19206, 'HideoutTrialmasterVaalOrbBloodOfCorruption', '[]', 'Corruption starts in the blood.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_25A_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19207, 'HideoutTrialmasterVaalOrbMalachaiVision', '[]', 'Take your prize and go.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_73H_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19208, 'HideoutTrialmasterVaalOrbGlimpseOfChaosImplicits', '[]', 'Impressive, challenger.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_72A_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19209, 'HideoutTrialmasterVaalOrbGlimpseOfChaosUniqueReroll', '[]', 'Do you wish to keep your fortunes, or continue in pursuit of greater riches?', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_90_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19210, 'HideoutTrialmasterVaalOrbGlimpseOfChaosVaalMask', '[]', 'You never win, yet you keep trying...', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_62A_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19211, 'HideoutTrialmasterVaalOrbGlimpseOfChaosRemoveExplicit', '[]', 'It was not to be.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_77D_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19212, 'HideoutTrialmasterVaalOrbPurityAuraReroll', '[]', 'Not bad... for a mortal.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_72E_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19213, 'HideoutTrialmasterVaalOrbWhiteSockets', '[]', 'Random chance must dictate you win... occasionally.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_65C_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19214, 'HideoutTrialmasterVaalOrbImplicits', '[]', 'Thus, the vagaries of chance.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_70B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19215, 'HideoutTrialmasterVaalOrbFullReroll', '[]', 'Hahahahaha! Your luck is over, fool!', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_79D_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19216, 'HideoutTrialmasterChaosOrb4Mod', '[]', 'Chance no longer favours you.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_78E_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19217, 'HideoutTrialmasterChaosOrb6Mod', '[]', 'Take what is yours.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_09B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19218, 'HideoutTrialmasterChaosOrb3Tier1', '[]', 'How do you keep winning?!', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_73C_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19219, 'HideoutTrialmasterChaosOrb3Resistances', '[]', 'Ah, a classic! But far fairer now than in ancient times.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_36C_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19220, 'HideoutTrialmasterChaosOrb3Attributes', '[]', 'Take your prize and go.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_73H_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19221, 'HideoutTrialmasterChaosOrbOnMap', '[]', 'No rest for the wicked.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_27B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19222, 'HideoutTrialmasterChaosOrbFracturedItem', '[]', 'We might just be here all day.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_34B_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19223, 'HideoutTrialmasterChaosOrbJewel', '[]', 'You must be a glutton for punishment.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_323_28A_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19224, 'HideoutTrialmasterChaosOrbEldritch', '[]', 'Your grand visions fade to dust.', 'Audio/Dialogue/NPC/TrialmasterHideout/Tri_78C_01.ogg', '', 0, 0, '', 1, 0, 1, '[505]', NULL, 0, 0, '[]', 100),
(19225, 'RaulfIntroQuest', '[]', 'Oh, Johan and Dannig brought you on? Don''t worry, I''ll get you all the necessary paperwork shortly. I''m Raulf. The Meridian Free Traders, my guild, sent me here to assist in executing the charter. I connect labourers and specialists with those who have available jobs and capital. I''ve heard you may be making some decisions around here, so we should definitely do business.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_01.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19226, 'RaulfIntroNonQuest', '[]', 'Welcome to Kingsmarch! I''m something of a people person. That''s to say, I handle our talent pool! The Meridian Free Traders, my guild, sent me here to assist in executing the charter. I connect labourers and specialists with those who have available jobs and capital. I''ve heard you may be making some decisions around here, so we should definitely do business.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_02.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19227, 'RaulfIntroPostA4', '[]', 'Ah, so you''re the ''Exile'' I''ve heard so much about! Statistical deviations like you only come around every thousand years. They''re sure to sing songs about your exploits! My best opportunity for being remembered is to support a great hero. I''ll recruit others to the cause, as well. Once I explain the benefits of working in Kingsmarch, many people seem quite open to it! The key word seems to be ''gold.''', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_03.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19228, 'RaulfOfferRecruitment', '[]', 'You won''t get very far without any workers. We should go through the official papers together. There may be some nominal fees, of course, but I promise it''ll be worth it.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_04.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19229, 'RaulfOnBlackKnight', '[]', 'The legendary Black Knight is <i>{here?} On this forsaken continent? I grew up hearing tales of his mysterious appearances... he''s supposedly been around for centuries. Oh, I simply must reach out. Pulling off that kind of hire would certainly be a Bounty Rune on my family mantle! But what job is prestigious enough for the <i>{Black Knight?} Certainly not a miner, nor a farmer. Smelter? No. Disenchanter? Mm... no. I doubt he has engineering skills. Maybe a recruiter? Haha, wait, no, that''s <i>{my} job! He''ll have to guard our shipping lanes. Yes! No one would dare interfere with a Kingsmarch shipment if the Black Knight himself was out there on the high seas! Now, what would a figure like him want for payment? Hmm... everyone''s got a price...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_05.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19230, 'RaulfOnSasan', '[]', 'It''s horrible, how Sasan conducts himself. He could be getting far richer by working here, for us! I''ve reached out, but I''ve yet to hear back. I have to wonder if he''s reading any of my letters at all! If he did, he would understand my impeccable explanation of his best options. It''s simply absurd to remain a bandit, when there are so many opportunities here in Kingsmarch!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_06.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19231, 'RaulfOnValerius', '[]', 'Faustus insists I not hire Admiral Valerius. I don''t normally take advice from outside the recruiting business, but some of the stories he has told me chill me to the bone. So, I suppose this Valerius fellow will simply have to remain freelance. Pity for him.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_07.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19232, 'RaulfOnTavern', '[]', 'It''s not the most auspicious office I''ve worked in, but it certainly puts me face-to-face with the people of Kingsmarch. I consider it an opportunity!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_08.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19233, 'RaulfOnTheGuilds', '[]', 'Things operate rather loosely here, but back home, almost all official business is done through one or more guilds. Eh, for example, you cannot simply open up a shop and start selling goods. All designated locations for shops have a process that must be undertaken. There are a set number, and they are all currently licensed to major merchants. Every few years, a new license is created, and bid upon by interested parties. Those without the familial wealth to get ''in on the game,'' so to speak, may consider moving across the world to new lands, where regulations are not so strict. It''s the best argument in favour of a move to Kingsmarch. Bring your family, start a new life!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf/Raulf_09.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19234, 'RaulfWildOfferRecruitment', '[]', 'Here is our initial batch of potential recruits. Let me know who you''d like to hire.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19235, 'RaulfWildReactToRecruitment', '[]', 'Great! It''s that simple. Now, you can assign them to the role you''d like them to fill.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19236, 'RaulfWildShowRecruits_Random', '[]', 'Here''s a list of workers who are interested in a new life in Kingsmarch!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19237, 'RaulfWildShowRecruits_2', '[]', 'Here''s a list of workers who are already interested!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19238, 'RaulfWildShowRecruits_3', '[]', 'Here''s a list of workers who are already interested!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19239, 'RaulfWildUnlockRecruitment', '[]', 'I''ve got quite the list of workers already eager to sign up!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_04.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19240, 'RaulfWildRecruitUpgradeSmeltingAndFarming', '[]', 'With investments in my outreach, I''m certain we''ll start attracting new talent!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_05.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19241, 'RaulfWildRecruitUpgradeMaxVillagersOne', '[]', 'Housing is crucial to making Kingsmarch a desirable place to work and live.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19242, 'RaulfWildRecruitUpgradeNumberOne', '[]', 'Oh, how I do love paperwork!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19243, 'RaulfWildRecruitUpgradeDisenchanting', '[]', 'Maybe we can get some specialists in for Rog.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19244, 'RaulfWildRecruitUpgradeMaxVillagersTwo', '[]', 'At what point do I upgrade our designation from an ''outpost'' to a ''town''?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19245, 'RaulfWildRecruitUpgradeMapRunning', '[]', 'The boldest and the brightest would be fools to work anywhere else!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19246, 'RaulfWildRecruitUpgradeNumberTwo', '[]', 'Ah, more paperwork... not to worry! I can handle it.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19247, 'RaulfWildRecruitUpgradeMaxVillagersThree', '[]', 'Forget ''town,'' soon I can call this place a ''city''!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19248, 'RaulfWildRecruitUpgradeRank', '[]', 'We have enough investment here to attract the best of the best.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19249, 'RaulfWildRecruitUpgradeReducedReroll', '[]', 'We''ve got labourers and specialists practically banging our door down. We''re the talk of Wraeclast!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19250, 'RaulfWildOnRecruit_Random', '[]', 'I''ll get right on that paperwork!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_01A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19251, 'RaulfWildOnRecruit_2', '[]', 'I''ll get right on that paperwork!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_01B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19252, 'RaulfWildOnRecruit_3', '[]', 'They can start immediately, and I''ll get everything filled out later.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_02A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19253, 'RaulfWildOnRecruit_4', '[]', 'They can start immediately, and I''ll get everything filled out later.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_02B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19254, 'RaulfWildOnRecruit_5', '[]', 'Our team continues to grow!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_03A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19255, 'RaulfWildOnRecruit_6', '[]', 'Our team continues to grow!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_03B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19256, 'RaulfWildOnRecruit_7', '[]', 'Great choice!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_04A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19257, 'RaulfWildOnRecruit_8', '[]', 'Great choice!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_04B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19258, 'RaulfWildOnRecruit_9', '[]', 'One more for Kingsmarch!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_05A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19259, 'RaulfWildOnRecruit_10', '[]', 'One more for Kingsmarch!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_05B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19260, 'RaulfWildOnRecruit_11', '[]', 'Promising pick!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_06A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19261, 'RaulfWildOnRecruit_12', '[]', 'Promising pick!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_06B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19262, 'RaulfWildOnRecruit_13', '[]', 'Couldn''t have chosen better myself!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_07A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19263, 'RaulfWildOnRecruit_14', '[]', 'Couldn''t have chosen better myself!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_07B.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19264, 'RaulfWildOnRecruit_15', '[]', 'Oh, okay... yes, that''ll work!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_15_08A.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
