(19287, 'RaulfWildHirelingDies_Random', '[]', 'Death is unfortunate, but inevitable. I''ll handle the paperwork, and inform the families.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_18_01A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19288, 'RaulfWildHirelingDies_2', '[]', 'Death is unfortunate, but inevitable. I''ll handle the paperwork, and inform the families.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_18_01B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19289, 'RaulfWildHirelingDies_3', '[]', 'Please do try to keep the workers alive. We hold ourselves to certain standards here.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_18_02A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19290, 'RaulfWildHirelingDies_4', '[]', 'Please do try to keep the workers alive. We hold ourselves to certain standards here.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_18_02B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19291, 'RaulfWildHirelingDies_5', '[]', 'We''re going to need some replacements. There''s been... some misfortune.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_18_03A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19292, 'RaulfWildHirelingDies_6', '[]', 'We''re going to need some replacements. There''s been... some misfortune.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_18_03B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19293, 'RaulfWildConvoToHimself_Random', '[]', 'It''s all about <i>{marketing...}', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_01A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19294, 'RaulfWildConvoToHimself_2', '[]', 'It''s all about <i>{marketing...}', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_01B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19295, 'RaulfWildConvoToHimself_3', '[]', 'It''s all about <i>{marketing...}', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_01C.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19296, 'RaulfWildConvoToHimself_4', '[]', '''March with us in Kingsmarch!'' No no...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_02A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19297, 'RaulfWildConvoToHimself_5', '[]', '''March with us in Kingsmarch!'' Oh, no no...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_02B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19298, 'RaulfWildConvoToHimself_6', '[]', '''March with us in Kingsmarch!'' Oh, no. No...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_02C.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19299, 'RaulfWildConvoToHimself_7', '[]', '''At the edge of the world, where even the King might not hear you''... hmm, no, too risky...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_03A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19300, 'RaulfWildConvoToHimself_8', '[]', '''At the edge of the world, where even the King might not hear you''... hmm, no, too risky...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_03B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19301, 'RaulfWildConvoToHimself_9', '[]', '''Are you an exile without a home? Kingsmarch is waiting... Kingsmarch is open...'' no, no...', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_19_04A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19302, 'RaulfWildConvoFaustus', '[]', 'I''m afraid I don''t drink, Captain.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_20_01.ogg', '', 0, 0, '', 1, 45000, 1, '[670]', NULL, 0, 0, '[]', 100),
(19303, 'RaulfWildConvoJohanOne', '[]', 'This Wraeclast is a strange continent. Full of extremely talented people who despise authority and cooperation. They seek only their own enrichment.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_21_01.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19304, 'RaulfWildConvoJohanTwo', '[]', 'I suppose I have a higher-minded ideal.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_21_02.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19305, 'RaulfWildConvoTujen', '[]', 'How did you lose the leg?', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_22_01.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19306, 'RaulfWildConvoIsla', '[]', 'It''s RA-ULF!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_23_01.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19307, 'RaulfWildOnApproach_Random', '[]', 'Come in!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_24_01A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19308, 'RaulfWildOnApproach_2', '[]', 'Ahh, come in!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_24_01B.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19309, 'RaulfWildOnApproach_3', '[]', 'Come in!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_24_01C.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19310, 'RaulfWildOnApproach_4', '[]', 'Come in!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_24_01D.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
(19311, 'RaulfWildOnApproach_5', '[]', 'Yes, yes, enter!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Raulf/Raulf_Wild/Raulf_Wild_24_02A.ogg', '', 0, 0, '', 1, 0, 1, '[670]', NULL, 0, 0, '[]', 100),
