(19449, 'SonjaConvoWithTujenOne', '[]', 'With farm work, there are no days off.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Sonja/Sonja_Wild/Sonja_Wild_23_01.ogg', '', 0, 0, '', 1, 0, 1, '[671]', NULL, 0, 0, '[]', 100),
(19450, 'SonjaConvoWithTujenTwo', '[]', 'Heheh... buy me a drink, and I''ll show you.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Sonja/Sonja_Wild/Sonja_Wild_23_02.ogg', '', 0, 0, '', 1, 0, 1, '[671]', NULL, 0, 0, '[]', 100),
(19451, 'SonjaConvoWithIslaOne', '[]', 'That ramshackle auto-planter of yours just scratched the dirt around, Isla. Didn''t do a lick of good.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Sonja/Sonja_Wild/Sonja_Wild_24_01.ogg', '', 0, 0, '', 1, 0, 1, '[671]', NULL, 0, 0, '[]', 100),
