(19529, 'JohanWildWithdrawGold_Random', '[]', 'I''ll handle the paperwork for that.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_01A.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
