(19531, 'JohanWildWithdrawGold_3', '[]', 'I''ll handle the paperwork for that.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_01C.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19532, 'JohanWildWithdrawGold_4', '[]', 'Handle it wisely.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_02A.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
