(19534, 'JohanWildWithdrawGold_6', '[]', 'Handle it wisely.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_02C.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19535, 'JohanWildWithdrawGold_7', '[]', '''Don''t spend it all in one place,'' as they say.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_03A.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19536, 'JohanWildWithdrawGold_8', '[]', '''Don''t spend it all in one place,'' as they say.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_03B.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19537, 'JohanWildWithdrawGold_9', '[]', '''Don''t spend it all in one place,'' as they say.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_05_03C.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19538, 'JohanWildInfrastructureDisenchanting', '[]', 'We now have the means to construct a building for disenchanting.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19539, 'JohanWildInfrastructureMining', '[]', 'We are now in a position to build mining infrastructure.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19540, 'JohanWildInfrastructureFarming', '[]', 'We can now set up farming capabilities.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_08.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19541, 'JohanWildInfrastructureSmelting', '[]', 'We can now build the proper structures for smelting.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_09.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19542, 'JohanWildInfrastructureMapRunning', '[]', 'It is now possible for us to consider excursions into the Atlas.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_10.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19543, 'JohanWildInfrastructureGuarding', '[]', 'We can now invest in naval protection.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_11.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19544, 'JohanWildUpgradeT1', '[]', 'Mining infrastructure will be crucial to our expansion', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_12.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19545, 'JohanWildUpgradeT2', '[]', 'If you can keep Tujen off the drink, he''s a highly capable harbourmaster.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_13.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19546, 'JohanWildUpgradeT3', '[]', 'Basic industry will certainly bolster our growth.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_14.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19547, 'JohanWildUpgradeT4', '[]', 'The finer arts are an important step forward.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_15.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19548, 'JohanWildUpgradeT5', '[]', 'I know Rog''s been interested in running something for quite some time.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_16.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19549, 'JohanWildUpgradeT6', '[]', 'I don''t know how much I trust this ''Atlas'', but the decision is yours.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_17.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19550, 'JohanWildKidnapped_Random', '[]', 'There''s been a development. Our scouts in the Atlas have been taken! We must do something immediately.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_01A.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19551, 'JohanWildKidnapped_2', '[]', 'There''s been a development. Our scouts in the Atlas have been taken! We must do something immediately.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_01B.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19552, 'JohanWildKidnapped_3', '[]', 'There''s been a development. Our scouts in the Atlas have been taken! We must do something immediately.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_01C.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19553, 'JohanWildKidnapped_4', '[]', 'Our men in the Atlas have been accosted! We must rescue them.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_02A.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19554, 'JohanWildKidnapped_5', '[]', 'Our men in the Atlas have been accosted! We must rescue them.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_02B.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19555, 'JohanWildKidnapped_6', '[]', 'Our men in the Atlas have been accosted! We must rescue them.', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_02C.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19556, 'JohanWildKidnapped_7', '[]', 'Our Atlas scouts have been kidnapped! Action must be taken!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_03A.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
(19557, 'JohanWildKidnapped_8', '[]', 'Our Atlas scouts have been kidnapped! Action must be taken!', 'Audio/Dialogue/Leagues/SettlersOfKalguur/Johan/Johan_Wild/Johan_Wild_18_03B.ogg', '', 0, 0, '', 1, 0, 1, '[667]', NULL, 0, 0, '[]', 100),
