(19974, 'MaataCraftingBench_CraftRemoveMod9', '[]', 'Such is life.', 'Audio/Dialogue/NPC/MaataMTX/MaataMTX_RemoveMod_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[704]', NULL, 0, 0, '[]', 100),
(19975, 'FirstMateMTX_Chatter_Random', '[]', 'What a life, ey? Out at sea... ahh. Beautiful.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19976, 'FirstMateMTX_Chatter_2', '[]', 'What a life, ey? Out at sea... ahh. Beautiful.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19977, 'FirstMateMTX_Chatter_3', '[]', 'What a life, ey? Out at sea... ahh. Beautiful.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19978, 'FirstMateMTX_Chatter_4', '[]', 'Remember: No bananas onboard!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19979, 'FirstMateMTX_Chatter_5', '[]', 'It''s the sailors life for me!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19980, 'FirstMateMTX_Chatter_6', '[]', 'Ahh, it''s the sailors life for me!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19981, 'FirstMateMTX_Chatter_7', '[]', 'It''s the sailors life for me!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19982, 'FirstMateMTX_Chatter_8', '[]', 'Ahh... I love the smell of salt on the air.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19983, 'FirstMateMTX_Chatter_9', '[]', 'Ahh... I love the smell of salt on the air.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19984, 'FirstMateMTX_Chatter_10', '[]', 'There are worse places to be exiled to, I reckon!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19985, 'FirstMateMTX_Chatter_11', '[]', 'There are worse places to be exiled to, I reckon!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19986, 'FirstMateMTX_Chatter_12', '[]', 'There are worse places to be exiled to, I reckon!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_05_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19987, 'FirstMateMTX_Chatter_13', '[]', 'You don''t get seasick, do ya?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19988, 'FirstMateMTX_Chatter_14', '[]', 'You don''t get seasick, do ya?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19989, 'FirstMateMTX_Chatter_15', '[]', 'Just gimme a nudge if I get suckered in by the ol'' siren song.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19990, 'FirstMateMTX_Chatter_16', '[]', 'Just gimme a nudge if I get suckered in by the ol'' siren song.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19991, 'FirstMateMTX_Chatter_17', '[]', 'You hungry? The smell of the sea makes me peckish. And I''m always at sea.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19992, 'FirstMateMTX_Chatter_18', '[]', 'You hungry? The smell of the sea makes me peckish. ', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19993, 'FirstMateMTX_Chatter_19', '[]', 'Hear that? Me neither! Won''t get silence like that on land.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_09_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19994, 'FirstMateMTX_Chatter_20', '[]', 'Hear that? Me neither! Won''t get silence like that on land.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_09_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19995, 'FirstMateMTX_Chatter_21', '[]', 'Me old lady don''t like the ocean! Breaks me heart, to tell you the truth.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_10_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19996, 'FirstMateMTX_Chatter_22', '[]', 'Me old lady don''t like the ocean! Breaks me heart, to tell you the truth.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_10_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19997, 'FirstMateMTX_Chatter_23', '[]', 'You smell that? No? Eh, good.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_11_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19998, 'FirstMateMTX_Chatter_24', '[]', 'You''re not much of a talking type, are ya.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_12_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(19999, 'FirstMateMTX_Chatter_25', '[]', 'You''re not much of a talking type, are ya.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_12_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100);
