(20000, 'FirstMateMTX_Chatter_26', '[]', 'You''re not much of a talking type, are ya.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_12_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20001, 'FirstMateMTX_Chatter_27', '[]', 'Hope you can swim! No reason. Just in case.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_13_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20002, 'FirstMateMTX_Chatter_28', '[]', 'Egh! Sorry ''bout that. Dozed off for a second there.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_14_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20003, 'FirstMateMTX_Chatter_29', '[]', 'Egh! Sorry ''bout that. Dozed off for a second there.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_14_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20004, 'FirstMateMTX_Chatter_30', '[]', 'I ever tell you about the time I saw a Golden Rhoa?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_15_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20005, 'FirstMateMTX_Chatter_31', '[]', 'I ever tell you about the time I saw a Golden Rhoa?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_15_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20006, 'FirstMateMTX_Chatter_32', '[]', 'I ever tell you about the time I saw a Golden Rhoa?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_15_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20007, 'FirstMateMTX_Chatter_33', '[]', 'Bit chilly out here!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_16_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20008, 'FirstMateMTX_Chatter_34', '[]', 'Ooh... bit chilly out here.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_16_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20009, 'FirstMateMTX_Chatter_35', '[]', 'So, ahh... come here often?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_17_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20010, 'FirstMateMTX_Chatter_36', '[]', 'So, ahh... come here often?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_17_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20011, 'FirstMateMTX_Chatter_37', '[]', 'Do do doo, do do do... Just sittin'' in a boat, with someone else...', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_18_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20012, 'FirstMateMTX_Chatter_38', '[]', 'Bit awkward you just starin'' at me like that.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_19_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20013, 'FirstMateMTX_Chatter_39', '[]', 'Bit awkward you just starin'' at me like that.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_19_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20014, 'FirstMateMTX_Chatter_40', '[]', '', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Humming_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20015, 'FirstMateMTX_Chatter_41', '[]', '', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Humming_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20016, 'FirstMateMTX_Chatter_LowChance_Random', '[]', 'Some communities really love boats.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Boats_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20017, 'FirstMateMTX_Chatter_LowChance_2', '[]', 'Some communities really love boats.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Boats_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20018, 'FirstMateMTX_Chatter_LowChance_3', '[]', 'How about a spot of fishin''?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Fishing_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20019, 'FirstMateMTX_Chatter_LowChance_4', '[]', 'How about a spot of fishin''?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Fishing_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20020, 'FirstMateMTX_Chatter_LowChance_5', '[]', 'How about a spot of fishin''?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Fishing_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20021, 'FirstMateMTX_Chatter_LowChance_6', '[]', 'Wish I brought me rod!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Fishing_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20022, 'FirstMateMTX_Chatter_LowChance_7', '[]', 'Wish I brought me rod!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Fishing_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20023, 'FirstMateMTX_Chatter_LowChance_8', '[]', 'Wish I brought me rod!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Chatter_Fishing_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20024, 'FirstMateMTX_Chatter_LowChance_9', '[]', 'Well, ho ho ho and rattle my toe, a Rhoa bit me on my nose. So here and there, everywhere that I go, I seem to be the butt of the joke! People laugh and people point, cause me nostril looks well out of joint! So to hell with the land, to hell with the beasts, I''d rather be sleepin'' out at sea!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_SeaShanty_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20025, 'FirstMateMTX_Goodbye_Random', '[]', 'See ya!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20026, 'FirstMateMTX_Goodbye_2', '[]', 'See ya!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20027, 'FirstMateMTX_Goodbye_3', '[]', 'See ya!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20028, 'FirstMateMTX_Goodbye_4', '[]', 'See ya!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_01_04.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20029, 'FirstMateMTX_Goodbye_5', '[]', 'Til next time!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20030, 'FirstMateMTX_Goodbye_6', '[]', 'Til next time!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20031, 'FirstMateMTX_Goodbye_7', '[]', 'Til next time!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20032, 'FirstMateMTX_Goodbye_8', '[]', 'Til next time!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_02_04.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20033, 'FirstMateMTX_Goodbye_9', '[]', 'What? No tip?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20034, 'FirstMateMTX_Goodbye_10', '[]', 'What? No tip?', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20035, 'FirstMateMTX_Goodbye_11', '[]', 'Thank ye for your patronage.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20036, 'FirstMateMTX_Goodbye_12', '[]', 'Thank ye for your patronage.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20037, 'FirstMateMTX_Goodbye_13', '[]', 'Thank ye for your patronage.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20038, 'FirstMateMTX_Goodbye_14', '[]', 'I''ll be here.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20039, 'FirstMateMTX_Goodbye_15', '[]', 'I''ll be here.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20040, 'FirstMateMTX_Goodbye_16', '[]', 'I''ll be here.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_05_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20041, 'FirstMateMTX_Goodbye_17', '[]', 'Come back soon!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20042, 'FirstMateMTX_Goodbye_18', '[]', 'Come back soon!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20043, 'FirstMateMTX_Goodbye_19', '[]', 'Come back soon!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_06_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20044, 'FirstMateMTX_Goodbye_20', '[]', 'A pleasure.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20045, 'FirstMateMTX_Goodbye_21', '[]', 'A pleasure.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20046, 'FirstMateMTX_Goodbye_22', '[]', 'A pleasure.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_07_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20047, 'FirstMateMTX_Goodbye_23', '[]', 'Bring me back something nice!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20048, 'FirstMateMTX_Goodbye_24', '[]', 'Bring me back something nice!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20049, 'FirstMateMTX_Goodbye_25', '[]', 'Bring me back something nice!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_08_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20050, 'FirstMateMTX_Goodbye_26', '[]', 'And don''t come back! Heh, just kiddin''. You''re welcome any time.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_09_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20051, 'FirstMateMTX_Goodbye_27', '[]', 'And don''t come back! Just kiddin''. You''re welcome any time.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_09_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20052, 'FirstMateMTX_Goodbye_28', '[]', 'And don''t come back! Just kiddin''. Please come back.', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Goodbye_09_03.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20053, 'FirstMateMTX_Greeting_Random', '[]', 'Keep your arms, legs, hooks and pegs inside the vessel at all times!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Greeting_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20054, 'FirstMateMTX_Greeting_2', '[]', 'Keep your arms, legs, hooks and pegs inside the vessel at all times!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Greeting_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20055, 'FirstMateMTX_Greeting_3', '[]', 'Got your sea legs? Then off we go!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Greeting_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
(20056, 'FirstMateMTX_Greeting_4', '[]', 'Got your sea legs? Then off we go!', 'Audio/Dialogue/NPC/FirstMateMTX/FirstMateMTX_Greeting_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[705]', NULL, 0, 0, '[]', 100),
