(21707, 'Merc_Ranger1_TakeItemRare_8', '[]', 'Bastard. Didn''t think I''d ever part with this.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TakeItemRare_8.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[6]', 100),
(21708, 'Merc_Ranger1_TakeItemRare_9', '[]', 'Bastard. Didn''t think I''d ever part with this.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TakeItemRare_9.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[6]', 100),
(21709, 'Merc_Ranger1_TutFirstApproach', '[]', 'Oi - Exile! Over here. Let''s have a word, eh?', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutFirstApproach.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21710, 'Merc_Ranger1_Tut_FightCallout', '[]', 'Gonna take more than that! Come on!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutFightCallout.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21711, 'Merc_Ranger1_Tut_IntroBoxVersion', '[]', 'Surprised to see a Trarthan in Wraeclast? It''s simple. Once the Bardiyans formed their so-called Merchant Council, Trarthus got... boring. Rules. Laws. Bloody taxes, if you can believe it.' || char(13) || '
' || char(13) || '
Folk like me didn''t fit their new vision. Some of us got exiled. Some left before the noose tightened.' || char(13) || '
' || char(13) || '
Now we''re here, plying our trade in a place that still respects strength.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutIntroBoxVersions.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21712, 'Merc_Ranger1_Tut_IntroShortAlt', '[]', 'Surprised to see a Trarthan in Wraeclast? It''s simple, really. Due to... <i>{political reasons}... work''s dried up. So, here we are. ', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutIntroShortAlt.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21713, 'Merc_Ranger1_Tut_LayingOutOptions', '[]', 'Beat me, and the choice is yours: take my gear, recruit me, or send me packing. That''s the Trarthan Code.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutLayingOutOptions.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21714, 'Merc_Ranger1_Tut_PlayerLosesFight', '[]', 'Huh. Seems Wraeclast ain''t all it''s cracked up to be. ', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutPlayerLosesFight.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21715, 'Merc_Ranger1_Tut_StartFightBanish', '[]', 'Want me to piss off? Go on, then. Make me. ', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutStartFightBanish.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21716, 'Merc_Ranger1_Tut_StartFightGeneric', '[]', 'Come on. Let''s see what passes for strength in Wraeclast.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutStartFightGeneric.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21717, 'Merc_Ranger1_Tut_StartFightHire', '[]', 'Want me to work for you, first you''ve gotta prove yourself.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutStartFightHire.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21718, 'Merc_Ranger1_Tut_StartFightItem', '[]', 'You want it? Then earn it!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutStartFightItem.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21719, 'Merc_Ranger1_Tut_WInFightBanish', '[]', 'Alright, alright! One hiding''s enough. Won''t be stickin'' around for a second.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutWInFightBanish.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21720, 'Merc_Ranger1_Tut_WinFightHired', '[]', 'If there''s one thing us Trarthans respect, it''s strength - and you showed yours. You lead, I''ll follow.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutWinFightHired.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21721, 'Merc_Ranger1_Tut_WinFightTakeItem', '[]', 'That''s how it''s done. It''s yours now.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_TutWinFightTakeItem.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[]', 100),
(21722, 'Merc_Ranger1_Ultimate_Random', '[]', 'Right between the eyes!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_Random.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21723, 'Merc_Ranger1_Ultimate_2', '[]', 'Right between the eyes!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_2.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21724, 'Merc_Ranger1_Ultimate_3', '[]', 'Right between the eyes!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_3.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21725, 'Merc_Ranger1_Ultimate_4', '[]', 'Lining up the shot.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_4.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21726, 'Merc_Ranger1_Ultimate_5', '[]', 'Lining up the shot.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_5.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21727, 'Merc_Ranger1_Ultimate_6', '[]', 'Lining up the shot.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_6.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21728, 'Merc_Ranger1_Ultimate_7', '[]', 'You''re finished!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_7.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21729, 'Merc_Ranger1_Ultimate_8', '[]', 'You''re finished!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_8.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21730, 'Merc_Ranger1_Ultimate_9', '[]', 'You''re finished!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_9.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21731, 'Merc_Ranger1_Ultimate_10', '[]', 'Last thing you''ll ever see!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_10.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21732, 'Merc_Ranger1_Ultimate_11', '[]', 'Last thing you''ll ever see!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_11.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21733, 'Merc_Ranger1_Ultimate_12', '[]', 'Last thing you''ll ever see!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_12.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21734, 'Merc_Ranger1_Ultimate_13', '[]', 'One shot. One kill.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_13.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21735, 'Merc_Ranger1_Ultimate_14', '[]', 'One shot. One kill.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_14.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21736, 'Merc_Ranger1_Ultimate_15', '[]', 'One shot. One kill.', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_15.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21737, 'Merc_Ranger1_Ultimate_16', '[]', 'Marked!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_16.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
(21738, 'Merc_Ranger1_Ultimate_17', '[]', 'Marked!', 'Audio/Dialogue/Leagues/Mercenaries/Ranger1/Merc_R1_Ultimate_17.ogg', '', 0, 0, '', 1, 40000, 1, '[730]', NULL, 0, 0, '[3]', 100),
