(21740, 'Merc_Neon_FirstApproach_Random', '[]', 'Well, well... what have we got here?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Approach_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21741, 'Merc_Neon_FirstApproach_2', '[]', '''Scuse me - who are you?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Approach_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21742, 'Merc_Neon_FirstApproach_3', '[]', 'Have we met before?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Approach_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21743, 'Merc_Neon_BattleStart_Random', '[]', 'Let the ruckus begin!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_BattleStart.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21744, 'Merc_Neon_ChangeGear_Random', '[]', 'Uh... sure.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_ChangeGear_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[7]', 100),
(21745, 'Merc_Neon_ChangeGear_2', '[]', 'Uh... sure.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_ChangeGear_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[7]', 100),
(21746, 'Merc_Neon_ChangeGear_3', '[]', 'Hey - I liked that.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_ChangeGear_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[7]', 100),
(21747, 'Merc_Neon_ChangeGear_4', '[]', 'Hey, what the heck? I liked that.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_ChangeGear_04.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[7]', 100),
(21748, 'Merc_Neon_ChangeGear_5', '[]', 'Well, you''re the boss... for now.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_ChangeGear_05.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[7]', 100),
(21749, 'Merc_Neon_ChangeGear_6', '[]', 'You''re the boss... for now.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_ChangeGear_06.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[7]', 100),
(21750, 'Merc_Neon_Banish_Random', '[]', 'Ugh, that''s fine. I got loads to do.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedBanish_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21751, 'Merc_Neon_Banish_2', '[]', 'Pity... but whatever.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedBanish_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21752, 'Merc_Neon_TakeItemGeneric_Random', '[]', 'Eh, I got loads of those at home. Whatever.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTake_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21753, 'Merc_Neon_TakeItemGeneric_2', '[]', 'You want <i>{that} thing? Alright, then.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTake_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21754, 'Merc_Neon_TakeItemGeneric_3', '[]', 'To be honest, I couldn''t care less about that.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTake_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21755, 'Merc_Neon_TakeItemRare_Random', '[]', 'Really? Not that one!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTakeRare_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21756, 'Merc_Neon_TakeItemRare_2', '[]', 'You lucky bugger!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTakeRare_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21757, 'Merc_Neon_TakeItemRare_3', '[]', 'Uh, that''s a bannable offence.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTakeRare_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21758, 'Merc_Neon_JoinParty_Random', '[]', 'Keep this one to yourself.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatJoin_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21759, 'Merc_Neon_JoinParty_2', '[]', 'Alright, alright, if you insist.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatJoin_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21760, 'Merc_Neon_Dismiss_Random', '[]', 'Churr.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Dismiss.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21761, 'Merc_Neon_CheckGear_Random', '[]', 'Whaddaya reckon?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectFriend_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21762, 'Merc_Neon_CheckGear_2', '[]', 'Whaddaya reckon?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectFriend_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21763, 'Merc_Neon_CheckGear_3', '[]', 'So, what''ll it be?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectFriend_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21764, 'Merc_Neon_CheckGear_4', '[]', 'So, what''ll it be?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectFriend_04.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21765, 'Merc_Neon_CheckGear_5', '[]', 'Go on, then.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectFriend_05.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21766, 'Merc_Neon_CheckGear_6', '[]', 'Go on, then.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectFriend_06.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21767, 'Merc_Neon_CheckGear_7', '[]', 'Yes, it is I - the Ruckus-Maker.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectNotable_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21768, 'Merc_Neon_CheckGear_8', '[]', 'Behold! Me!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectNotable_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21769, 'Merc_Neon_InspectNotable_Random', '[]', 'Yes, it is I - the Ruckus-Maker.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectNotable_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21770, 'Merc_Neon_InspectNotable_2', '[]', 'Behold! Me!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_InspectNotable_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[4]', 100),
(21771, 'Merc_Neon_PlayerKill_Random', '[]', 'Oh, you died. Just deal with it.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillPlayer_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21772, 'Merc_Neon_PlayerKill_2', '[]', 'Ideally, you''d get good.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillPlayer_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21773, 'Merc_Neon_PlayerKill_3', '[]', 'It''s definitely a build issue.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillPlayer_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21774, 'Merc_Neon_KillUnique_Random', '[]', 'Oh! Rip.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillUnique_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21775, 'Merc_Neon_KillUnique_2', '[]', 'Rip.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillUnique_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21776, 'Merc_Neon_KillUnique_3', '[]', 'Yep. Dead as.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillUnique_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21777, 'Merc_Neon_KillUnique_4', '[]', 'Aw, love to see it!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillUnique_04.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[6]', 100),
(21778, 'Merc_Neon_Kurai', '[]', 'Kurai knows the weight of responsibility. So many moving parts... So many deadlines... Such a ruckus...', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Kurai.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21779, 'Merc_Neon_Retreat_Random', '[]', 'Good thing <i>{I''m} not in hardcore.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_LowHealth_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21780, 'Merc_Neon_Retreat_2', '[]', 'I''ll be back... uh, I just gotta go nerf something.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_LowHealth_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21781, 'Merc_Neon_PlayerDies_Random', '[]', 'Really, bruh? Get good.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_PlayerDies_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21782, 'Merc_Neon_PlayerDies_2', '[]', 'I guess the loot is mine, then.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_PlayerDies_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21783, 'Merc_Neon_PlayerDies_3', '[]', 'I guess this was just a little bit difficult for you.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_PlayerDies_06.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21784, 'Merc_Neon_PlayerDies_4', '[]', 'Oh, you died. Just deal with it.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillPlayer_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21785, 'Merc_Neon_PlayerDies_5', '[]', 'Ideally, you''d get good.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillPlayer_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21786, 'Merc_Neon_PlayerDies_6', '[]', 'It''s definitely a build issue.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_KillPlayer_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21787, 'Merc_Neon_PlayerDies_7', '[]', 'Ah, that''s a bannable offence.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_DefeatedTakeRare_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[11]', 100),
(21788, 'Merc_Neon_Rehire_Random', '[]', 'That''s smart - I can feel a divine''s about to drop.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Rehire_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[8]', 100),
(21789, 'Merc_Neon_Rehire_2', '[]', 'Alright, fine then - let''s go again.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Rehire_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[8]', 100),
(21790, 'Merc_Neon_Rehire_3', '[]', 'You <i>{probably} won''t regret it.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Rehire_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[8]', 100),
(21791, 'Merc_Neon_SetToReserve_Random', '[]', 'You do know who I am, right?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Reserve_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[9]', 100),
(21792, 'Merc_Neon_SetToReserve_2', '[]', 'What the heck?', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Reserve_02.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[9]', 100),
(21793, 'Merc_Neon_SetToReserve_3', '[]', 'That''s... just stupid. But fine.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Reserve_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[9]', 100),
(21794, 'Merc_Neon_RogueHarbour', '[]', 'Thankfully, there''s not too many people here.', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_RogueHarbour.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[]', 100),
(21795, 'Merc_Neon_Ultimate_Random', '[]', 'Ruckus!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Ultimate_01.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[3]', 100),
