(21797, 'Merc_Neon_Ultimate_3', '[]', 'Auras for everyone!', 'Audio/Dialogue/Leagues/Mercenaries/Neon/Merc_Neon_Ultimate_03.ogg', '', 0, 0, '', 1, 40000, 1, '[728]', NULL, 0, 0, '[3]', 100),
