(24062, 'Ailith_FlameGlyphOne', '[]', 'Ailith, you must...', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24063, 'Ailith_FlameGlyphTwo', '[]', '... remember! You just...', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24064, 'Ailith_FlameGlyphThree', '[]', '... woke from a dream...', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24065, 'Ailith_FlameGlyphFour', '[]', '... didn''t you? It''s all a lie!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_04.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24066, 'Ailith_FlameGlyphFive', '[]', '...The Dreamer has betrayed us...', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_05.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24067, 'Ailith_FlameGlyphSix', '[]', '... Don''t go back...', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_06.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24068, 'Ailith_FlameGlyphSeven', '[]', '... to the Monastery. Run while you still can!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_01_07.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24069, 'Ailith_TruthGlyph', '[]', 'Time is a sacred gift. Each moment must be spent in disciplined pursuit of perfection.' || char(13) || '
<br/>' || char(13) || '
<br/>Suffering is a sacred gift. Hunger, thirst, and pain are all signposts on the road.' || char(13) || '
<br/>' || char(13) || '
<br/>Flesh is a sacred gift. It grows and adapts, a forge unlike any other.' || char(13) || '
<br/>' || char(13) || '
<br/>Truth lies beyond the wall of sleep. All else is an illusion.' || char(13) || '
', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Glyph/Ailith_Glyph_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24070, 'Ailith_Wild_CalloutCoast', '[]', 'Come here, quickly!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24071, 'Ailith_Wild_GraftPrompt', '[]', 'Go on. Meld it to your flesh.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24072, 'Ailith_Wild_GraftPromptTwo', '[]', 'We''re running out of time!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24073, 'Ailith_Wild_AfterGrafting', '[]', 'Ah, your body has survived my gift! Now, test your new power. Wield the flame against that wall.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_04_v2.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24074, 'Ailith_Wild_DestroyWallImpatient_Random', '[]', 'Use the Flame to destroy the wall.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24075, 'Ailith_Wild_DestroyWallImpatient_2', '[]', 'Do not be afraid. Use the Flame.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24076, 'Ailith_Wild_WallDestroyed', '[]', 'By the Dreamer! You did it!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_06.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24077, 'Ailith_Wild_CalloutFortFirstTime', '[]', 'We need to break this wall and get inside! Use the Flame!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_07.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24078, 'Ailith_Wild_TutorialFortPortInOne', '[]', 'You did it! You exposed the centre!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_31.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24079, 'Ailith_Wild_TutorialFortPortInTwo', '[]', 'I can destroy this rift, I just need time! Defend me while I focus my will!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_32.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24080, 'Ailith_Wild_FortFirstTimePortalIn_Random', '[]', 'Defend me while I close the breach!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_08_01.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24081, 'Ailith_Wild_FortFirstTimePortalIn_2', '[]', 'Guard me! I''ll close this breach!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_08_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24082, 'Ailith_Wild_FortFirstTimePortalIn_3', '[]', 'Keep them back while I handle this!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_08_03.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
