(24226, 'Ailith_Wild_EnterBackRoom', '[]', 'They''re all... me...', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Cine/Ailith_Wild_25.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775,776]', NULL, 0, 0, '[]', 100),
(24227, 'Ailith_Wild_ChayulaConvoOne', '[]', 'What... what is this?!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Cine/Ailith_Wild_26_01.ogg', '', 0, 0, '', 1, 0, 1, '[776]', NULL, 0, 0, '[]', 100),
(24228, 'Ailith_Wild_ChayulaConvoTwo', '[]', 'I am a fool... you''ve betrayed me! I''m nothing but a Hiveborn abomination, a mindless pawn, like <i>{them!}', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Cine/Ailith_Wild_27.ogg', '', 0, 0, '', 1, 0, 1, '[776]', NULL, 0, 0, '[]', 100),
(24229, 'Ailith_Wild_ChayulaConvoThree', '[]', 'You had no right!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Cine/Ailith_Wild_28.ogg', '', 0, 0, '', 1, 0, 1, '[776]', NULL, 0, 0, '[]', 100),
(24230, 'Ailith_Wild_ChayulaConvoFour', '[]', 'Not anymore. I reject you. I reject this perverse existence!', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Cine/Ailith_Wild_29.ogg', '', 0, 0, '', 1, 0, 1, '[776]', NULL, 0, 0, '[]', 100),
(24231, 'Ailith_Wild_ChayulaConvoFive', '[]', 'I will remember! I <i>{must remember!}', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Cine/Ailith_Wild_30.ogg', '', 0, 0, '', 1, 0, 1, '[776]', NULL, 0, 0, '[]', 100),
(24232, 'Ailith_Wild_AfterEasterEggConvo_Random', '[]', 'Oh, hello. I didn''t notice you arrive.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_33_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24233, 'Ailith_Wild_AfterEasterEggConvo_2', '[]', 'Oh, hello. I didn''t notice you arrive.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_33_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
(24234, 'Ailith_Wild_AfterEasterEggConvo_3', '[]', 'That was quite the battle against the Hiveborn. Keep up the good work.', 'Audio/Dialogue/Leagues/BreachTwo/Ailith_Wild/Ailith_Wild_33_02.ogg', '', 0, 0, '', 1, 0, 1, '[771,773,774,775]', NULL, 0, 0, '[]', 100),
