(24602, 'Treasurer_Idle_5', '[]', 'Don''t you have somewhere to be?', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Idle_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[]', 100),
(24603, 'Treasurer_Idle_6', '[]', 'Don''t you have somewhere to be?', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Idle_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[]', 100),
(24604, 'Treasurer_Idle_7', '[]', 'Not that I don''t enjoy your company, but... aren''t you needed elsewhere?', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Idle_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[]', 100),
