(24609, 'Treasurer_Idle_12', '[]', 'The rolling stone gathers no moss.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Idle_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[]', 100),
(24610, 'Treasurer_Idle_13', '[]', 'You know what they say: the early bird catches the worm.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Idle_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[]', 100),
