(24616, 'Treasurer_Wild_Buy_Random', '[]', 'Spending so freely? Hm.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
