(24618, 'Treasurer_Wild_Buy_3', '[]', 'Spending so freely? Hm.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24619, 'Treasurer_Wild_Buy_4', '[]', 'Gold in, gold out.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
