(24621, 'Treasurer_Wild_Buy_6', '[]', 'Gold in, gold out.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24622, 'Treasurer_Wild_Buy_7', '[]', 'Keeps me busy, at least.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24623, 'Treasurer_Wild_Buy_8', '[]', 'Keeps me busy, at least.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24624, 'Treasurer_Wild_Buy_9', '[]', 'Keeps me busy, at least.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24625, 'Treasurer_Wild_Buy_10', '[]', 'Spending like a wastrel again, I see.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24626, 'Treasurer_Wild_Buy_11', '[]', 'Spending like a wastrel again, I see.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24627, 'Treasurer_Wild_Buy_12', '[]', 'Spending like a <i>{wastrel} again, I see.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24628, 'Treasurer_Wild_Buy_13', '[]', 'Ever the profligate, hm?', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24629, 'Treasurer_Wild_Buy_14', '[]', 'Ever the profligate, hm?', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24630, 'Treasurer_Wild_Buy_15', '[]', 'Ever the profligate, hm?', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Buy_05_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24631, 'Treasurer_Wild_Sell_Random', '[]', 'I wouldn''t have given you half that.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24632, 'Treasurer_Wild_Sell_2', '[]', 'I wouldn''t have given you half that.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24633, 'Treasurer_Wild_Sell_3', '[]', 'Ugh, I wouldn''t have given you half that.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24634, 'Treasurer_Wild_Sell_4', '[]', '<i>{Someone} paid more than that was worth.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24635, 'Treasurer_Wild_Sell_5', '[]', '<i>{Someone} paid more than that was worth.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24636, 'Treasurer_Wild_Sell_6', '[]', '<i>{Someone} paid more than that was worth.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24637, 'Treasurer_Wild_Sell_7', '[]', 'Surprising... but profit is profit.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24638, 'Treasurer_Wild_Sell_8', '[]', 'Surprising... but profit is profit.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24639, 'Treasurer_Wild_Sell_9', '[]', 'A fool and his coin... soon parted.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24640, 'Treasurer_Wild_Sell_10', '[]', 'A fool and his coin... soon parted.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24641, 'Treasurer_Wild_Sell_11', '[]', 'A fool and his coin... soon parted.', 'Audio/Dialogue/MTX/Hideout/NPCs/Treasurer/Treasurer/Treasurer_Wild_Sell_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[780]', NULL, 0, 0, '[24]', 100),
(24642, 'Chayula_A_01', '[]', 'Keep this secret... and I shall answer.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24643, 'Chayula_A_02', '[]', 'You... may call me ally... for now.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24644, 'Chayula_A_03', '[]', 'To exist... to continue.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24645, 'Chayula_A_04', '[]', 'We are the same... we are opposites.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_04.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24646, 'Chayula_A_05', '[]', 'None are safe... while the enemy rampages.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_05.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24647, 'Chayula_A_06', '[]', '... Xesht.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_06.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24648, 'Chayula_A_07', '[]', 'Unity of flesh... with no care as to how... or <i>{where}... it is found.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_07.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24649, 'Chayula_A_08', '[]', 'For now... we fight... the rest will become clear... in time.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_A_08.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24650, 'Chayula_B_01', '[]', 'Keep this secret... and I shall answer.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24651, 'Chayula_B_02', '[]', 'The Keepers know me... as the Benevolent Dreamer. ' || char(13) || '
' || char(13) || '
The enemy knows me... as the One Who Dreamt. ' || char(13) || '
' || char(13) || '
You... may call me ally... for now.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24652, 'Chayula_B_03', '[]', 'The willow bends with the storm... but too strong a gale... and it may snap.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24653, 'Chayula_B_04', '[]', 'Shattered hopes drift across the void... what is broken can never be repaired.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_04.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24654, 'Chayula_B_05', '[]', 'Two fates intertwine... not the unity desired, but the only unity at hand... the enemy is nigh.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_05.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24655, 'Chayula_B_06', '[]', 'The Hand closed at long last, bringing five into one... a flaw glimmered in a perfect crystal... the Dream ruptured, and the Dreamer was torn asunder... four became one, jagged and imbalanced... Xesht.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_06.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24656, 'Chayula_B_07', '[]', 'Endless rage and hunger... seeks only unity of flesh... with no care... how or where it is found.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_07.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24657, 'Chayula_B_08', '[]', 'Each day dawns red from the smoke of war. Two paths flank the same river... for now.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_B_08.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24658, 'Chayula_C_01', '[]', 'The Keepers know me... as the Benevolent Dreamer. ' || char(13) || '
' || char(13) || '
The enemy knows me... as the One Who Dreamt. ' || char(13) || '
' || char(13) || '
You... may call me ally... for now.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24659, 'Chayula_C_02', '[]', 'To exist... to preserve my essence... to endure what looms.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24660, 'Chayula_C_03', '[]', 'Broken bonds now ache like severed limbs.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24661, 'Chayula_C_04', '[]', 'We share the same fate... the enemy grows near.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_04.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24662, 'Chayula_C_05', '[]', 'Xoph... Esh... Tul... Uul-Netol... our melding... failed... I was torn asunder. Cast into the void between worlds. They... became Xesht.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_05.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24663, 'Chayula_C_06', '[]', 'Xesht is imbalanced... four minds sewn together, vying for dominance... filled with endless rage and hunger they do not understand. Seeking only unity of flesh... with no care... how or where it is found.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_06.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24664, 'Chayula_C_07', '[]', 'Fight. Ailith will aid you. She must continue her duties here... unburdened by the pain of truth. I must... regenerate. Keep our enemy at bay... and the path we share... shall <i>{remain} clear.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_C_07.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24665, 'Chayula_Cine_One', '[]', 'Ailith. This was never meant for your eyes.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_Cine_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24666, 'Chayula_Cine_Two', '[]', 'No. You... are not mindless... you died, long ago. I preserved your essence.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_Cine_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24667, 'Chayula_Cine_Three', '[]', 'I had every right. For you belong to me.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_Cine_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24668, 'Chayula_Cine_Four', '[]', 'So be it. I revoke my gift.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_Cine_04.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24669, 'Chayula_Cine_Five', '[]', 'I... would speak with you.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_Cine_05.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24670, 'Chayula_Glyph_Random', '[]', 'Silence.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24671, 'Chayula_Glyph_2', '[]', 'Silence.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24672, 'Chayula_Glyph_3', '[]', 'Silence.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24673, 'Chayula_Glyph_4', '[]', 'Quiet.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24674, 'Chayula_Glyph_5', '[]', 'Quiet.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24675, 'Chayula_Glyph_6', '[]', 'Quiet.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24676, 'Chayula_Glyph_7', '[]', 'Enough.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24677, 'Chayula_Glyph_8', '[]', 'Enough.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24678, 'Chayula_Glyph_9', '[]', 'Enough.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24679, 'Chayula_Glyph_10', '[]', 'No more.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24680, 'Chayula_Glyph_11', '[]', 'No more.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
