(24685, 'Chayula_Glyph_16', '[]', 'No.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Glyph/Chayula_Glyph_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
