(24687, 'Chayula_Truth_Random', '[]', 'I told you not to tell her.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24688, 'Chayula_Truth_2', '[]', 'I told you not to tell her.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24689, 'Chayula_Truth_3', '[]', 'I told you not to tell her.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24690, 'Chayula_Truth_4', '[]', 'The secret must be kept.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24691, 'Chayula_Truth_5', '[]', 'The secret must be kept.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
