(24693, 'Chayula_Truth_7', '[]', 'Do not violate our agreement.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24694, 'Chayula_Truth_8', '[]', 'Do not violate our agreement.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
