(24696, 'Chayula_Truth_10', '[]', 'There are consequences.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula/Chayula_Truth_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
