(24699, 'Chayula_A_Wild_01', '[]', 'Keep the secret... allies we remain.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_A_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24700, 'Chayula_A_Wild_02', '[]', 'Keep the secret... allies we remain.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_A_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24701, 'Chayula_A_Wild_03', '[]', 'Keep the secret... allies we remain.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_A_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24702, 'Chayula_B_Wild_01', '[]', 'Beware Xesht.... no dreams remain... only nightmares.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_B_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24703, 'Chayula_B_Wild_02', '[]', 'Beware Xesht.... no dreams remain... only nightmares.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_B_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24704, 'Chayula_C_Wild_01', '[]', 'Beware... Xesht.... prepare for an unyielding nightmare.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_C_Wild_01.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24705, 'Chayula_C_Wild_02', '[]', 'Beware... Xesht.... prepare for an unyielding nightmare.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_C_Wild_02.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24706, 'Chayula_C_Wild_03', '[]', 'Beware... Xesht.... prepare for an unyielding nightmare.', 'Audio/Dialogue/Leagues/BreachTwo/Chayula_Wild/Chayula_C_Wild_03.ogg', '', 0, 0, '', 1, 0, 1, '[779]', NULL, 0, 0, '[]', 100),
(24707, 'EshTul_Tul_Emerge_One', '[]', 'Wake. They are here.', 'Audio/Dialogue/Leagues/BreachTwo/Tul/TUL_Emerge_01.ogg', '', 0, 0, '', 0, 0, 1, '[781]', NULL, 0, 0, '[]', 100),
(24708, 'EshTul_Esh_Emerge_Two', '[]', 'The flesh is weak... I need time... ', 'Audio/Dialogue/Leagues/BreachTwo/Esh/ESH_Emerge_01.ogg', '', 0, 0, '', 0, 0, 1, '[782]', NULL, 0, 0, '[]', 100),
(24709, 'EshTul_Tul_Emerge_Three', '[]', 'Hah! Pathetic. I shall bury them!', 'Audio/Dialogue/Leagues/BreachTwo/Tul/TUL_Emerge_02.ogg', '', 0, 0, '', 0, 0, 1, '[781]', NULL, 0, 0, '[]', 100),
(24710, 'EshTul_Esh_Emerge_Four', '[]', 'Thought and motion nears...', 'Audio/Dialogue/Leagues/BreachTwo/Esh/ESH_Emerge_02.ogg', '', 0, 0, '', 0, 0, 1, '[782]', NULL, 0, 0, '[]', 100),
(24711, 'EshTul_Tul_EmergeShort', '[]', 'Chilling sorrow beckons!', 'Audio/Dialogue/Leagues/BreachTwo/Tul/TUL_EmergeShort.ogg', '', 0, 0, '', 1, 0, 1, '[781]', NULL, 0, 0, '[]', 100),
(24712, 'Esh_Skill_ChestSummon_Random', '[]', 'Ruin... within!', 'Audio/Dialogue/Leagues/BreachTwo/Esh/ESH_E_Skill_ChestSumm_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[782]', NULL, 0, 0, '[]', 100),
