(25374, 'Varashta_FarewellCallout_7', '[]', 'Slaughter them all!', 'Audio/Dialogue/Leagues/Mirage/Varashta_Wild/Varashta_FarewellCallout_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[788]', NULL, 0, 0, '[]', 100),
