(25514, 'Zarokh_Mirage_Anomaly_13', '[]', 'I have all eternity to grind you down.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Mirage_Anomaly_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[800]', NULL, 0, 0, '[31]', 100),
(25515, 'Zarokh_Mirage_Anomaly_14', '[]', 'I have never seen the Sun with my own eyes, but I soon will.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Mirage_Anomaly_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[800]', NULL, 0, 0, '[31]', 100),
(25516, 'Zarokh_Mirage_Anomaly_15', '[]', 'I have never seen the Sun with my own eyes, but I soon will.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Mirage_Anomaly_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[800]', NULL, 0, 0, '[31]', 100),
(25517, 'Zarokh_Mirage_Anomaly_16', '[]', 'I have never seen the Sun with my own eyes, but I soon will.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Mirage_Anomaly_05_03.ogg', '', 0, 0, '', 1, 0, 1, '[800]', NULL, 0, 0, '[31]', 100),
