(25939, 'VampireServant_Idle_11', '[]', 'Minkleton... pull your weight, or we''ll both be for the guillotine.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25940, 'VampireServant_Idle_12', '[]', 'Minkleton... pull your weight, or we''ll both be for the guillotine.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25941, 'VampireServant_Idle_13', '[]', 'Rest assured, master. Where we come from... a light bashing now and then is important for productivity.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_06_01.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25942, 'VampireServant_Idle_14', '[]', 'Rest assured, master. Where we come from... a light bashing now and then is important for productivity.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_06_02.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25943, 'VampireServant_Idle_15', '[]', 'Rest assured, master. Where we come from... a light bashing now and then is important for productivity.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_06_03.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25944, 'VampireServant_Idle_16', '[]', 'I''ve stared into the void and seen the darkness stare back... but in you, master... I see only light!', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_07_01.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25945, 'VampireServant_Idle_17', '[]', 'I''ve stared into the void and seen the darkness stare back... but in you, master... I see only light!', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_Idle_07_02.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[40]', 100),
(25946, 'VampireServant_IdleWetWilly_Random', '[]', 'Oof. Minkleton you little bastard...', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
(25947, 'VampireServant_IdleWetWilly_2', '[]', 'Oof. Minkleton you little bastard...', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
(25948, 'VampireServant_IdleWetWilly_3', '[]', 'Oof. Minkleton you little bastard...', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
(25949, 'VampireServant_IdleWetWilly_4', '[]', 'Not now, Minkleton... not, now.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
(25950, 'VampireServant_IdleWetWilly_5', '[]', 'Not now, Minkleton... not, now.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
(25951, 'VampireServant_IdleWetWilly_6', '[]', 'Ugh. Forgive us, master... he''s a pest.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
(25952, 'VampireServant_IdleWetWilly_7', '[]', 'Ugh. Forgive us, master... he''s a pest.', 'Audio/Dialogue/MTX/Hideout/NPCs/VampireServantMTX/VampireServant_Wild/VampireServant_IdleWetWilly_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[804]', NULL, 0, 0, '[]', 100),
