(26178, 'FinneganTrader_BuyingFromOthersTrader_Random', '[]', 'Who the blazes are you?! Oh. A buyer.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26179, 'FinneganTrader_BuyingFromOthersTrader_2', '[]', 'Who the blazes are you?! Oh. A buyer.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26180, 'FinneganTrader_BuyingFromOthersTrader_3', '[]', 'Who the blazes are you?! Oh! A buyer.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26181, 'FinneganTrader_BuyingFromOthersTrader_4', '[]', 'You want this? Give us a cuddle first. No? Fine!', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26182, 'FinneganTrader_BuyingFromOthersTrader_5', '[]', 'You want this? Give us a cuddle first. No? Fine.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26183, 'FinneganTrader_BuyingFromOthersTrader_6', '[]', 'You want this, aye? Give us a cuddle first. No? <i>{Fine.}', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26184, 'FinneganTrader_BuyingFromOthersTrader_7', '[]', 'This what you want, eh? Haha! Well, you can''t have it. Just kidding.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26185, 'FinneganTrader_BuyingFromOthersTrader_8', '[]', 'This what you want, eh? Haha! You can''t have it. Just kidding.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26186, 'FinneganTrader_BuyingFromOthersTrader_9', '[]', 'This what you want, eh? Haha! You can''t have it. <i>{I''m just kidding.}', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26187, 'FinneganTrader_BuyingFromOthersTrader_10', '[]', 'You sure you want this? Smells off. ''Course it could be me, mind you.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26188, 'FinneganTrader_BuyingFromOthersTrader_11', '[]', 'You sure you want this? Smells off. Could be me, mind you.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26189, 'FinneganTrader_BuyingFromOthersTrader_12', '[]', 'You sure you want this? Smells off. Could be me, mind you.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_BuyingFromOthersTrader_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[16]', 100),
(26190, 'FinneganTrader_PlaceOrder_Random', '[]', 'Yes, yes. I''ll try me best.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_PlaceOrder_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[34]', 100),
