(26192, 'FinneganTrader_PlaceOrder_3', '[]', 'Yes, yes. I''ll try me best.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_PlaceOrder_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[34]', 100),
(26193, 'FinneganTrader_PlaceOrder_4', '[]', 'You are a hard task master, you know?', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_PlaceOrder_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[34]', 100),
