(26195, 'FinneganTrader_PlaceOrder_6', '[]', 'You are a hard task master, y'' know?', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_PlaceOrder_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[34]', 100),
(26196, 'FinneganTrader_PlaceOrder_7', '[]', 'Fine. I''ll send the order.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_PlaceOrder_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[34]', 100),
