(26199, 'FinneganTrader_PlaceOrder_10', '[]', 'As you wish.', 'Audio/Dialogue/MTX/Hideout/NPCs/FleabagFinnegan/FleabagFinnegan/FinneganTrader_PlaceOrder_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[806]', NULL, 0, 0, '[34]', 100),
