Velka', 'Audio/Dialogue/Leagues/Deepwater/Velka_Glyph/Velka_Glyph_RaisingTheFirstBrineQueen.ogg', '', 0, 0, '', 1, 0, 1, '[809]', NULL, 0, 0, '[]', 100),
(26472, 'Velka_Taunt', '[]', 'Brines drown you! Soon, we shall own the seas once more!', 'Audio/Dialogue/Leagues/Deepwater/Velka_Taunt/Velka_Taunt_01.ogg', '', 0, 0, '', 1, 100000, 1, '[796]', NULL, 0, 0, '[]', 100),
(26473, 'Velka_Emerge_01_01', '[]', 'This salvage belongs to the Brinerot. Run for your life, if you know what''s good for ya.', 'Audio/Dialogue/Leagues/Deepwater/Velka_Combat/Velka_Emerge_01_01.ogg', '', 0, 0, '', 1, 100000, 1, '[810]', NULL, 0, 0, '[]', 100),
(26474, 'Velka_Emerge_01_02', '[]', 'This salvage belongs to the Brinerot. Run for your life, if you know what''s good for ya.', 'Audio/Dialogue/Leagues/Deepwater/Velka_Combat/Velka_Emerge_01_02.ogg', '', 0, 0, '', 1, 100000, 1, '[810]', NULL, 0, 0, '[]', 100),
(26475, 'Velka_Emerge_A', '[]', 'Ugh! You limey whelp. The Allflame is <i>{ours!}', 'Audio/Dialogue/Leagues/Deepwater/Velka_Combat/Velka_Emerge_A_01.ogg', '', 0, 0, '', 1, 0, 1, '[796]', NULL, 0, 0, '[]', 100),
(26476, 'Velka_Emerge_B_Random', '[]', 'I''ll tear it from your hide!', 'Audio/Dialogue/Leagues/Deepwater/Velka_Combat/Velka_Emerge_B_01.ogg', '', 0, 0, '', 1, 0, 1, '[810]', NULL, 0, 0, '[]', 100),
(26477, 'Velka_Emerge_B', '[]', 'I''ll tear it from your hide!', 'Audio/Dialogue/Leagues/Deepwater/Velka_Combat/Velka_Emerge_B_02.ogg', '', 0, 0, '', 1, 0, 1, '[810]', NULL, 0, 0, '[]', 100),
