(27057, 'Kulemak_Emerge', '[]', 'Yes... Rise, Zorath...', 'Audio/Dialogue/Leagues/Abyss/Kulemak/Kulemak_329_02.ogg', '', 0, 0, '', 1, 0, 1, '[815]', NULL, 0, 0, '[]', 100),
(27058, 'Kulemak_Death', '[]', 'Pity... He was... my most loyal servant...', 'Audio/Dialogue/Leagues/Abyss/Kulemak/Kulemak_329_03.ogg', '', 0, 0, '', 1, 0, 1, '[815]', NULL, 0, 0, '[]', 100),
