(27292, 'ZarokhBoss_Godvoice_Sekhema_Random', '[]', 'Be Indomitable, like Deshret.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Indomitable.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
(27293, 'ZarokhBoss_Godvoice_Sekhema_2', '[]', 'Be Fearless, like Aukuna.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Fearless.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
(27294, 'ZarokhBoss_Godvoice_Sekhema_3', '[]', 'Be Ambitious, like Asala.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Ambitious.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
(27295, 'ZarokhBoss_Godvoice_Sekhema_4', '[]', 'Be Wise, like Oyun.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Wise.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
(27296, 'ZarokhBoss_Godvoice_Sekhema_5', '[]', 'Be Radiant, like Solerai.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Radiant.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
(27297, 'ZarokhBoss_Godvoice_Sekhema_6', '[]', 'Be Enlightened, like Lundara.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Enlightened.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
(27298, 'ZarokhBoss_Godvoice_Sekhema_7', '[]', 'Be Resolute, like Varashta.', 'Audio/Dialogue/Leagues/Mirage/Zarokh/Zarokh_Godvoice_Sek_Resolute.ogg', '', 0, 0, '', 1, 500000, 1, '[800]', NULL, 0, 0, '[51]', 100),
