(27487, 'Cecilia_ReceivingBlessing_Random', '[]', 'Open yourself, for the love of Innocence can warm even the darkest of hearts.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_01.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27488, 'Cecilia_ReceivingBlessing_2', '[]', 'The road less traveled is often the exact path we ought to take.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_02.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27489, 'Cecilia_ReceivingBlessing_3', '[]', 'As sight withers, the vibrance of life becomes clearer than ever before.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_03.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27490, 'Cecilia_ReceivingBlessing_4', '[]', 'Fate moves unseen... rather than control it, we must embrace it.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_04.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27491, 'Cecilia_ReceivingBlessing_5', '[]', 'His love is upon you, whether you accept him, is up to you.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_05.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27492, 'Cecilia_ReceivingBlessing_6', '[]', 'In his light, we can see more. We can see beyond. We can see eternity.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_06.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27493, 'Cecilia_ReceivingBlessing_7', '[]', 'A new love grows on your horizon.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_07.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27494, 'Cecilia_ReceivingBlessing_8', '[]', 'Failure is but a stepping stone on your way to success.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_08.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27495, 'Cecilia_ReceivingBlessing_9', '[]', 'There are times we must forgive, and times we must forget.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_09.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27496, 'Cecilia_ReceivingBlessing_10', '[]', 'Oriath is the one true holy land. It must thrive again once more.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_10.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27497, 'Cecilia_ReceivingBlessing_11', '[]', 'Remain steadfast in your faith. Even in utter darkness, he will find you.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_11.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27498, 'Cecilia_ReceivingBlessing_12', '[]', 'The trials we face only mean to show us another side of our wanting selves.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_12.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27499, 'Cecilia_ReceivingBlessing_13', '[]', 'Tomorrow is not promised. But today is yours to own.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_13.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100);
INSERT INTO "NPCTextAudio" ("_row", "Id", "Characters", "Text", "Mono_AudioFile", "Stereo_AudioFile", "HasStereo", "__col6", "Video", "__col8", "__col9", "__col10", "NPCs", "NPCPortrait", "__col13", "__col14", "Cooldown", "__col16") VALUES
(27500, 'Cecilia_ReceivingBlessing_14', '[]', 'Step into the light. Bask in his glory. He is your beacon.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_14.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27501, 'Cecilia_ReceivingBlessing_15', '[]', 'Darkness grows like a weed. Root it out and cast it back to the void.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_15.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27502, 'Cecilia_ReceivingBlessing_16', '[]', 'Words can cut, it is true. But knives cut deeper. Resilience against those with sour tongues is your strongest ally.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_16.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27503, 'Cecilia_ReceivingBlessing_17', '[]', 'The light burns when we need it most. Stare deeply into His radiance.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_17.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27504, 'Cecilia_ReceivingBlessing_18', '[]', 'Art weaves his essence into reality. Covering us in a quilt of his abundant understanding.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_18.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27505, 'Cecilia_ReceivingBlessing_19', '[]', 'Embrace the unknown. Set out on an adventure. Dare to be more than you are today.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_19.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27506, 'Cecilia_ReceivingBlessing_20', '[]', 'The first Spring dawn offers a chance to become someone <i>{better}.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_20.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27507, 'Cecilia_ReceivingBlessing_21', '[]', 'The touch of a blade of grass, is sometimes all our soul truly needs.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_ReceivingBlessing_21.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27508, 'Cecilia_ReceivingBlessing_22', '[]', 'Blessings be upon you, traveller. Go well, into the light of the Pure One.', 'Audio/Dialogue/MTX/MapDevices/FountainOfCeciliaMapDevice/CeciliaMTX/Cecilia_OnFirstInteraction.ogg', '', 0, 0, '', 1, 100000, 1, '[817]', NULL, 0, 0, '[]', 100),
(27509, 'VaalTrader_Ipaatiki_BuySomething_Random', '[]', 'As expected...', 'Audio/Dialogue/Atlas/AtlasAnomalies/VaalTraderIpaatiki/VaalTrader_Ipaatiki_BuySomething_01.ogg', '', 0, 0, '', 1, 200000, 1, '[807]', NULL, 0, 0, '[]', 100),
(27510, 'VaalTrader_Ipaatiki_BuySomething_2', '[]', 'Make it so.', 'Audio/Dialogue/Atlas/AtlasAnomalies/VaalTraderIpaatiki/VaalTrader_Ipaatiki_BuySomething_02.ogg', '', 0, 0, '', 1, 200000, 1, '[807]', NULL, 0, 0, '[]', 100),
(27511, 'VaalTrader_Ipaatiki_BuySomething_3', '[]', 'It is your fate.', 'Audio/Dialogue/Atlas/AtlasAnomalies/VaalTraderIpaatiki/VaalTrader_Ipaatiki_BuySomething_03.ogg', '', 0, 0, '', 1, 200000, 1, '[807]', NULL, 0, 0, '[]', 100),
(27512, 'VaalTrader_Ipaatiki_BuySomething_4', '[]', 'Your choice is made.', 'Audio/Dialogue/Atlas/AtlasAnomalies/VaalTraderIpaatiki/VaalTrader_Ipaatiki_BuySomething_04.ogg', '', 0, 0, '', 1, 200000, 1, '[807]', NULL, 0, 0, '[]', 100),
(27513, 'VaalTrader_Ipaatiki_BuySomething_5', '[]', 'I did not foresee that.', 'Audio/Dialogue/Atlas/AtlasAnomalies/VaalTraderIpaatiki/VaalTrader_Ipaatiki_BuySomething_05.ogg', '', 0, 0, '', 1, 200000, 1, '[807]', NULL, 0, 0, '[]', 100),
(27514, 'VaalTrader_Ipaatiki_BuySomething_6', '[]', 'Your choice is made.', 'Audio/Dialogue/Atlas/AtlasAnomalies/VaalTraderIpaatiki/VaalTrader_Ipaatiki_BuySomething_06.ogg', '', 0, 0, '', 1, 200000, 1, '[807]', NULL, 0, 0, '[]', 100),
(27515, 'TimeRewindMTX_Random', '[]', 'Return to nothing.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_ReturnToNothing_01.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27516, 'TimeRewindMTX_2', '[]', 'Return to nothing.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_ReturnToNothing_02.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27517, 'TimeRewindMTX_3', '[]', 'Return to nothing.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_ReturnToNothing_03.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27518, 'TimeRewindMTX_4', '[]', 'Back you flow.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Back_01.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27519, 'TimeRewindMTX_5', '[]', 'Back you flow.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Back_02.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27520, 'TimeRewindMTX_6', '[]', 'Back you flow.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Back_03.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27521, 'TimeRewindMTX_7', '[]', 'Return!', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Return_01.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27522, 'TimeRewindMTX_8', '[]', 'Return!', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Return_02.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27523, 'TimeRewindMTX_9', '[]', 'Return!', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Return_03.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27524, 'TimeRewindMTX_10', '[]', 'Eternity awaits you.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Eternity_01.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27525, 'TimeRewindMTX_11', '[]', 'Eternity awaits you.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Eternity_02.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27526, 'TimeRewindMTX_12', '[]', 'Eternity awaits you.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_Eternity_03.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27527, 'TimeRewindMTX_13', '[]', 'Time unwinds.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_TimeUnwinds_01.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27528, 'TimeRewindMTX_14', '[]', 'Time unwinds.', 'Audio/Dialogue/MTX/Finishers/RareFinisherBTimeRewindMTX/Zarokh_TemporalRift_TimeUnwinds_02.ogg', '', 0, 0, '', 1, 0, 1, '[818]', NULL, 0, 0, '[56]', 100),
(27529, 'CorruptionTraderMan_OnApproach_First_One', '[]', 'Finally... we are free.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_First_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27530, 'CorruptionTraderMan_OnApproach_First_Two', '[]', 'We have spent too long beyond the infernal veil.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_First_02.ogg', '', 0, 0, '', 0, 0, 1, '[819]', NULL, 0, 0, '[]', 100),
(27531, 'CorruptionTraderMan_OnApproach_Subsequent_Random', '[]', 'You return.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27532, 'CorruptionTraderMan_OnApproach_Subsequent_2', '[]', 'You return.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27533, 'CorruptionTraderMan_OnApproach_Subsequent_3', '[]', 'You return.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27534, 'CorruptionTraderMan_OnApproach_Subsequent_4', '[]', 'Come closer.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27535, 'CorruptionTraderMan_OnApproach_Subsequent_5', '[]', 'Come closer.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_02_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27536, 'CorruptionTraderMan_OnApproach_Subsequent_6', '[]', 'Come closer.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_02_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27537, 'CorruptionTraderMan_OnApproach_Subsequent_7', '[]', 'Approach, human.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27538, 'CorruptionTraderMan_OnApproach_Subsequent_8', '[]', 'Approach, human.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27539, 'CorruptionTraderMan_OnApproach_Subsequent_9', '[]', 'Approach, human.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_03_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27540, 'CorruptionTraderMan_OnApproach_Subsequent_10', '[]', 'We sense your presence.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27541, 'CorruptionTraderMan_OnApproach_Subsequent_11', '[]', 'We sense your presence.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27542, 'CorruptionTraderMan_OnApproach_Subsequent_12', '[]', 'We sense your presence.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27543, 'CorruptionTraderMan_OnApproach_Subsequent_13', '[]', 'We''ve been waiting for you.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_05_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27544, 'CorruptionTraderMan_OnApproach_Subsequent_14', '[]', 'We''ve been waiting for you.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_OnApproach_Subsequent_05_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
