(27549, 'CorruptionTraderMan_Listing_Random', '[]', 'As you wish.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Listing_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[37]', 100),
(27550, 'CorruptionTraderMan_Listing_2', '[]', 'As you wish.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Listing_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[37]', 100),
(27551, 'CorruptionTraderMan_Listing_3', '[]', 'As you wish.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Listing_01_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[37]', 100),
(27552, 'CorruptionTraderMan_Listing_4', '[]', 'We will do our best.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Listing_02_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[37]', 100),
