(27663, 'CorruptionTraderMan_ShipmentReceived_10', '[]', 'Your offer was accepted.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_ShipmentReceived_04_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[35]', 100),
(27664, 'CorruptionTraderMan_ShipmentReceived_11', '[]', 'Your offer was accepted.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_ShipmentReceived_04_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[35]', 100),
(27665, 'CorruptionTraderMan_ShipmentReceived_12', '[]', 'Your offer was accepted.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_ShipmentReceived_04_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[35]', 100),
(27666, 'CorruptionTraderMan_Idle_Random', '[]', 'A thousand, thousand years we''ve waited. You are but a drop in our ocean.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27667, 'CorruptionTraderMan_Idle_2', '[]', 'Each dawn you wake is less than a blink of our eye.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27668, 'CorruptionTraderMan_Idle_3', '[]', 'Patience, patience, always patience. There is no end in sight. Still, we wait.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_03.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27669, 'CorruptionTraderMan_Idle_4', '[]', 'Here... you could join us. If you would... here.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_04.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27670, 'CorruptionTraderMan_Idle_5', '[]', 'In the veil, her voice is lost. We cannot remember her voice. Only... the imprint of sorrow.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_05.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27671, 'CorruptionTraderMan_Idle_6', '[]', 'It takes <i>{one} moment. A touch, and you could see beyond the veil.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_06.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27672, 'CorruptionTraderMan_Idle_7', '[]', 'You prefer the ignorance of your senses to the clarity of your mind. We understand.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_07.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27673, 'CorruptionTraderMan_Idle_8', '[]', 'Where are we? What is this... place?', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_08.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27674, 'CorruptionTraderMan_Idle_9', '[]', 'The void whispers, regret clawing at our ears. She will not stop...', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_09.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27675, 'CorruptionTraderMan_Idle_10', '[]', 'Do you hear her? She cries out... a lonely whine piercing death''s veil.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_10.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27676, 'CorruptionTraderMan_Idle_11', '[]', 'There is no end for ones such as we. Always the same. Always suffering.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderMan/CorruptionTraderMan_Idle_11.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[58]', 100),
(27677, 'CorruptionTraderWoman_OnApproach_First_One', '[]', 'Finally... we are free.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderWoman/CorruptionTraderWoman_OnApproach_First_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27678, 'CorruptionTraderWoman_OnApproach_First_Two', '[]', 'We have spent too long beyond the infernal veil.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderWoman/CorruptionTraderWoman_OnApproach_First_02.ogg', '', 0, 0, '', 0, 0, 1, '[819]', NULL, 0, 0, '[]', 100),
(27679, 'CorruptionTraderWoman_OnApproach_Subsequent_Random', '[]', 'You return.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderWoman/CorruptionTraderWoman_OnApproach_Subsequent_01_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
(27680, 'CorruptionTraderWoman_OnApproach_Subsequent_2', '[]', 'You return.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderWoman/CorruptionTraderWoman_OnApproach_Subsequent_01_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[57]', 100),
