(27807, 'CorruptionTraderWoman_ShipmentReceived_7', '[]', 'Fortune finds you.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderWoman/CorruptionTraderWoman_ShipmentReceived_03_01.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[35]', 100),
(27808, 'CorruptionTraderWoman_ShipmentReceived_8', '[]', 'Fortune finds you.', 'Audio/Dialogue/MTX/Hideout/NPCs/CorruptionTraderMTX/CorruptionTraderWoman/CorruptionTraderWoman_ShipmentReceived_03_02.ogg', '', 0, 0, '', 1, 0, 1, '[819]', NULL, 0, 0, '[35]', 100),
